window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-gastrologia-gas-2"]={"block":"medcurso:medcurso-gastrologia-gas-2","label":"Medcurso · GAS 2","count":440,"questions":[{"id":"medcurso-gastrologia-gas-2-345453","number":"345453","sourceNumber":"345453","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Quando a decisão de tratar com antibiótico a diarreia aguda no adulto for tomada,\ndeve-se dar preferência por ou\n. Assinale a alternativa que\npreencha correta e respectivamente as lacunas:","options":{"A":"Azitromicina / uma fluoroquinolona.","B":"Uma fluoroquinolona / sulfametoxazol-trimetropim.","C":"Azitromicina / metronidazol.","D":"Uma fluoroquinolona / metronidazol."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-345461","number":"345461","sourceNumber":"345461","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Homem de 52 anos é admitido no serviço de emergência com hematêmese e relato de\num episódio de melena. Há dois meses\napresentou episódio semelhante e desde então tem\npassado bem. A investigação àquela época foi negativa. Ele nega ingerir bebida alcoólica e uso de\nanti-inflamatórios. Ao exame aparenta palidez cutânea discreta; pressão arterial sistólica de 110\nmmHg quando deitado e 100 mmHg na posição ortostática; frequência cardíaca de 106 bpm, sem\noutros achados importantes. Exames complementares iniciais: hemoglobina = 9,8g/dL; ureia = 72\nmf/dL; creatinina = 1,1 mg/dL; endoscopia digestiva alta realizada no dia seguinte à admissão\nmostrou mucosas gástrica e duodenal de aspecto normal. O diagnóstico mais provável para esse\npaciente é:","options":{"A":"Úlcera de Curling.","B":"Úlcera de Cushing.","C":"Lesão de Dieulafoy.","D":"Síndrome de Mallory-Weiss."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-345502","number":"345502","sourceNumber":"345502","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Criança com 2 anos de vida apresenta quadro de diarreia há 3 meses, com fezes\nsemilíquidas, sem sangue e de odor fétido.\nSua mãe relata que esse quadro é intercalado com\nfezes pastosas. Nega febre e apresenta vômitos esporádicos. Ao exame: pálida (+), afebril, muito\nemagrecida (peso e altura abaixo do percentil 10). Pulmões sem ruídos adventícios, cardiovascular\nnormal, abdome distendido e sem visceromegalias. O pediatra levantou a hipótese diagnóstica de\nDoença Celíaca? Marque a alternativa CORRETA em relação aos exames que devem ser\nsolicitados para paciente com suspeita de doença celíaca:","options":{"A":"Anticorpo antiendomísio e anticorpo antitransglutaminase tecidual.","B":"Teste do suor com pilocarpina e iontoforese.","C":"IgE especifica para alimentos e Anticorpo antiendomísio.","D":"Curva de tolerância à lactose e anticorpo antitransglutaminase tecidual."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-345510","number":"345510","sourceNumber":"345510","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente sexo feminino, 63 anos, refere hematoquezia há 3 meses, sem outros\ncomemorativos. Das opções abaixo, qual a medida inicial mais adequada?","options":{"A":"Realizar toque retal.","B":"Solicitar colonoscopia.","C":"Solicitar retossigmoidoscopia.","D":"Dosagem de CEA (Antigo Carcinoembrionário)."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-345511","number":"345511","sourceNumber":"345511","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"O principal tratamento para o controle da hemorragia digestiva alta por ruptura das\nvarizes de esôfago na hipertensão portal esquistossomótica é:","options":{"A":"Tratamento endoscópico.","B":"Uso de terlipressina.","C":"Balão de Sengstaken-Blakemore.","D":"Propranolol."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-345517","number":"345517","sourceNumber":"345517","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Assinale a alternativa que apresenta as indicações formais para a exploração cirúrgica:","options":{"A":"Febre, dor abdominal e hérnia.","B":"Instabilidade hemodinâmica, peritonite, evisceração e empalamento.","C":"Choque, vômito e diarreia.","D":"Hematoma de parede, arritmia cardíaca e insuficiência respiratória."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-343847","number":"343847","sourceNumber":"343847","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A Síndrome de Peutz-Jeghers é caracterizada pela presença de pólipos\nHamartomatosos pelo trato gastrointestinal\nassociado a manchas escurecidas na mucosa dos\nlábios, cavidade oral e pele. Sobre ela é CORRETO dizer que:","options":{"A":"É Autossômica dominante.","B":"É Autossômica recessiva.","C":"Não apresenta relação com incidência de neoplasias sólidas.","D":"O diagnóstico é clínico com a determinação das lesões, tendo em vista ausência de teste\ncomplementar específico."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-283270","number":"283270","sourceNumber":"283270","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente de 69 anos, tabagista, comparece no consultório com queixa de astenia e\nprostração, refere ainda períodos de constipação intestinal com episódios alternados de diarreia.\nAo exame físico não se encontram grandes alterações. Em relação à conduta imediata assinale\nalternativa CORRETA.","options":{"A":"Solicitar tomografia abdominal.","B":"Solicitar ressonância magnética abdominal.","C":"Solicitar colonoscopia.","D":"Solicitar pesquisa de sangue oculto nas fezes."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-283273","number":"283273","sourceNumber":"283273","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente de 32 anos, do sexo masculino, comparece referindo diarreia volumosa,\nassociada à perda de sangue e muco,\nemagrecimento e lesão de borda anal. Assinale a alternativa\nCORRETA quanto ao diagnóstico mais provável.","options":{"A":"Síndrome de intestino irritável.","B":"Doença de Crohn.","C":"Retocolite ulcerativa.","D":"Colite amebiana."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-291772","number":"291772","sourceNumber":"291772","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente, sexo feminino, 69 anos de idade, é trazida por familiares ao Pronto Socorro\ncom queixa de dor abdominal, de forte\nintensidade, há uma hora. A paciente relata início súbito da\ndor, associada à náuseas, vômitos e hiporexia. A filha refere que a paciente é portadora de\nfibrilação atrial, hipertensão arterial e diabetes mellitus, fazendo uso regular das medicações. Ao\nexame, bom estado geral, FC: 108bpm, PA: 128x86mmHg, FR: 22ipm; ausculta respiratória:\nmurmúrios vesiculares bem distribuídos e sem ruídos adventícios; ausculta cardíaca: bulhas\narrítmicas, normofonéticas e com sopro sistólico em foco aórtico; FC: abdome um pouco distendido,\ncom ruídos hidroaéreos diminuídos, dor à palpação difusa, com descompressão brusca negativa.\n\nDe acordo com o caso descrito, Indique a principal suspeita diagnóstica que justifique o quadro\nclínico da paciente.","options":{"A":"Apendicite aguda.","B":"Pancreatite aguda.","C":"Isquemia mesentérica aguda.","D":"Diverticulite aguda no sigmoide."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-291773","number":"291773","sourceNumber":"291773","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente, sexo feminino, 69 anos de idade, é trazida por familiares ao Pronto Socorro\ncom queixa de dor abdominal, de forte\nintensidade, há uma hora. A paciente relata início súbito da\ndor, associada à náuseas, vômitos e hiporexia. A filha refere que a paciente é portadora de\nfibrilação atrial, hipertensão arterial e diabetes mellitus, fazendo uso regular das medicações. Ao\nexame, bom estado geral, FC: 108bpm, PA: 128x86mmHg, FR: 22ipm; ausculta respiratória:\nmurmúrios vesiculares bem distribuídos e sem ruídos adventícios; ausculta cardíaca: bulhas\narrítmicas, normofonéticas e com sopro sistólico em foco aórtico; FC: abdome um pouco distendido,\ncom ruídos hidroaéreos diminuídos, dor à palpação difusa, com descompressão brusca negativa.\n\nDe acordo com o caso descrito, Determine o exame complementar mais indicado para confirmar o\ndiagnóstico.","options":{"A":"Radiografia de abdome em decúbito dorsal e em ortostase.","B":"Ressonância nuclear magnética do abdome.","C":"Angiotomografia computadorizada do abdome.","D":"Videolaparoscopia."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-247138","number":"247138","sourceNumber":"247138","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Uma Paciente procura o ambulatório com queixas de diarreia crônica. Qual dos\nsintomas abaixo fala contra o diagnóstico de\ndiarreia funcionar (Síndrome do Intestino Irritável)?","options":{"A":"Piora da diarreia após as refeições (reflexo gastrocólico).","B":"Diarreia noturna que interfere no sono.","C":"Presença de muco transparente nas fezes.","D":"Cólica abdominais difusas e de forte intensidade.","E":"Nenhuma das alternativas."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-251862","number":"251862","sourceNumber":"251862","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A abordagem inicial de um paciente que se apresenta na sala de emergência com um\nquadro de hemorragia digestiva consiste em:","options":{"A":"Busca da etiologia do sangramento.","B":"Pesquisa de comorbidades importantes.","C":"Passagem de sonda nasogástrica calibrosa.","D":"Avaliação do estado volêmico."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-247160","number":"247160","sourceNumber":"247160","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Homem com 53 anos de idade, com diagnóstico de varizes de esôfago há 3 anos por\nhipertensão portal de etiologia esquistossomótica, deu entrada no pronto-socorro com história de\nvômitos com sangue em grande quantidade há 1 hora. Ao exame, PA = 70x40 mmHg, pulso fino de\n120bpm, pele fria, sudorese e confusão mental. A conduta recomendada é:","options":{"A":"Reposição volêmica vigorosa e passagem de balão esofagogástrico se mantiver instabilidade\nhemodinâmica.","B":"Endoscopia digestiva alta imediata com ligadura das varizes esofágicas.","C":"Reposição volêmica vigorosa seguida de laparotomia exploradora e realização da cirurgia de\nCrawford.","D":"Reposição volêmica vigorosa seguida de laparotomia exploradora e realização da cirurgia de\nWarren.","E":"Reposição volêmica, controle de Hb/Ht e endoscopia digestiva alta após 24 horas de\nestabilidade hemodinâmica."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-247217","number":"247217","sourceNumber":"247217","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Assinale a alternativa que responde CORRETAMENTE à pergunta abaixo. Qual a\nmelhor conduta no caso de apendalgite\n(epiploite) diagnosticada pré-operatoriamente por exame de\ntomografia computadorizada?","options":{"A":"Laparotomia exploradora.","B":"Tratamento conservador.","C":"Exérese Cirúrgica.","D":"Colectomia direita.","E":"Ressecção do ceco."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-251939","number":"251939","sourceNumber":"251939","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Nos casos de diverticulite aguda tipo Hinchey III, a conduta correta é:","options":{"A":"Colostomia em alça.","B":"Cirurgia de Hartmann.","C":"Ressecção do seguimento afetado e anastomose primária.","D":"Sutura do divertículo com drenagem."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-247220","number":"247220","sourceNumber":"247220","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Assinale a alternativa que responde CORRETAMENTE à pergunta a seguir. Qual\ndoença está associada ao câncer gástrico em aproximadamente 10% dos casos?","options":{"A":"Síndrome do câncer colorretal não poliposo.","B":"Doença de Crohn.","C":"Colite isquêmica.","D":"Adenocarcinoma de apêndice cecal.","E":"Adenocarcinoma de sigmoide."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-247222","number":"247222","sourceNumber":"247222","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Assinale a alternativa que responde CORRETAMENTE à pergunta abaixo. Em casos\nnão clássicos de apendicite aguda, qual o estudo\nde imagem de escolha?","options":{"A":"Ultrassonografia abdominal.","B":"Enema opaco.","C":"Raio X de abdome em decúbito lateral direito.","D":"Cintilografia com radionuclídeos.","E":"Tomografia computadorizada."},"answer":"E","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-251948","number":"251948","sourceNumber":"251948","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Nos tumores de reto baixo, como opções terapêuticas, exceto?","options":{"A":"Ablação por radiofrequência.","B":"Excisão trans-anal.","C":"Amputação abdomino-perineal do reto.","D":"Radioterapia e quimioterapia."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-251956","number":"251956","sourceNumber":"251956","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Sobre o quadro clínico da apendicite, qual a opção CORRETA?","options":{"A":"EAS com piúria afasta o diagnóstico.","B":"A dor é sempre localizada em fossa ilíaca direita.","C":"Pode cursar com diarréia em sua fase inicial.","D":"A USG sempre determina o diagnóstico."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-217648","number":"217648","sourceNumber":"217648","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Uma doença tem distribuição bimodal, afetando adultos jovens, com um segundo pico\nde incidência aos setenta anos de idade,\napresenta prevalência particularmente aumentada em\njudeus asquenazes e acomete mais comumente o íleo distal e o cólon proximal. O tabagismo\nassocia-se a um pior prognóstico. Os anti-inflamatórios não hormonais parecem estar associados a\nexacerbações. A doença caracterizada no texto acima é:","options":{"A":"Doença de Whipple.","B":"Linfoma de Hodgkin.","C":"Câncer intestinal.","D":"Doença de Crohn."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-217670","number":"217670","sourceNumber":"217670","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente, sexo feminino, 37 anos, refere história de diarreia com mais de 6 evacuações\nao dia, presença de sangue e muco, períodos\nde exacerbação e remitência, com evolução de um\nano. Há 3 meses, apresenta piora progressiva do quadro, associado a dor abdominal difusa, tipo\ncólica, urgência, tenesmo e perda ponderal de 13 kg neste período. Qual a conduta inicial no\nambulatório?","options":{"A":"Solicitar enema opaco.","B":"Realizar retossigmoidoscopia.","C":"Solicitar colonoscopia.","D":"Realizar toque retal."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-182616","number":"182616","sourceNumber":"182616","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente com diarreia crônica com exame de fezes (parasitológico) e teste fecal para\nantígenos de Giardia lamblia negativos, com teste para gordura fecal anormal, sem nenhuma pista\nsobre a etiologia e com teste da D-xilose anormal. Qual a próxima etapa de investigação para\nmelhor elucidação etiológica?","options":{"A":"Coprocultura.","B":"Biópsia de intestino delgado.","C":"Tomografia para avaliar pâncreas.","D":"Teste de secretina."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-183226","number":"183226","sourceNumber":"183226","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Em relação à isquemia mesentérica aguda, assinale a alternativa INCORRETA.","options":{"A":"Digitálicos e diuréticos podem ser fatores predisponentes para a isquemia arterial não-oclusiva.","B":"A isquemia segmentar focal ocorre em, aproximadamente, 30% dos casos de isquemia\nmesentérica e tem melhor prognóstico que a Trombose Mesentérica.","C":"A dor abdominal é de início súbito, de forte intensidade e está presente em 75% a 98% dos\ncasos de isquemia mesentérica aguda.","D":"A taxa de mortalidade é de 70% a 90%.","E":"As angiografias, especialmente a aortografia e a arteriografia seletiva das artérias mesentéricas\nsuperior e inferior, representam os\nmétodos propedêuticos de escolha."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-183186","number":"183186","sourceNumber":"183186","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Em relação ao câncer colorretal, assinale a alternativa INCORRETA:","options":{"A":"Aproximadamente, 1% a 3% dos carcinomas colorretais são relacionados às síndromes\npolipoides hereditárias, tais como. Polipose\nadenomatosa familiar, Síndrome de Gardner de Turcot.","B":"Não há evidências suficientes de que a dieta rica em gordura animal esteja relacionada com o\naumento da incidência de câncer colorretal.","C":"Mulheres com história pessoal de câncer de mama, endométrio e ovário têm maior probabilidade\nde desenvolver câncer colorretal que o restante da\npopulação normal.","D":"Aproximadamente, 10% dos indivíduos com câncer colorretal desenvolvem metástases\nperitoneais.","E":"Segundo a classificação TNM, pode-se dizer que um indivíduo com adenocarcinoma de colo que\natinge até a camada muscular e apresenta comprometimento linfonodal encontra-se em estágio III."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-182645","number":"182645","sourceNumber":"182645","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente masculino, 67 anos, refere dor em FIE e febre baixa com evolução de 8 dias.\nAo exame físico: dor à palpação superficial e profunda em FIE com descompressão brusca\ndolorosa. Qual a hipótese diagnóstica?","options":{"A":"Diverticulite colônica.","B":"Infarto entero-mesentérico.","C":"Doença inflamatória pélvica.","D":"Doença inflamatória intestinal."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-182625","number":"182625","sourceNumber":"182625","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente masculino, 17 anos, refere dor em FE com evolução de 7 dias, associado à\nfebre de 39ªC e há 2 dias apresenta flexão antálgica de MIE. Qual a melhor hipótese diagnóstica?","options":{"A":"Piomiosite de músculo psoas esquerdo.","B":"Pionefrose esquerda.","C":"Diverticulite colônica.","D":"Apendagite epiplóica."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-182606","number":"182606","sourceNumber":"182606","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente masculino, 56 anos, refere dor periumbilical com evolução de 24 horas,\nassociado à parada de eliminação de flatos e\nfezes. Revisão de sistemas: aparelho gastrointestinal\n\n- Constipação intestinal crônica. Exame físico: mucosas úmidas. AC: RCR 2T, FC: 110 bpm, PA:\n100X80 mmHg. RX de abdome com imagem em \"grão de café\". Qual a hipótese diagnóstica?","options":{"A":"Intussuscepção intestinal.","B":"Volvo de sigmoide.","C":"Obstrução por fitobezoar.","D":"Obstrução por tumor."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-159123","number":"159123","sourceNumber":"159123","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A hemorragia digestiva alta (HDA) é um das principais causas de óbito entre os\nindíviduos com cirrose hepática. Diante de um\nquadro de HDA em um paciente portador de cirrose\nhepática pelo vírus da hepatite B, que após o manejo inicial estabiliza hemodinamicamente, você\nindica primariamente o tratamento:","options":{"A":"Endoscópico com escleroterapia.","B":"Endoscópico com ligadura elástica.","C":"Medicamentoso com terlipressina, um vasoconstritor esplâncnico.","D":"Medicamentoso com propranolol, um betabloqueador."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-159067","number":"159067","sourceNumber":"159067","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Em relação às doenças inflamatórias intestinais, é CORRETO afirmar que:","options":{"A":"A colite ulcerativa é uma doença de acometimento transmural do intestino, cursando, portanto,\ncom manifestações de obstrução intestinal.","B":"O acometimento da mucosa na doença de Crohn é contínuo, enquanto na colite ulcerativa há\náreas de mucosa doente intercaladas com mucosa normal.","C":"O achado de reto com mucosa normal à colonoscopia, praticamente, exclui do diagnóstico de\ncolite ulcerativa.","D":"A evolução para carcinoma colorretal é mais comum na doença de Crohn que na colite\nulcerativa."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-159110","number":"159110","sourceNumber":"159110","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente sexo feminino, 60 anos, refere hematoquezia há 3 meses, sem outros\ncomemorativos. Das opções abaixo, qual a medida inicial mais adequada?","options":{"A":"Solicitar colonoscopia.","B":"Solicitar retossigmoidoscopia.","C":"Dosagem de CEA (Antígeno Carcinoembrionário).","D":"Realizar toque retal."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-159054","number":"159054","sourceNumber":"159054","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente sexo masculino, 68 anos. Há 4 dias refere dor abdominal intensa, que\naumentou progressivamente. Ao exame físico apresenta\nRCI em 2 tempos, abdome difusamente\ndoloroso com descompressão brusca dolorosa, ruídos hidro-aéreos diminuídos. Qual a melhor\nhipótese diagnóstica?","options":{"A":"Obstrução intestinal.","B":"Apendicite aguda.","C":"Diverticulite.","D":"Infarto entero-mesentérico."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-369536","number":"369536","sourceNumber":"369536","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Diante do caso clínico e dos exames complementares, indique a principal suspeita\ndiagnóstica para este paciente:","options":{"A":"Gastroenterocolite aguda.","B":"Diverticulite aguda de Meckel.","C":"Apendicite aguda.","D":"Diverticulite aguda cecal."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-369537","number":"369537","sourceNumber":"369537","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente, sexo masculino, 12 anos de idade, é levado ao Pronto-Socorro pela genitora,\ncom queixa de dor abdominal difusa há dois\ndias. O paciente refere, também, hiporexia, alguns\nepisódios de náuseas, vômitos e diarreia. Ao exame físico, bom estado geral, temperatura axilar:\n38.2°C, FC: 82 bpm, PA: 110x74mmHg; ausculta cardíaca e respiratória sem alterações; abdome\num pouco distendido, ruídos hidroaéreos presentes, flácido, dor à palpação profunda de\nmesogástrio e fossa ilíaca direita, com sinais de irritação peritoneal. Os exames laboratoriais\niniciais\napresentaram Hb: 13g/dL, Ht: 36%, Leucócitostotais: 12500células/mm³ (Bastões: 5%). Indique a\nconduta mais adequada neste momento:","options":{"A":"Iniciar antibioticoterapia e observação em leito de enfermaria.","B":"Solicitar tomografia computadorizada de abdome com contraste.","C":"Coletar hemoculturas, iniciar antibioticoterapia e internar em Unidade de Terapia Intensiva.","D":"Realizar laparotomia por incisão oblíqua em fossa ilíaca direita."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-372093","number":"372093","sourceNumber":"372093","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente masculino, 57 anos, procura atendimento médico queixando-se de dor e\ndistensão abdominal há 1 dia. Queixa-se de dor\nabdominal difusa, tipo cólica, iniciada há 1 dia,\nprogressiva, sem melhora com analgésicos e antiespasmódicos, associada a vários episódios de\nvômitos. Nega trauma. Nega episódios prévios. Nega cirurgias abdominais. Nega perda de peso ou\nsangramento nas fezes. É portador de cardiomiopatia dilatada, hipertenso e diabético.\n\nEletrocardiograma evidencia taquicardia sinusal, com bloqueio divisional ântero-superior. Ao exame\nfísico, encontra-se em regular estado geral, desidratado, taquipneico, anictérico, acianótico,\nafebril.\nEstável hemodinamicamente. Abdome com ruídos presentes e aumentados, distendido, doloroso à\npalpação superficial e profunda, sem sinais de irritação peritoneal. Foi submetido aos exames\nradiológicos abaixo. Assinale a principal hipótese diagnóstica.","options":{"A":"Isquemia mesentérica.","B":"Úlcera duodenal perfurada e bloqueada.","C":"Neoplasia de cólon esquerdo.","D":"Volvo de sigmoide."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-2/372093.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-372094","number":"372094","sourceNumber":"372094","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente masculino, 57 anos, procura atendimento médico queixando-se de dor e\ndistensão abdominal há 1 dia. Queixa-se de dor\nabdominal difusa, tipo cólica, iniciada há 1 dia,\nprogressiva, sem melhora com analgésicos e antiespasmódicos, associada a vários episódios de\nvômitos. Nega trauma. Nega episódios prévios. Nega cirurgias abdominais. Nega perda de peso ou\nsangramento nas fezes. É portador de cardiomiopatia dilatada, hipertenso e diabético.\n\nEletrocardiograma evidencia taquicardia sinusal, com bloqueio divisional ântero-superior. Ao exame\nfísico, encontra-se em regular estado geral, desidratado, taquipneico, anictérico, acianótico,\nafebril.\nEstável hemodinamicamente. Abdome com ruídos presentes e aumentados, distendido, doloroso à\npalpação superficial e profunda, sem sinais de irritação peritoneal. Foi submetido aos exames\nradiológicos abaixo. Assinale a conduta imediata mais adequada para este caso.","options":{"A":"Colostomia de urgência.","B":"Retossigmoidoscopia descompressiva.","C":"Procedimento de Hartmann.","D":"Anticoagulação plena."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-2/372094.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-343200","number":"343200","sourceNumber":"343200","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Jovem, masculino, há 3 dias com hiporexia, náuseas, desconforto epigástrico,\nqueixando-se hoje de piora da dor, mais\nlocalizada em fossa ilíaca direita associada a 2 picos de\nfebre aferida. Ao exame físico: bom estado geral, corado, hidratado, eupneico, anictérico. Exame\nfísico cardiopulmonar normal, exceto leve taquicardia. Ruídos abdominais presentes, sem\nalterações na inspeção, porém com dor a palpação de fossa ilíaca direita. Sinal de Blumberg\npresente. Foi submetido a exames laboratoriais que resultaram em um escore de Alvarado de 10\npontos. Não há exames de imagem disponível no serviço. A conduta mais adequada é:","options":{"A":"Transferência para realizar tomografia de abdome.","B":"Cirurgia.","C":"Alta com sintomáticos.","D":"Anti-inflamatório não hormonal e reavaliação em 48h."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-343201","number":"343201","sourceNumber":"343201","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente feminina, 80 anos, internada com diverticulite aguda, submeteu-se à\ntomografia de abdome com contraste endovenoso\nque evidenciou processo inflamatório colônico\ncom divertículos e a presença de coleção pélvica bloqueada. Trata-se de diverticulite aguda,\nclassificada por Hinchey (clássica) em grau:","options":{"A":"II","B":"III","C":"IV","D":"IV"},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-315163","number":"315163","sourceNumber":"315163","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Dentre os achados abaixo, o mais típico da isquemia intestinal aguda é:","options":{"A":"O vômito.","B":"A taquicardia.","C":"A diarréia sanguinolenta.","D":"A dor desproporcional ao exame físico.","E":"A febre."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-315170","number":"315170","sourceNumber":"315170","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"O tratamento inicial a ser instituído em paciente com Volvo de sigmóide é:","options":{"A":"Colonoscopia.","B":"Cirurgia de Hartmann.","C":"Sigmoidostomia.","D":"Transversostomia.","E":"Colectomia total."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-313436","number":"313436","sourceNumber":"313436","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Dentre as alternativas apresentadas abaixo, assinale a correta em relação às\ntransfusões de concentrado de hemácias em pacientes com hemorragia digestiva.","options":{"A":"Em caso de pacientes com perdas sanguíneas contínuas e pacientes com quadro de choque\nhemorrágico, pode-se indicar a transfusão de concentrado de hemácias, mesmo sem ter o valor da\nhemoglobina dosada.","B":"Em pacientes com perdas sanguíneas e evolução para choque hemorrágico, necessita-se do\nvalor de hemoglobina abaixo do corte de 7 a 8g/dL, mesmo que haja perdas contínuas de sangue,\npara se indicar a transfusão.","C":"Não há necessidade de transfusão de concentrado de hemácias nas hemorragias digestivas, em\nespecial nas hemorragias digestivas altas.","D":"Atualmente, o valor de corte de hemoglobina que indica transfusão de concentrado de hemácias\né de 10g/dL, sem importar a situação."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-314211","number":"314211","sourceNumber":"314211","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"O terço distal do cólon transverso, o cólon descendente e o reto evoluem da cissura do\nintestino posterior e são supridos pela:","options":{"A":"Artéria mesentérica superior.","B":"Tronco celíaco.","C":"Artéria mesentérica inferior.","D":"Artéria cólica direita."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-314212","number":"314212","sourceNumber":"314212","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Embora tenha elasticidade, uma dilatação aguda do ceco que pode ser medida por uma\nradiografia abdominal simples pode resultar em necrose isquêmica e perfuração da parede\nintestinal. Neste contexto, o valor de corte, em centímetros, para este tipo de lesão é:","options":{"A":"6 cm","B":"8 cm","C":"10 cm","D":"12 cm"},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-314213","number":"314213","sourceNumber":"314213","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Representa a fusão do mesentério com o peritônio posterior. Este ponto de referência\nperitoneal sutil serve ao cirurgião como um guia para a mobilização do cólon e do mesentério do\nretroperitônio. É um marco anatômico importante na dissecção do cólon.","options":{"A":"A linha branca de Toldt.","B":"Ponto de Sudeck.","C":"Ponto de Griffith.","D":"Ponto de Cattel."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-314214","number":"314214","sourceNumber":"314214","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A fáscia endopélvica é uma camada espessa do peritônio parietal que reveste as\nparedes e o assoalho da pelve. Seu\nconhecimento anatômico é importante pois sua secção durante\na dissecção por ocasião de uma abordagem abdominal proporciona o acesso para a pelve\n\nretro-retal. A dissecção entre as fáscias acompanha os princípios da oncologia cirúrgica e minimiza\nos riscos de lesões vasculares e neurais. A\nfigura abaixo traz a representação da fáscia\nendopélvica. Assinale a alternativa com a correta associação.","options":{"A":"A: Fáscia pré-sacral, B: Fáscia retossacral, C: Fáscia de Denonvilliers.","B":"A: Fáscia de Denonvilliers, B: Fáscia retossacral, C: Fáscia pré-sacral.","C":"A: Fáscia de Denonvilliers, B: Fáscia pré-sacral, C: Fáscia retossacral.","D":"A: Fáscia pré-sacral, B: Fáscia de Denonvilliers, C: Fáscia retossacral."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-2/314214.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-314215","number":"314215","sourceNumber":"314215","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"O assoalho ou diafragma pélvico é constituído um grupo muscular que, em conjunto,\nformam o elevador do ânus. São eles:","options":{"A":"Músculos pubococcígeos, ileococcígeos e puborretais.","B":"Músculos pubococcígeos, piriformes e puborretais.","C":"Músculos pubococcígeos, puborretais e psoas maior.","D":"Músculos pubococcígeos, obturadores internos e puborretais."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-314216","number":"314216","sourceNumber":"314216","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"É causa mais comum de fístula entre o cólon e a bexiga:","options":{"A":"Câncer.","B":"Retocolite ulcerativa.","C":"Diverticulite aguda do cólon.","D":"Doença de Crohn."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-314217","number":"314217","sourceNumber":"314217","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente em investigação de diverticulite aguda é submetida à tomografia de abdome\nabaixo. Além de podermos classificar a gravidade da doença, nota-se também uma complicação\nlocal. Trata-se da:","options":{"A":"Fístula cutânea.","B":"Pneumoperitônio.","C":"Fístula vesical.","D":"Fístula vaginal."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-2/314217.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-314218","number":"314218","sourceNumber":"314218","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"É uma condição na qual o intestino sofre uma torção sobre o seu eixo mesentérico,\numa situação que resulta em obstrução parcial ou\ncompleta do lúmen intestinal e de um grau\nvariável do seu suprimento sanguíneo. A condição geralmente afeta o cólon.","options":{"A":"Hérnia interna.","B":"Volvo.","C":"Intussuscepção.","D":"Estenose colônica."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-314219","number":"314219","sourceNumber":"314219","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"O achado tomográfico de uma dobra mesentérica típica, representado na imagem\nabaixo, pode ser encontrada mais frequentemente em qual patologia abaixo?","options":{"A":"Apendicite aguda.","B":"Pancreatite aguda.","C":"Adenite mesentérica.","D":"Volvo de sigmoide."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-2/314219.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-314220","number":"314220","sourceNumber":"314220","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Na constituição da parede do trato gastrointestinal, é o segmento da parede em que é\npoupado de lesão inflamatória nos pacientes\ncom colite ulcerativa:","options":{"A":"Mucosa.","B":"Submucosa.","C":"Muscular.","D":"Epitélio."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-279041","number":"279041","sourceNumber":"279041","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Podemos classificar o abdome agudo, do ponto de vista sindrômico, em 4 grandes\ntipos. Das alternativas abaixo assinale\naquela que não representa uma classificação sindrômica do\nabdome agudo.","options":{"A":"Hemorrágico.","B":"Inflamatório.","C":"Perfurativo.","D":"Parasitário."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-283727","number":"283727","sourceNumber":"283727","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente, sexo feminino, 69 anos de idade, é trazida por familiares ao pronto-socorro\ncom queixa de dor abdominal, de forte\nintensidade, há uma hora. A paciente relata inicio súbito da\ndor, associada à náuseas, vômitos e hiporexia. A filha refere que a paciente é portadora de\nfibrilação atrial, hipertensão arterial e diabetes mellitus, fazendo uso regular das medicações. Ao\nexame, bom estado geral, FC: 108 bp, PA: 128 x 86 mmHg, FR: 22 ipm; ausculta respiratória:\nmurmúrios vesiculares bem distribuídos e sem ruídos adventícios, ausculta cardíaca: bulhas\narrítmicas, normofonéticas e com sopro sistólico em foco aórtico; FC: abdome um pouco distendido,\ncom ruídos hidroaéreos diminuídos, dor a palpitação difusa, com descompressão brusca negativa.\nDe acordo com o caso descrito. Indique a principal suspeita diagnóstica que justifique o quadro\nclínico da paciente.","options":{"A":"Apendicite aguda.","B":"Pancreatite aguda.","C":"Isquemia mesentérica aguda.","D":"Diverticulite aguda no sigmoide."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-283728","number":"283728","sourceNumber":"283728","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente, sexo feminino, 69 anos de idade, é trazida por familiares ao pronto-socorro\ncom queixa de dor abdominal, de forte\nintensidade, há uma hora. A paciente relata inicio súbito da\ndor, associada à náuseas, vômitos e hiporexia. A filha refere que a paciente é portadora de\nfibrilação atrial, hipertensão arterial e diabetes mellitus, fazendo uso regular das medicações. Ao\nexame, bom estado geral, FC: 108 bp, PA: 128 x 86 mmHg, FR: 22 ipm; ausculta respiratória:\nmurmúrios vesiculares bem distribuídos e sem ruídos adventícios, ausculta cardíaca: bulhas\narrítmicas, normofonéticas e com sopro sistólico em foco aórtico; FC: abdome um pouco distendido,\ncom ruídos hidroaéreos diminuídos, dor a palpitação difusa, com descompressão brusca negativa.\nDe acordo com o caso descrito. Determine o exame complementar mais indicado para confirmar o\ndiagnóstico.","options":{"A":"Radiografia de abdome em decúbito dorsal e em ortostase.","B":"Ressonância nuclear magnética do abdome.","C":"Angiotomografia computadorizada do abdome.","D":"Videolaparoscopia."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-283729","number":"283729","sourceNumber":"283729","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente, sexo feminino, 69 anos de idade, é trazida por familiares ao pronto-socorro\ncom queixa de dor abdominal, de forte\nintensidade, há uma hora. A paciente relata inicio súbito da\ndor, associada à náuseas, vômitos e hiporexia. A filha refere que a paciente é portadora de\nfibrilação atrial, hipertensão arterial e diabetes mellitus, fazendo uso regular das medicações. Ao\nexame, bom estado geral, FC: 108 bp, PA: 128 x 86 mmHg, FR: 22 ipm; ausculta respiratória:\nmurmúrios vesiculares bem distribuídos e sem ruídos adventícios, ausculta cardíaca: bulhas\narrítmicas, normofonéticas e com sopro sistólico em foco aórtico; FC: abdome um pouco distendido,\ncom ruídos hidroaéreos diminuídos, dor a palpitação difusa, com descompressão brusca negativa.\nDe acordo com o caso descrito. Indique o tratamento mais adequado que deve ser instituído.","options":{"A":"Internação em unidade de terapia intensiva e suporte clínico.","B":"Embolectomia arterial com cateter de Fogarty.","C":"Apendicectomia por videolaparoscopia.","D":"Retossigmoidectomia por laparotomia."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-278625","number":"278625","sourceNumber":"278625","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente de 6 anos de idade submetido à laparotomia de urgência devido a abdome\nagudo. Foi constatada, no intraoperatório,\napendicite grau IV; realizada apendicectomia, e o\npaciente foi encaminhado para UTI Pediátrica. Qual seria a complicação mais comum esperada\nnesse paciente?","options":{"A":"Abscesso.","B":"Infecção em ferida operatória.","C":"Íleo paralitico.","D":"Obstrução intestinal."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-278098","number":"278098","sourceNumber":"278098","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Assinale a alternativa que apresenta os defeitos estruturais dos enterócitos na Displasia\nEpitelial Intestinal.","options":{"A":"Formação de vacúolos nos enterócitos e desarranjo da arquitetura as microvilosidades.","B":"Estrutura da membrana basal dos enterócitos com anomalias na composição da lamilina e dos\nproteoglicanos.","C":"Mutações no transportador glicose/ sódio.","D":"Alterações do bordo em escova, acarretando perda da função absortiva."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-279055","number":"279055","sourceNumber":"279055","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"É responsável pela irrigação do intestino anterior:","options":{"A":"Tronco celíaco.","B":"Artéria mesentérica anterior.","C":"Artéria mesentérica superior.","D":"Artéria mesentérica inferior."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-280425","number":"280425","sourceNumber":"280425","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Masculino, 91 anos, em internação prolongada com uso de várias classes de\nantibióticos. Há 3 dias apresentou febre e diarreia com eliminação de sangue, pus e muco,\nassociada a distensão abdominal sem sinais de peritonite. A principal hipótese diagnóstica é:","options":{"A":"Retocolite ulcerativa idiopática.","B":"Diverticulite complicada.","C":"Atelectasia.","D":"Colite pseudomembranosa."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-280426","number":"280426","sourceNumber":"280426","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"É responsável pela etiologia da colite pseudomembranosa:","options":{"A":"Escherichia coli","B":"Acinetobacter sp.","C":"Clostridium difficile","D":"Klebsiella pneumoniae"},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-279057","number":"279057","sourceNumber":"279057","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"O ceco é um segmento dilatado em forma de saco do cólon proximal. Embora tenha\nelasticidade, uma dilatação aguda do ceco pode resultar em necrose isquêmica e perfuração da\nparede intestinal. O diâmetro limítrofe notado em radiografia simples de abdome para\ndesenvolvimento de tais repercussões é:","options":{"A":"Diâmetro maior de 6 cm.","B":"Diâmetro maior de 10 cm.","C":"Diâmetro maior de 12 cm.","D":"Diâmentro maior de 20 cm."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-280427","number":"280427","sourceNumber":"280427","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"É a anomalia congênita mais encontrada no intestino delgado e geralmente está\nlocalizada na borda antimesentérica do íleo,\n45 a 60 cm proximal à válvula ileocecal e resulta de um\nfechamento incompleto do conduto onfalomesentérico, ou vitelínico.","options":{"A":"Dívertículo de Zenker.","B":"Divetículo de Meckel.","C":"Mucocele ileal.","D":"Úraco persistente."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-279058","number":"279058","sourceNumber":"279058","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A artéria retal inferior é um ramo da artéria pudenda que é, ela mesma, um ramo mais\ndistal da:","options":{"A":"Artéria ilíaca interna.","B":"Artéria ilíaca externa.","C":"Artéria mesentérica superior.","D":"Artéria mesentérica inferior."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-278639","number":"278639","sourceNumber":"278639","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Em geral, os tumores carcinoides raramente são malignos e se originam das células\nprecursoras neuroendócrinas e podem se apresentar em qualquer lugar do corpo humano. A\nlocalização mais comum é o trato gastrointestinal, abrangendo mais da metade de todos os\ncarcinoides. Assinale a alternativa com os locais mais comuns do trato gastrointestinal:","options":{"A":"Intestino delgado, reto e o apêndice cecal.","B":"Intestino grosso, reto, estômago.","C":"Esôfago, intestino delgado e reto.","D":"Reto, pâncreas e mesentério."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-279059","number":"279059","sourceNumber":"279059","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente de 72 anos, masculino, dá entrada em pronto-socorro com queixa de dor\nepigástrica súbita há 2 horas, de forte\nintensidade, com irradiação para o dorso e tórax, associada a\nvômitos e sudorese fria. Nega febre. Relata piora progressiva neste intervalo de tempo e nega\nmelhora com analgesia simples. É portador de hipertensão arterial, sistêmica, fibrilação atrial\ncrônica, diabetes melitus tipo II, artrite reumatoide e é tabagista. Em uso contínuo de losartana\n(100mg/dia), hidroclorotiazida (25mg/dia), varfarina (5mg/dia), metoprolol (50mg/dia), metformina\n(1000mg/dia), e diclofenaco (75mg/dia). Ao exame físico encontra-se em regular estado geral,\nsudoreico, taquicárdico, descorado, desidratado, anictérico, acianótico, afebril. Bulhas cardíacas\narrítmicas, sem sopros audíveis, pulsos periféricos cheios e amplos. Murmúrio vesicular reduzido\nbilateralmente, sem ruídos adventícios. Abdome com ruídos, flácido, doloroso difusamente, sem\nsinais de irritação peritoneal. Sinal de Murphy negativo. Sinal de Jobert negativo. Sinais vitais da\nadmissão: pressão arterial: 170/110 mmHg (membro superior direito) e 180/110 mmHg (membro\nsuperior esquerdo), frequência respiratória: 22 irpm, frequência cardíaca: oscilando entre 100 e 120\nbpm, saturação periférica de oxigênio: 93%, temperatura axilar: 37.3ºC. Foi submetido à radiografia\nde tórax e eletrocardiograma abaixo. A principal hipótese diagnóstica é:","options":{"A":"Síndrome coronariana aguda.","B":"Dissecção aguda de aorta.","C":"Abdome agudo perfurativo.","D":"Tromboembolismo venoso"},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-2/279059.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-279060","number":"279060","sourceNumber":"279060","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"É responsável pela irrigação do intestino posterior:","options":{"A":"Tronco celíaco.","B":"Artéria mesentérica anterior.","C":"Artéria mesentérica superior.","D":"Artéria mesentérica inferior."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-279061","number":"279061","sourceNumber":"279061","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"É um ramo proximal da artéria mesentérica superior. Ela geralmente se divide em\nramos direito e esquerdo, que irrigam o cólon transverso proximal e distal, respectivamente.\nTrata-se da:","options":{"A":"Artéria mesentérica anterior.","B":"Artéria ileocecocólica.","C":"Artéria cólica direita.","D":"Artéria cólica média."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-279062","number":"279062","sourceNumber":"279062","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Conecta diretamente as porções proximais às porções da artéria mesentética superior\ncom a artéria mesentética inferior e pode\nservir como um canal vital quando uma ou outra destas\nartérias está ocluída. Ela também é conhecida como artéria mesentérica sinuosa e tem um\ntamanho bastante variável. Trata-se da:","options":{"A":"Arcada de Riolan.","B":"Arcada Sudeck.","C":"Arcada de Ghriffts.","D":"Arcada celíaca."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-279065","number":"279065","sourceNumber":"279065","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Irriga todo o intestino delgado, dando 12 a 20 ramos jejunais e ileais para a esquerda e\naté três ramos colônicos principais à direita. Trata-se da:","options":{"A":"Artéria celíaca.","B":"Artéria mesentérica anterior.","C":"Artéria mesentérica superior.","D":"Artéria mesentérica inferior."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-279066","number":"279066","sourceNumber":"279066","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente de 23 anos, há 3 dias com dor abdominal já localizada em fossa ilíaca direita,\nassociada a hiporexia, sem melhora com uso de dipirona. Nega náusea. Nega febre. Relata piora\nprogressiva da dor, que se intensificou na data de hoje. Conta que já apresentou 2 episódios\nsemelhantes ao quadro clínico atual, porém apresentaram resolução espontânea. Nega sintomas\nurinários. Ao exame físico: bom estado geral, corado, hidratado, eupneico, anictérico, acianótico,\nafebril. Aparelho cardiopulmonar sem alterações. Abdome com ruídos presentes, flácido,\ndepressível, doloroso em fossa ilíaca direita, sem sinais de irritação peritoneal. Sinal de\nBlumberg,\nRovsing, Dunphy: todos negativos. Apresenta discreta leucocitose em hemograma, exame de urina\nnormal. Foi submetido a tomografia de abdome e pelve com contraste (figura abaixo). Assinale a\ncorreta.","options":{"A":"A principal hipótese diagnóstica é de diverticulite aguda de cólon direito, com coleção adjacente\nao cólon apontada pela seta branca.","B":"A principal hipótese diagnóstica é abscesso de músculo psoas direito, com coleção adjacente ao\nmúsculo apontada pela seta branca.","C":"A principal hipótese diagnóstica é apendicite aguda complicada, com coleção e pequena\nperfuração representada pela letra C na tomografia.","D":"A principal hipótese diagnóstica é apendicite aguda, com presença de fecalito apontado pela\nseta branca."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-2/279066.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-279067","number":"279067","sourceNumber":"279067","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A ilustração abaixo mostra a secção da artéria apendicular, passo fundamental no\nprocesso de apendicectomia. A artéria apendicular, mais frequentemente é ramo indireto da(o):","options":{"A":"Tronco celíaco.","B":"Artéria mesentérica inferior.","C":"Artéria mesentérica superior.","D":"Artéria ilíaca interna."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-2/279067.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-278648","number":"278648","sourceNumber":"278648","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"As imagens abaixo foram realizadas na investigação de uma paciente feminina, 24\nanos de idade, com queixas de dor e\ndistensão abdominal pós-prandial e eructações frequentes há\naproximadamente 2 meses. Relata perda ponderal importante neste mesmo período. As imagens\nevidenciam compressão da terceira porção duodenal entre a artéria mesentérica superior e a aorta,\ncom consequente dilatação a montante. Trata-se da:","options":{"A":"Síndrome de Wilkie.","B":"Síndrome de Foley.","C":"Síndrome de Prader Willi.","D":"Síndrome de Cocket."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-2/278648.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-279068","number":"279068","sourceNumber":"279068","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A fáscia retossacra é uma condensação espessada da fáscia endopélvica conectando a\nfáscia pré-sacra à fáscia própria no nível de S4 e estendendo-se até o anel anorretal. É um ponto\nde referência cirúrgico importante, e a sua secção durante a dissecção por ocasião de uma\nabordagem abdominal proporciona o acesso para a pelve retro-retal. Tal fáscia é conhecida como:","options":{"A":"Fáscia dos Denonvilliers.","B":"Fáscia de Waldeyer.","C":"Fáscia de Blumberg.","D":"Fáscia de Houston."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-279069","number":"279069","sourceNumber":"279069","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"É responsável pela irrigação do intestino médio:","options":{"A":"Tronco celíaco.","B":"Artéria mesentérica anterior.","C":"Artéria mesentérica superior.","D":"Artéria mesentérica inferior."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-279070","number":"279070","sourceNumber":"279070","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Origina-se da aorta no nível de L2 a L3, aproximadamente 3 cm acima da bifurcação\naórtica. A artéria cólica esquerda é seu\nramo mais proximal, irrigando a porção distal do cólon\ntransverso, a flexura esplênica e o cólon descendente. Trata-se da:","options":{"A":"Artéria mesentérica inferior.","B":"Artéria mesentérica superior.","C":"Artéria mesentérica médica.","D":"Artéria celíaca."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-280440","number":"280440","sourceNumber":"280440","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente hepatopata crônico, é transferido ao pronto-atendimento com história de\nmelena há 4 dias e hematêmese volumosa\nhoje. Sinais vitais da admissão em sala de emergência:\npressão arterial: 60 x 40 mmHg, frequência cardíaca: 145 bpm, frequência respiratória: 20 irpm,\nsaturação de oxigênio periférica: 92%, temperatura axilar: 38,5o. Ao exame físico: mal estado geral,\ndescorado, ictérico, acianótico, ictérico, febril. Ausculta pulmonar com crepitações em ambas as\nbases pulmonares, bulhas cardíacas rítmicas e taquicárdicas, abafadas, sem sopros audíveis.\n\nAbdome com ruídos, levemente distendido, ascítico, presença de circulação colateral, doloroso à\npalpação difusa, com sinais de irritação peritoneal. As principais hipóteses diagnósticas são:","options":{"A":"Hemorragia digestiva alta (varicosa ou ulcerosa), abdome agudo perfurativo, peritonite\nbacteriana.","B":"Hemorragia digestiva alta (varicosa apenas), abdome agudo perfurativo, peritonite bacteriana.","C":"Hemorragia digestiva baixa, abdome agudo perfurativo, peritonite bacteriana.","D":"Hemorragia digestiva baixa (varicosa), abdome agudo perfurativo, peritonite bacteriana."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-249278","number":"249278","sourceNumber":"249278","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A Doença de Crohn (DC) é uma doença intestinal inflamatória que pode aceitar como\ncorreto o seguinte item:","options":{"A":"Mais de 6 semanas de diarreia é o prazo sugerido como critério para diferenciação com diarreia\naguda infecciosa.","B":"Menos de 6 semanas de diarreia é o prazo sugerido como critério para diferenciação com\ndiarreia aguda infecciosa.","C":"Mais de 6 meses de diarreia é o prazo sugerido como critério para diferenciação com diarreia\naguda infecciosa.","D":"A diarreia não é sugerida como critério para diferenciação com diarreia aguda infecciosa."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-249378","number":"249378","sourceNumber":"249378","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Na Doença de Crohn (DC) a atividade aumentada da enzima tiopurinametiltransferase\nTPMT leva a baixa formação de 6-tioguanina e a\naumento dos níveis de 6-metilmercaptopurina,\ncom consequentes redução da eficácia e maior risco de hepatotoxicidade da azatioprina. Podemos\nconcordar com o item:","options":{"A":"Adição de alopurinol, um inibidor daxantinaoxidase capaz de desviar o metabolismo da\nazatioprina para a produção de 6- tioguanina,\nlevou a significativo aumento da atividade da doença,\npossibilitando a redução da dose de corticosteroide, sem aumento de toxicidade hepática.","B":"Adição de alopurinol, um inibidor daxantinaoxidase capaz de desviar o metabolismo da\nazatioprina para a produção de 6- tioguanina,\nlevou a significativa diminuição da atividade da\ndoença, possibilitando a redução da dose de corticosteroide, sem aumento de toxicidade hepática.","C":"Adição de alopurinol, um inibidor daxantinaoxidase capaz de desviar o metabolismo da\nazatioprina para a produção de 6- tioguanina,\nlevou a significativa diminuição da atividade da\ndoença, possibilitando a aumento da dose de corticosteroide, sem aumento de toxicidade hepática.","D":"Adição de alopurinol, um inibidor daxantinaoxidase capaz de desviar o metabolismo da\nazatioprina para a produção de 6- tioguanina, levou a significativa diminuição da atividade da\ndoença, possibilitando a redução da dose de corticosteroide, mas também com aumento de\ntoxicidade hepática."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-249279","number":"249279","sourceNumber":"249279","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A Doença de Crohn (DC) é uma doença intestinal inflamatória sendo sua localização\napenas no esôfago é rara. Somente 5% dos pacientes com essa doença têm acometimento\ngastroduodenal. Podemos apenas aceitar que:","options":{"A":"Quando ocorre acometimento do estômago e do duodeno, justifica-se o uso de fármacos que\nnão alterem agressão péptica, sendo indicados\ninibidores da bomba de prótons.","B":"Quando ocorre acometimento do estômago e do duodeno, justifica-se o uso de fármacos que\ndiminuam a agressão péptica, não sendo indicados inibidores da bomba de prótons.","C":"Quando ocorre acometimento do estômago e do duodeno, justifica-se o uso de fármacos que\ndiminuam a agressão péptica, sendo indicados inibidores da bomba de Na e K.","D":"Quando ocorre acometimento do estômago e do duodeno, justifica-se o uso de fármacos que\ndiminuam a agressão péptica, sendo indicados inibidores da bomba de prótons."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-249380","number":"249380","sourceNumber":"249380","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A Doença de Crohn (DC) é uma doença inflamatória intestinal, que apresenta exame\nhistopatológico pode indicar o seguinte item:","options":{"A":"Acometimento transmural (quando da análise de ressecções cirúrgicas), padrão segmentar e\npresença de granulomas não caseosos.","B":"Acometimento transmural (quando da análise de ressecções cirúrgicas), padrão não segmentar\ne presença de granulomas não caseosos.","C":"Acometimento transmural (quando da análise de ressecções cirúrgicas), padrão segmentar e\npresença de granulomas caseosos.","D":"Acometimento transmural (quando da análise de ressecções cirúrgicas), padrão generalizado e\nausência de granulomas não caseosos."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-249282","number":"249282","sourceNumber":"249282","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Na Doença de Crohn (DC), pacientes em uso da associação azatioprina e alopurinol\ndevem ser monitorizados laboratorialmente em\nrelação às contagens de leucócitos, semanalmente\nno primeiro mês e quinzenalmente no segundo mês. Está correto que:","options":{"A":"Ocorrendo leucopenia, recomenda-se o aumento da dose de azatioprina, de acordo com a\ngravidade do caso.","B":"Ocorrendo leucopenia, recomenda-se a redução da dose de azatioprina (50% da dose atual) ou\nmesmo a sua suspensão, de acordo com a\ngravidade do caso.","C":"Ocorrendo leucopenia, recomenda-se a redução da dose de azatioprina (50% da dose atual)\nindependente da gravidade do caso.","D":"Ocorrendo leucopenia, recomenda-se a redução da dose de azatioprina (50% da dose atual),\nmas nunca sua suspensão, independente da gravidade do caso."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-249384","number":"249384","sourceNumber":"249384","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Na Doença de Crohn (DC) nos casos em que não há resposta inicial com o uso em\ndoses adequadas de azatioprina, recomenda-se a\nassociação de azatioprina mais alopurinol.\n\nAssim, está correto que:","options":{"A":"Alternativamente, caso o médico assistente prefira ou o paciente cortiço dependente tenha\nhistória de efeito adverso ou hipersensibilidade à azatioprina, pode-se usar metotrexato por via\nintramuscular (IM) semanal.","B":"Alternativamente, caso o médico assistente prefira ou o paciente cortiço dependente tenha\nhistória de efeito adverso ou hipersensibilidade à azatioprina, pode-se usar metotrexato por via\nintramuscular (IM) mensal.","C":"Alternativamente, caso o médico assistente prefira ou o paciente cortiço dependente tenha\nhistória de efeito adverso ou\nhipersensibilidade à azatioprina, pode-se usar metotrexato por via EV\nquinzenal.","D":"Alternativamente, caso o médico assistente prefira ou o paciente cortiço dependente não tenha\nhistória de efeito adverso ou hipersensibilidade à azatioprina, pode-se usar metotrexato por via\nintramuscular (IM) semanal."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-249386","number":"249386","sourceNumber":"249386","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A Doença de Crohn (DC) é uma doença inflamatória intestinal, podemos apenas aceitar\ncomo adequado o item:","options":{"A":"A endoscopia digestiva baixa (colonoscopia) com biópsias de sítios distintos, incluindo o íleo,\né o\npior método para o diagnóstico e revela tipicamente lesões ulceradas.","B":"A endoscopia digestiva baixa (colonoscopia) com biópsias de sítios distintos, incluindo o íleo,\né o\nmétodo preferencial para o diagnóstico e revela tipicamente lesões ulceradas, entremeadas de\náreas com mucosa normal, acometimento focal, assimétrico e descontínuo.","C":"A endoscopia digestiva baixa (colonoscopia) com biópsias de sítios distintos, incluindo o íleo,\né o\nmétodo preferencial para o diagnóstico e revela tipicamente lesões ulceradas, não entremeadas de\náreas com mucosa normal, acometimento generalizado, simétrico e descontínuo.","D":"A endoscopia digestiva baixa (colonoscopia) com biópsias de sítios distintos, incluindo o íleo,\né o\nmétodo preferencial para o diagnóstico e revela raramente lesões ulceradas, e nunca entremeadas\nde áreas com mucosa normal, acometimento focal, assimétrico e contínuo."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-231356","number":"231356","sourceNumber":"231356","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Assinale a alternativa correta: De acordo com o Consenso Roma IV, o período em que\nos sintomas devem estar ocorrendo para que se\nfaça o diagnostico de Dispepsia Funcional é:","options":{"A":"Sintomas tenham iniciado a pelo menos 12 meses e ativos nos últimos 3 meses","B":"Seis meses com sintomas presentes e que tenham melhorados nos últimos 3 meses.","C":"Sintomas tenham iniciado há pelo menos 6 meses do diagnostico e presentes nos últimos 3\nmeses.","D":"Sintomas tenham iniciado há 12 meses e presentes nos últimos 2 meses.","E":"Nenhuma das alternativas acima."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-252888","number":"252888","sourceNumber":"252888","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente, sexo masculino, 65 anos de idade, é levado ao Pronto Socorro por familiares\ncom queixa de dor abdominal e lombar direita,\nhá três dias. Refere febre, náuseas e hiporexia. O\npaciente relata também irradiação da dor para região inguinal e membro inferior direito. Familiares\ninformam que o paciente tratou erisipela em membro inferior esquerdo, há sete dias. Paciente\nportador de diabetes Mellitus, em uso regular de hipoglicemiantes orais. Ao exame físico, bom\nestado geral, corado, hidratado, Temperatura axilar: 38,3ºC, FC: 88bpm, PA: 116x74mmHG, FR:\n18imp; ausculta cardíaca e respiratória sem alterações; abdome plano, flácido, ruídos hidroaéreos\npresentes, dor leve e difusa à palpação profunda e dor à punho percussão da região lombar direita;\ndor à extensão e rotação interna da articulação coxofemoral direita. Diante dos dados clínicos,\nindique a principal suspeita diagnóstica.","options":{"A":"Apendicite aguda.","B":"Diverticulite aguda.","C":"Abscesso de músculo psoas direito.","D":"Pielonefrite aguda direita."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-252889","number":"252889","sourceNumber":"252889","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente, sexo masculino, 65 anos de idade, é levado ao Pronto Socorro por familiares\ncom queixa de dor abdominal e lombar direita,\nhá três dias. Refere febre, náuseas e hiporexia. O\npaciente relata também irradiação da dor para região inguinal e membro inferior direito. Familiares\ninformam que o paciente tratou erisipela em membro inferior esquerdo, há sete dias. Paciente\nportador de diabetes Mellitus, em uso regular de hipoglicemiantes orais. Ao exame físico, bom\nestado geral, corado, hidratado, Temperatura axilar: 38,3ºC, FC: 88bpm, PA: 116x74mmHG, FR:\n18imp; ausculta cardíaca e respiratória sem alterações; abdome plano, flácido, ruídos hidroaéreos\npresentes, dor leve e difusa à palpação profunda e dor à punho percussão da região lombar direita;\ndor à extensão e rotação interna da articulação coxofemoral direita. Identifique o exame\ncomplementar mais importante para a elucidação diagnóstica.","options":{"A":"Análise urinária.","B":"Ultrassonografia de abdome.","C":"Videolaparoscopia.","D":"Tomografia computadorizada de abdome."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-252890","number":"252890","sourceNumber":"252890","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente, sexo masculino, 65 anos de idade, é levado ao Pronto Socorro por familiares\ncom queixa de dor abdominal e lombar direita,\nhá três dias. Refere febre, náuseas e hiporexia. O\npaciente relata também irradiação da dor para região inguinal e membro inferior direito. Familiares\ninformam que o paciente tratou erisipela em membro inferior esquerdo, há sete dias. Paciente\nportador de diabetes Mellitus, em uso regular de hipoglicemiantes orais. Ao exame físico, bom\nestado geral, corado, hidratado, Temperatura axilar: 38,3ºC, FC: 88bpm, PA: 116x74mmHG, FR:\n18imp; ausculta cardíaca e respiratória sem alterações; abdome plano, flácido, ruídos hidroaéreos\npresentes, dor leve e difusa à palpação profunda e dor à punho percussão da região lombar direita;\ndor à extensão e rotação interna da articulação coxofemoral direita. Após a confirmação do\ndiagnóstico, indique a conduta terapêutica mais adequada nesse caso.","options":{"A":"Laparotomia exploradora.","B":"Terapia antibiótica e observação.","C":"Drenagem percutânea guiada por imagem e terapia antibiótica.","D":"Videolaparoscopia."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-231375","number":"231375","sourceNumber":"231375","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente de 65 anos com diverticulite perfurada de sigmoide com peritonite difusa. Qual\no procedimento cirúrgico mais adequado:","options":{"A":"Laparostomia com colorrafia","B":"Laparotomia com colorrafia","C":"Operação de Hartman","D":"Operação de Duhamel","E":"Colostomia do transverso"},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-249413","number":"249413","sourceNumber":"249413","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente de 53 anos, admitido em pronto-socorro por vômitos há 3 dias, associado à\ndor abdominal importante, em cólicas, que vem\nse tornando progressiva. Nega febre. Queixa-se de\nhiporexia. Nega sintomas urinários. Ao exame físico, apresenta-se regular estado geral,\ndesidratado, discretamente taquicárdico, com exame físico cardiopulmonar normal. Ruídos\nreduzidos em todo o abdome, doloroso difusamente, distendido, sem sinais de irritação peritoneal.\nFoi submetido à radiografia abaixo, com achado pouco comum destacado pela seta. Hemograma\ncom discreta leucocitose, função renal normal. Análise de exame de urina normal. A principal\nhipótese diagnóstica é:","options":{"A":"Volvo de sigmóide.","B":"Úlcera perfurada.","C":"Íleo Biliar.","D":"Ureterolitíase."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-2/249413.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-249217","number":"249217","sourceNumber":"249217","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Dividimos o abdome em 9 regiões, delimitadas por linhas imaginárias. Assinale a\nalternativa que corresponde corretamente o número à região indicada.","options":{"A":"1 ? flanco direito","B":"2 ? mesogástrio","C":"8 ? hipocôndrio medial","D":"7 ? fossa ilíaca direita"},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-2/249217.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-249425","number":"249425","sourceNumber":"249425","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A causa mais comum de fístula colo-vesical é:","options":{"A":"Doença de Crohn.","B":"Câncer Colorretal.","C":"Retocolite ulcerativa.","D":"Diverticulite aguda."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-249235","number":"249235","sourceNumber":"249235","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Das lesões polipóides abaixo, a que apresenta maior potencial de degeneração maligna\né:","options":{"A":"Adenoma tubular.","B":"Pólipo hiperplásico.","C":"Adenoma viloso.","D":"Hamartoma."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-249236","number":"249236","sourceNumber":"249236","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente de 8 anos, trazido pela mãe com queixas de perda ponderal e dor abdominal\ndifusa há 7 meses. Queixa-se também de\nepisódios esporádicos e auto-limitados de diarreia, sem\nfebre, sem eliminação de muco, pus ou sangue. AO exame físico: emagrecido, descorado, abdome\nlevemente distendido, doloroso difusamente, sem sinais de peritonite, com presença de abscesso\nperianal. A principal hipótese diagnóstica é:","options":{"A":"Doença de Crohn.","B":"Alergia a proteína do leite de vaca.","C":"Doença de Hirchsprung.","D":"Pancreatite crônica auto-imune juvenil."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-219847","number":"219847","sourceNumber":"219847","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"KRH, 32 anos, sexo feminino, do lar, que está na 28ª semana de gestação, inciou dor\nabdominal periumbilical e náuseas há 12 horas. A dor permaneceu difusa e surgiu febre de 37,8°C.\nAo exame físico, encontra-se corada, hidratada, anictérica e febril (37,7°C). Útero acima da\ncicatriz\numbilical, palpação pouco dolorosa sem reação peritoneal à descompressão. Exames laboratoriais\nmostraram anemia discreta (11,8 g/dl) com 16.500 leucócitos/mm³ com 70% de bastões. PCR de\n17 mg/dl. Em relação a este caso, assinale a alternativa CORRETA:","options":{"A":"A ausência de reação peritoneal se deve em parte à elevação do útero que alterna a posição do\napêndice.","B":"A extensão da propedêutica com Ressonância Magnética está contraindicada pelo risco de\nmalformação fetal e abortamento.","C":"Contagem de leucócitos superior a 14.000 céls/mm³ confirma quadro de peritonite difusa.","D":"Em caso de indicação cirúrgica está contraindicada a vida laparoscópica."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-212151","number":"212151","sourceNumber":"212151","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente de 62 anos, masculino, obeso e sedentário, diabético, etilista e tabagista, com\nquadro de astenia e perda ponderal significativa. História prévia de sangramento retal e\nconstipação intestinal. Ao exame físico, apresentava-se em regular estado geral, eupneico,\nhidratado, hipocorado (2+/4+), frequência cardíaca = 84 bpm, abdome flácido, doloroso à palpação\nprofunda no quadrante inferior direito, sem sinais de irritação peritoneal. Inspeção e toque retal\nevidenciaram coxins hemorroidários, presença de fezes na ampola, sem lesões. Foi submetido a\nretossigmoidoscopia, que não evidenciou nenhuma alteração. Sobre o caso apresentado, assinale\na alternativa CORRETA.","options":{"A":"A colonoscopia está indicada.","B":"O paciente em questão apresenta, apenas, dois fatores de risco para neoplasia.","C":"A dosagem do antígeno carcinoembrionário (CEA) está indicado para rastreamento e\ndiagnóstico.","D":"Caso o diagnóstico do paciente seja neoplasia colorretal, está indicado PET-CT de rotina para\nesse paciente.","E":"O diagnóstico de câncer colorretal pode ser excluído, visto que o sangramento retal está\njustificado pela doença hemorroidária."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-212162","number":"212162","sourceNumber":"212162","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"O estudo da anatomia e semiologia é de grande importância para as correlações\nmédico-cirúrgicas. Dessa forma, o diagnóstico de\ndiversas patologias cirúrgicas pode ser possível a\npartir do exame clínico e físico. Além disso, o entendimento da anatomia servirá de base para\nrealização adequada do procedimento cirúrgico. Em relação à correlação entre anatomia e/ou\nsemiologia e algumas patologias cirúrgicas, assinale a alternativa correta.","options":{"A":"Um paciente jovem que apresente abaulamento na região inguinal e exteriorização do conteúdo\nherniário pelo anel inguinal externo possui o diagnóstico de hérnia inguinal direta e o tratamento\nindicado deverá ser realizado pela técnica de Bassini.","B":"Durante a colecistectomia videolaparoscópica para o tratamento de colelitíase sintomática,\npode-se identificar o triângulo cistohepático (ou\ntriângulo de Calot) que é delimitado pelo ducto\nhepático comum, o ducto cístico e a vesícula biliar.","C":"O apêndice vermiforme mede cerca de 8 cm de comprimento, sua localização mais frequente é\nretrocecal e, quando está inflamado, a presença do sinal de Blumberg sugere irritação do peritônio\nparietal e o provável diagnóstico de apendicite\n\naguda.","D":"Em um paciente estável hemodinamicamente que apresenta hemorragia digestiva alta e exame\nendoscópico com identificação de uma úlcera duodenal, o provável vaso responsável pelo\nsangramento será a artéria gastroduodenal e o tratamento será cirúrgico.","E":"Paciente portador de neoplasia de esôfago médio, durante uma esofagectomia, optou-se pelo\nestômago como órgão para a reconstrução do trânsito a partir da confecção de um tubo gástrico\npara anastomose com esôfago proximal. Dessa forma, deve-se ter cuidado especial em preservar a\nartéria gástrica esquerda que será responsável por nutrir o tubo gástrico."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-212174","number":"212174","sourceNumber":"212174","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"É contraindicação absoluta a exame de endoscopia digestiva baixa:","options":{"A":"hemoglobina de 8.","B":"uso de ácido acetil salicílico.","C":"antecedente recente de abdome agudo obstrutivo.","D":"deixar de obter termo de consentimento livre e esclarecido.","E":"lesão em cólon transverso que ocupa mais de 80% da luz do órgão."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-219864","number":"219864","sourceNumber":"219864","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"RDD, 30 anos, sexo masculino, casado, balconista, iniciou alteração do hábito intestinal\ne sangramento nas fezes. A retossigmoidoscopia\nmostrou mamilos hemorroidários de IIIo grau e\nvários pólipos no reto. Foi realizada colonoscopia que mostrou inúmeros pólipos em todo o intestino\ngrosso. O exame de fundo de olho confirmou hipertrofia congênita do epitélio pigmentar da retina\n(CHRDE). Apresentava também osteoma de face (mandibular) e cistos epidérmicos em região\n\npré-tibial, mas não sabe precisar a época de seus aparecimentos. Foi solicitada EDA e está\nproposta a realização de colectomia total. Em\nrelação aos desdobramento deste caso, assinale a\nalternativa INCORRETA:","options":{"A":"A realização de coletomia total, previne o aparecimento de câncer ligado à polipose\nadenomatosa familiar.","B":"A realização de laparotomia aumenta o risco de aparecimento de tumor desmoide.","C":"As manifestações extraintestinais podem proceder ao aparecimento dos pólipos do intestino\ngrosso.","D":"Os pólipos do estômago acometem principalmente o antro e têm baixo risco de malignização."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-219881","number":"219881","sourceNumber":"219881","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"TDP, 27 anos, sexo masculino, pintor, refere dor em fossa ilíaca direita com vários dias\nde evolução, que não melhora com a\nadministração de analgésicos comuns. Nega febre. Apresenta\nnáuseas sem vômitos. Exames laboratoriais sem alterações. Realizou tomografia computadorizada\nque mostrou alteração no apêndice, que pode ser vista abaixo. Em relação a este caso, a MELHOR\nCONDUTA entre as abaixo deve ser:","options":{"A":"Apendicectomia aberta com retirada em monobloco do mesoapêndice.","B":"Conduta expectante com exames de imagem seriados.","C":"Punção guiada por ultrassonografia para estudo histopatológico.","D":"Realizar ileocolectomia direita."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-2/219881.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-212160","number":"212160","sourceNumber":"212160","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente 22 anos, masculino, apresentando quadro de dor abdominal em região\nperiumbilical há 2 dias, de moderada\nintensidade com alívio discreto com uso de analgésicos\ncomuns, sem irradiação, associada à anorexia, náuseas e vômito. Nas últimas horas, evoluiu com\npiora da dor e migração dessa dor para a fossa ilíaca direita. Dados Vitais: temperatura 38 °C,\nfrequência cardíaca 106 bpm, frequência respiratória 21 irpm, normotenso. Exame físico do\nabdome: flácido, doloroso à palpação superficial e profunda da fossa ilíaca direita. Sinais de\nBlumberg e Rovsing positivos. Hemograma: Hemoglobina: 13 mg/dL (VR: 12-16) Leucócitos: 16460\n(bastões: 5%). Ultrassom do abdome revela apenas as alterações apresentadas nas figuras. Sobre\no caso, assinale a alternativa correta.","options":{"A":"Trata-se de um caso de apendicite aguda não complicada e está indicado o tratamento\nexclusivamente clínico com uso de antibioticoterapia.","B":"O escore de Alvarado do caso em questão indica baixa probabilidade de apendicite aguda e o\npaciente deverá ser acompanhado apenas com exame físico seriado.","C":"Trata-se de um caso de apendicite aguda não complicada e o tratamento cirúrgico,\napendicectomia videolaparoscópica,\n\nassociada ou não a antibioticoterapia, está indicado.","D":"Trata-se de um caso de apendicite aguda complicada com abscesso, sendo indicada a\ndrenagem percutânea do abscesso e antibioticoterapia, seguido de apendicectomia em\nmomento oportuno.","E":"Trata-se de apendicite aguda e o tratamento cirúrgico convencional tem maior vantagem em\nrelação ao tratamento cirúrgico por videolaparoscopia devido ao retorno precoce às\n\natividades, menor incidência de infecção de ferida operatória e menos dor no pós-operatório."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-2/212160.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-216248","number":"216248","sourceNumber":"216248","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Sobre os tumores carcinoides é INCORRETO que","options":{"A":"é a neoplasia neuroendócrina mais comum do trato digestório.","B":"a localização gástrica é muito frequente.","C":"a síndrome carcinoide é mediada pela serotonina e caracterizada por flush cutâneo,\nbroncoespasmo e taquicardia.","D":"os carcinoides gástricos provocam poucas metástases."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-181368","number":"181368","sourceNumber":"181368","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente de 32 anos, com diagnóstico de retocolite ulcerativa há 6 anos, em tratamento\nirregular e sem seguimento ambulatorial\nnos últimos 2 anos. Admitido em pronto-atendimento por\ndor abdominal e diarreia. Ao exame, ruim estado geral, taquicárdico e hipocorado. O abdome é\npouco distendido, doloroso e sem descompressão negativa, sem cicatrizes cirúrgicas. Hemograma\nrevela hemoglobina de 6, leucocitose de 17000, 3% bastões, PCR 120, VHS 60. Em relação ao\ncaso e à doença, é correto afirmar:","options":{"A":"o uso de corticoides sistêmicos não é benéfico nessa fase da doença.","B":"o tratamento inicial deve ser hidratação vigorosa, dieta oral hipercalórica e hipoproteica.","C":"esse paciente deve ser submetido à colectomia subtotal com ileostomia terminal de urgência.","D":"o tratamento inicial deve ser hidratação venosa vigorosa, antibioticoterapia e imunobiológico.","E":"os pacientes que apresentam coprocultura positiva para C. difficile podem beneficiar-se de\ntransplante fecal em algumas situações."},"answer":"E","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-181399","number":"181399","sourceNumber":"181399","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Em relação à apendicite aguda, assinale a alternativa correta.","options":{"A":"A presença de peritonite difusa é contraindicação à abordagem laparoscópica.","B":"A ultrassonografia tem maior acurácia em relação à tomografia para diagnóstico da doença.","C":"É mais frequente na primeira década de vida, principalmente pela obstrução da luz do órgão por\ncorpo estranho ou tumor.","D":"É uma doença de diagnóstico eminentemente clínico, inclusive os critérios de Alvarado de\nprobabilidade levam em conta apenas sinais e sintomas.","E":"A apendicectomia de intervalo é uma opção terapêutica factível e realizada nos casos onde\nhouve impossibilidade de abordagem durante um evento\nagudo."},"answer":"E","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-187835","number":"187835","sourceNumber":"187835","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Em relação ao abdome agudo, assinale alternativa ERRADA:","options":{"A":"Ausência de leucocitose não exclui apendicite aguda","B":"Ausência de pneumoperitônio inviabiliza o diagnóstico de úlcera perfurada","C":"Níveis normais de amilase e lipase séricos não excluem pancreatite aguda","D":"Os níveis de lactato e as determinações da gasometria arterial auxiliam no diagnóstico de\nisquemia ou infarto intestinal"},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-183105","number":"183105","sourceNumber":"183105","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"São doenças que entram no diagnóstico diferencial das hemorragias digestivas na\ninfância todas a seguir, EXCETO:","options":{"A":"Divertículo de Meckel.","B":"Hemorroidas.","C":"Cetoacidose diabética.","D":"Intussuscepção."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-183602","number":"183602","sourceNumber":"183602","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A dor abdominal em crianças com idade inferior a 2 anos é de difícil diagnóstico; na\nmaioria dos casos, o paciente apresenta irritabilidade e choro excessivos. Em situações de causas\nagudas que cursam com obstrução, massas e peritonite, podemos considerar as seguintes,\nEXCETO","options":{"A":"volvo intestinal.","B":"hérnia encarcerada.","C":"gastroenterites.","D":"apendicite."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-183607","number":"183607","sourceNumber":"183607","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"São aspectos clínicos da dor abdominal que sugerem a necessidade de tratamento\ncirúrgico todos os abaixo, EXCETO","options":{"A":"febre alta e diarreia.","B":"vômitos biliosos ou fecaloides.","C":"rigidez abdominal involuntária (abdome em tábua).","D":"sinal de descompressão brusca positiva (sinal de Blumberg)."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-183612","number":"183612","sourceNumber":"183612","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A faixa etária infantil que apresenta maior dificuldade para a obtenção do diagnóstico\nde dor abdominal aguda corresponde a","options":{"A":"entre 2 e 5 anos.","B":"menores de 2 anos.","C":"entre 5 e 12 anos.","D":"entre 12 e 15 anos."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-183601","number":"183601","sourceNumber":"183601","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A Doença de Crohn (DC) é uma doença inflamatória intestinal de origem não\nconhecida, caracterizada pelo acometimento focal,\nassimétrico e transmural de qualquer porção do\ntubo digestivo, da boca ao ânus. Sendo INADEQUADO, apenas, o seguinte item:","options":{"A":"Apresenta-se sob três formas principais: inflamatória, fistulosa e fibroestenosante. Os segmentos\ndo tubo digestivo mais acometidos são: íleo,\ncólon e região perianal.","B":"Além das manifestações no sistema digestório, a DC pode ter manifestações extraintestinais,\nsendo as mais frequentes as oftalmológicas, as\ndermatológicas e as reumatológicas.","C":"A DC tem início mais frequentemente na segunda e terceira décadas de vida, mas não pode\nafetar qualquer faixa etária.","D":"Em países desenvolvidos, a prevalência e a incidência situam-se em torno de 50:100.000 e\n5:100.000, respectivamente."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-183562","number":"183562","sourceNumber":"183562","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A Doença de Crohn DC não é curável clínica ou cirurgicamente, e sua história natural é\nmarcada por agudizações e remissões. A diferenciação entre doença ativa e em remissão pode ser\nfeita com base no Índice de Harvey-Bradshaw. Sendo INADEQUADO, apenas, que","options":{"A":"pacientes sem sintomas (IHB igual ou inferior a 4) e sem uso de corticosteroide são\nconsiderados em remissão sintomática.","B":"pacientes que necessitam de corticosteroide para permanecer assintomáticos não são\nclassificados como corticodependentes, sendo considerados em remissão, devido ao risco de\ntoxicidade do tratamento prolongado.","C":"pacientes com doença leve a moderada (IHB igual a 5, 6 ou 7) costumam ser atendidos\nambulatoriamente, toleram bem a alimentação, estão bem hidratados, não apresentam perda de\npeso superior a 10%, sinais de toxicidade, massas dolorosas à palpação ou sinais de obstrução\nintestinal.","D":"pacientes com doença moderada a grave (IHB igual ou superior a 8), usualmente, estão com o\nestado geral bastante comprometido e apresentam, ainda, um ou mais dos seguinte sintomas:\nfebre, perda de peso, dor abdominal acentuada, anemia ou diarreia frequente (3-4 evacuações ou\nmais por dia)."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-183603","number":"183603","sourceNumber":"183603","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"O diagnóstico pode ser difícil devido à heterogeneidade das manifestações e à sua\nsobreposição com as da retocolite ulcerativa, bem como a ocasional ausência de sintomas\ngastrointestinais relevantes. Sendo INCORRETO, apenas, que","options":{"A":"o sintoma mais comum no momento do diagnóstico é diarreia, seguida por sangramento\n(40%-50%), perda de peso (60%) e dor abdominal\n(70%).","B":"os sinais mais comuns são febre, palidez, caquexia, massas abdominais, fístulas e fissuras\nperianais.","C":"a endoscopia mostra tipicamente lesões ulceradas, entremeadas de áreas com mucosa normal,\nacometimento focal, simétrico e contínuo, podendo, também, ser útil para a coleta de material para\nanálise histopatológica.","D":"mais de 6 semanas de diarreia é o critério sugerido como prazo útil para diferenciação com\ndiarreia aguda infecciosa."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-183641","number":"183641","sourceNumber":"183641","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"O diagnóstico pode ser difícil devido à heterogeneidade das manifestações e à sua\nsobreposição com as da retocolite ulcerativa, sendo que endoscopia mostra tipicamente lesões\nulceradas, entremeadas de áreas com mucosa normal, acometimento focal para a coleta de\nmaterial para análise histopatológica. Sendo ADEQUADO, apenas, que a análise histológica","options":{"A":"nunca pode indicar acometimento transmural (quando da análise de ressecções cirúrgicas),\npadrão segmentar e presença de\n\ngranulomas não caseosos.","B":"pode indicar acometimento transmural (quando da análise de ressecções cirúrgicas), padrão\nsegmentar e presença de\n\ngranulomas não caseosos.","C":"pode indicar acometimento transmural (quando da análise de ressecções cirúrgicas), padrão\nsegmentar e presença de\n\ngranulomas caseosos.","D":"pode indicar acometimento transmural (quando da análise de ressecções cirúrgicas), padrão\nsegmentar e ausência de\n\ngranulomas não caseosos."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-183620","number":"183620","sourceNumber":"183620","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Durante a gestação, a atividade da doença está relacionada a abortamento, sendo que\na sulfassalazina apresenta diversas interações.\nIndique, das abaixo, qual está ERRADA.","options":{"A":"A sulfassalazina não interfere no metabolismo normal do ácido fólico, não sendo necessário ser\nsuplementado no período preconcepção.","B":"É seguro sulfassalazina durante os dois primeiros trimestres da gestação.","C":"No último trimestre, a sulfassalazina pode com seu uso, aumentar o risco de Kernicterus.","D":"Mesalazina é considerada segura durante a gestação em doses de até 3 g/dia, não tendo sido\ntestadas doses maiores."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-161118","number":"161118","sourceNumber":"161118","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Em relação à doença inflamatória intestinal, assinale a alternativa INCORRETA.","options":{"A":"Doença de Crohn é uma doença inflamatória crônica, transmural do trato gastrointestinal de\ncausa desconhecida. Afeta mais comumente o\nintestino delgado. O risco de desenvolver Crohn é\nduas vezes mais elevado em fumantes do que em não fumantes.","B":"São manifestações extraintestinais da doença de Crohn: eritema multiforme, eritema nodoso,\npioderma gangrenoso, irite, uveíte, conjuntivite, artrite, espondilite anquilosante, anemia,\ntrombocitose, colangite esclerosante, amiloidose e pancreatite.","C":"Os corticosteroides, particularmente a prednisona, são benéficos na indução da remissão, porém\nsão ineficazes na manutenção da remissão.","D":"As operações decorrentes à doença de Crohn são na maioria das vezes curativas, com taxas de\nrecorrência muito baixas."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-161344","number":"161344","sourceNumber":"161344","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A respeito da doença diverticular dos cólons e diverticulite, aponte a alternativa\nINCORRETA.","options":{"A":"O Cólon sigmoide é o local mais cometido, e a segunda área mais envolvida é o cólon\ndescendente.","B":"São divertículos verdadeiros, pois são formados por todas as camadas da parede do intestino.","C":"Segundo a classificação de Hinchey para diverticulite, estádio II, corresponde ao abscesso\npélvico bloqueado, e o tratamento de escolha é drenagem percutânea via tomografia\ncomputadorizada ou ultrassom.","D":"Nas peritonites generalizadas causadas pela diverticulite e associadas à sepse, não é seguro\nrestabelecer continuidade intestinal, pela elevada probabilidade de cicatrização inadequada. Neste\ncaso a operação apropriada é a cirurgia de Hartmann."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-158765","number":"158765","sourceNumber":"158765","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Dadas as afirmativas sobre a apendicite aguda, I. Pacientes com escore de Alvarado\nigual ou superior a 7 têm alto risco de\napendicite.; II. Atualmente, a cirurgia aberta é a via de\nescolha para o tratamento da doença.; III. É a urgência cirúrgica abdominal mais frequente.; IV. Há\npredomínio no sexo feminino e em negros. Verifica-se que está(ão) correta(s):","options":{"A":"I, apenas.","B":"II, apenas.","C":"I e III, apenas.","D":"II e IV, apenas.","E":"I, II, III e IV."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-161138","number":"161138","sourceNumber":"161138","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"São bactérias comumente isoladas em apendicite perfurada, com EXCEÇÃO de uma\ndelas. Indique-a.","options":{"A":"Bacterioides fragilis.","B":"Streptococcus viridans.","C":"Clostridium difficile.","D":"Pseudomonas aeroginosa."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-161309","number":"161309","sourceNumber":"161309","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Assinale a alternativa INCORRETA sobre a Laceração de Mallory-Weiss.","options":{"A":"Está relacionada com vômitos explosivos, regurgitação, tosse ou esforço excessivo.","B":"Ocorre ruptura da mucosa gástrica em uma parte alta da curvatura maior na junção\ngastroesofágica.","C":"Raramente está associada a um sangramento generoso.","D":"A maioria dos pacientes com sangramento ativo pode ser tratada com métodos endoscópicos,\ncomo a coagulação multipolar, a injeção de\nepinefrina, a ligadura com uma banda elástica e/ou a\nhemoclipagem endoscópica."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-161304","number":"161304","sourceNumber":"161304","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Assinale a alternativa INCORRETA quanto à diverticulite:","options":{"A":"É efeito da perfuração de um divertículo colônico resultado em uma infecção pericólica\nextraluminal.","B":"O cólon sigmoide é o segmento do intestino grosso com a maior incidência de divertículos e é o\nlocal mais frequente para envolvimento com a diverticulite.","C":"Muitos pacientes com diverticulite queixam-se de dor em quadrante inferior esquerdo do\nabdome, que pode irradiar-se para a área suprapúbica, virilha esquerda ou para as costas.","D":"A presença de abscesso pericólico ou mesentérico é classificado como estádio II de Hinchey."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-161331","number":"161331","sourceNumber":"161331","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Cerca de 8% das pessoas nos países ocidentais têm apendicite em algum momento de\nsuas vidas, com uma incidência máxima entre\n10 e 30 anos de idade. Sobre aspectos diversos do\napêndice, indique a opção CORRETA.","options":{"A":"A localização mais comum do apêndice cecal é pélvica.","B":"Piúria mínima, frequentemente observada em mulheres idosas, exclui apendicite aguda.","C":"Em crianças pré-escolares, o diagnóstico diferencial inclui diverticulite de Meckel,\ngastroenterite\naguda.","D":"Em crianças em idade escolar, o mais comum simulador de apendicite são os neoplasmas de\napêndice."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-161252","number":"161252","sourceNumber":"161252","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Marque a opção INCORRETA quanto à hemobilia.","options":{"A":"A exploração cirúrgica da árvore biliar pode resultar em hemobilia por lesão direta ou pela\nformação de pseudoaneurisma arterial.","B":"O tratamento de primeira linha para uma hemobilia volumosa é a intervenção cirúrgica e envolve\na ligadura de vasos sangrantes, excisão do\naneurisma ou a ligadura não seletiva de uma artéria\nhepática principal.","C":"A hemobilia secundária à lesão acidental é mais comum no trauma abdominal fechado do que\nno penetrante.","D":"A tríade clássica de sintomas e sinais de hemobilia são dor abdominal superior, hemorragia\ngastrointestinal alta e icterícia."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-158810","number":"158810","sourceNumber":"158810","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Mulher, 18 anos, procura serviço médico, pois há 1 ano vem apresentando rubor facial\n(flushing), cólicas abdominais, náuseas, vômitos, diarreia e episódios de broncoespasmos.\n\nTomografia de abdômen e pelve mostrou massa sólida hipervascularizada mesentérica em\ncontinuidade com jejuno associada a múltiplas lesões hepáticas compatíveis com lesões\nsecundárias. Qual o diagnóstico mais provável?","options":{"A":"Síndrome de Felty.","B":"Doença de Addison.","C":"Síndrome carcinoide.","D":"Síndrome de Ogilvie.","E":"Síndrome de Zollinger-Ellison."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-152651","number":"152651","sourceNumber":"152651","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Qual das seguintes afirmações está CORRETA em relação às angiodisplasias do\ncólon?","options":{"A":"Fulguração da angiodisplasia deve ser realizada durante uma colonoscopia eletiva,\nindependentemente da história de sangramento anterior.","B":"O sangramento da angiodisplasia é mais comum no lado esquerdo do paciente idoso.","C":"Uma angiografia normal durante um sangramento ativo exclui angiodisplasia como causa de\nhemorragia.","D":"As angiodisplasias variam de 1,5 a 2 mm e histologicamente são caracterizadas por capilares\ndilatados e tortuosos localizados na lâmina própria.","E":"Nenhuma das alternativas acima está correta."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-158395","number":"158395","sourceNumber":"158395","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"João da silva, 62 anos, deu entrada no hospital de Emergências apresentando quadro\nde dor abdominal difusa há 10 dias, que veio\naumentando de intensidade, associado à distensão do\nabdome e episódios de vômitos e parada de eliminação de flatos e fezes. Relata também perda de\npeso nos últimos meses, entretanto não sabe precisar o quanto perdeu. Ao exame físico:\nconsciente, desidratado ++\\++++, dispneico, FR: 30 irpm, anictérico, afebril. Abdome globoso,\ndistendido, doloroso à palpação difusamente, timpânico. Toque retal: ausência de fezes, sangue ou\ntumorações em dedo de luva. Marque a assertiva INCORRETA:","options":{"A":"O quadro descrito pode ter diagnóstico sindrômico de câncer de reto com metástase pulmonar, o\nque justificaria a dispneia do paciente.","B":"O toque retal é extremamente importante, pois permite detectar 50% dos tumores de reto e canal\nanal.","C":"A colonoscopia é indicada na presença de sintomas, bem como no seguimento de doentes que,\nrastreados para Cancer Colo Retal, apresentam resultado positivo de pesquisa de sangue oculto\nnas fezes.","D":"As metástases por via sanguínea são pouco comuns e ocorrem com mais frequência no fígado e\nmenos no pulmão, nos rins, nos ossos e no cérebro.","E":"A ressecção cirúrgica deve incluir o tumor e a área de drenagem linfática locorregional\ncorrespondente com margens parietal e distal de no\nmínimo 5 cm para o cólon e 2 cm para o reto\nquando a intenção for curativa."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-158400","number":"158400","sourceNumber":"158400","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"São doenças que entram no diagnóstico diferencial de abdome agudo inflamatório,\nEXCETO:","options":{"A":"Apendicite aguda.","B":"Abscesso hepático.","C":"Herpes zoster.","D":"Pielonefrite.","E":"Ferimento por arma de fogo no abdome."},"answer":"E","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-158430","number":"158430","sourceNumber":"158430","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Dentre as citadas, as causas mais comuns de dor abdominal aguda em\nescolares/adolescentes, pré-escolares e lactentes são representadas, respectivamentes, por:","options":{"A":"Anemia falciforme, constipação intestinal e infecção urinária.","B":"Hematocolpos, infecção urinária e psoíte.","C":"Apendicite, adenite mesentérica e doença diarréica aguda.","D":"Cetoacidose diabética, infecção urinária e doença diarreica aguda.","E":"Úlcera péptica, pneumonia e invaginação intestinal."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-362487","number":"362487","sourceNumber":"362487","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Qual a manifestação extra-intestinal mais comum na doença de Crohn?","options":{"A":"Artrite.","B":"Uveíte.","C":"Pioderma gangrenoso.","D":"Eritema nodoso."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-362469","number":"362469","sourceNumber":"362469","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo masculino, 32 anos, sobrepeso, comparece ao pronto atendimento\napresentando quadro de dor tipo cólica,\nmesogástrica, que migrou para FID e aumentou de\nintensidade, há cerca de 24hs. Apresentou também vários episódios de vômito. Nega febre, diarreia\ne sintomas urinários. Encontra-se em BEG, eupneico, afebril, estável. Sem abdome é plano, flácido,\ndoloroso à palpação profunda na FID, com descompressão súbita levemente positiva. Foi solicitada\navaliação laboratorial que evidenciou leucograma 11.000, com 90% de segmentados e Proteína C\nReativa 36g/l. Optou-se por avaliação ultrassonográfica que evidenciou apêndice cecal espessado\ne discretamente aumentado de volume, com hipervascularização da sua parede ao doppler, sem\nfecalito ou líquido livre na cavidade. Sobre o caso descrito acima, assinale a alternativa CORRETA:","options":{"A":"Havia indicação precisa de laparotomia imediata logo após o exame físico, caso contrário o\npaciente provavelmente evoluiria com complicações como abscesso intracavitário.","B":"A conduta definitiva para o caso só pode ser tomada após a exclusão de apendicolito por\ntomografia computadorizada.","C":"O achado laboratorial de leucocitose e elevação da proteína C reativa nos permite afirmar que\nantibioticoterapia por 3 a 5 dias fará parte do tratamento deste paciente.","D":"Está indicada internação hospitalar para tratamento inicial não cirúrgico, com antibióticos e\nreavaliação clínica após 8 horas."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-362511","number":"362511","sourceNumber":"362511","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo masculino, 57 anos, vem ao atendimento médico queixando dor tipo\ncólica em FIE com piora progressiva, associada a vômitos e constipação há 48 horas. Refere hábito\nintestinal inadequado, com eliminação de fezes endurecidas e ressecadas, sob esforço, cerca de\numa vez por semana, há muitos anos. Nega febre e episódios anteriores de dor semelhante. Nega\ncomorbidades. Ao exame físico apresenta-se em BEG, eupneico, afebril hemodinamicamente\nestável. Seu abdome é globoso, flácido, doloroso à palpação profunda, sem irritação peritoneal ou\nplastrão palpável. Leucograma: 12.000 e Proteína C reativa: 63mg/l. Foi solicitada tomografia de\nabdome que evidenciou presença de divertículos em sigmoide de parede espessada, contendo\ndivertículos, com borramento da gordura adjacente, sem coleções ou líquido livre na cavidade\nabdominal. Sobre o caso descrito, assinale a alternativa CORRETA:","options":{"A":"Por tratar-se de paciente imunocompetente, sem comorbidades e com bom estado geral, o\ntratamento clínico inicial pode ser realizado sem antibióticos.","B":"Considerando que a grande maioria dos casos descritos acima evoluem com complicações\ncomo perfuração de cólon, formação de abscessos e\nperitonite, há clara indicação para\nhospitalização.","C":"A história, o exame físico e a avaliação laboratorial eram suficientes para fechamos o\ndiagnóstico clínico e início do tratamento, sem a necessidade da realização da tomografia.","D":"A conduta definitiva para o caso é a sigmoidectomia eletiva laparoscópica realizada 6 a 8\nsemanas após a remissão dos sintomas com tratamento clínico."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-362510","number":"362510","sourceNumber":"362510","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo feminino, 49 anos, dá entrada no pronto atendimento queixando dor\nabdominal tipo cólica, difusa, progressiva, há 3 dias, associada a vários episódios de vômitos.\n\nRefere parada de eliminação de gases e fezes desde o início do quadro. Encontra-se desidratada,\nFR: 28irpm, FC: 90bpm, P.A.: 100x70mmHg,\nnormocorada, anictérica, sem edemas. Refere\ndiminuição do volume urinário. Seu abdome é distendido, sem cicatrizes ou circulação colateral,\nhipertimpânico, com RHA aumentados em frequência e intensidade, difusamente doloroso à\npalpação, sem sinais de irritação peritoneal e sem massas palpáveis. Regiões inguinais e crurais\nsem herniações. Foi solicitada radiografia simples de abdome que evidenciou volumosa distensão\nde intestino delgado, com sinal de empilhamento de moeda e vários níveis hidroaéreos, sem\ndistensão do cólon e sem pneumoperitôneo. Sobre o caso acima, assinale a alternativa\nINCORRETA:","options":{"A":"A ausência gás na árvore de biliar e de cálculos na vesícula na radiografia de abdome exclui o\ndiagnóstico diferencial de íleo biliar.","B":"Apesar da paciente não ter sido submetida a cirurgias abdominais prévias, não se pode excluir\nas bridas e aderências como diagnóstico\ndiferencial.","C":"O próximo passo na avaliação desta paciente é a tomografia de abdome para definição da\netiologia do quadro e investigação de possíveis sinais de sofrimento de alças intestinais.","D":"Radiografias seriadas de abdome após administração de contraste oral hidrossolúvel podem\nauxiliar na escolha do tratamento para o caso."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-362508","number":"362508","sourceNumber":"362508","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo masculino, 10 anos de idade, apresentando quadro de dor aguda e\nprogressiva em FID, associada a vómitos e febre e sinais de irritação peritoneal. Foi indicada a\nlaparotomia pela hipótese diagnóstica de apendicite aguda, porém durante a exploração cirúrgica\nfoi observado abcesso bloqueado em FID secundário a processo inflamatório e perfuração em\nestrutura saculiforme de 5cm de diâmetro localizado em íleo distal, há cerca de 50cm da vávula\níleo-ceçal. O apêndice não tinha sinais patológicos. Optou-se por enterectomia do segmento ileal\nacometido, enteroanastomose e apendicectomia incidental. A mãe do paciente solicitou\nesclarecimento sobre o achado cirúrgico e a patologia do filho. As seguintes orientações são\nadequadas para o caso, EXCETO:","options":{"A":"\"\"A maioria das pessoas não sabe que tem essa pequena alteração no intestino porque não tem\nsintomas e se pode passar a vida inteira sem apresentar complicações\"\".","B":"\"\"É uma doença de difícil diagnóstico porque ela normalmente passa despercebida nos exames\nde imagem como ultrassonografia e tomografia e\no diagnóstico geralmente é feito durante uma\ncirurgia para outras doenças\"\".","C":"\"\"Essa doença não complica apenas com inflamação e casos de obstrução intestinal e\nhemorragia digestiva também podem ocorrer\"\".","D":"\"\"As duas principais causas de inflamação são a presença de tecido de outras partes do tubo\ndigestivo (tecido ectópico), como esófago e duodeno, e perfuração por corpos estranhos como\nespinhas de peixe\"\"."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-362505","number":"362505","sourceNumber":"362505","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo masculino, 45 anos, é achado desmaiado no banheiro da sua\nresidência e trazido para o pronto socorro. Apresenta-se hipocorado +++/4, FC: 120bpm, FR:\n28irpm, P.A.: 80x60mmHg e débito urinário reduzido. Não há icterícia, edema de membros\ninferiores ou abdome ascítico. Foi infundido inicialmente 1.000ml de ringer lactato durante\nressuscitação volêmica e transfundidos 2 concentrados de hemácias após hemograma revelar\nhemoglobina 7g/dl. Após as medidas iniciais, o paciente apresentou estabilização dos sinais\nclínicos e referiu a equipe estar apresentando fezes enegrecidas de odor fétido há vários dias.\nNega hematêmese e quadro febril. Sobre o caso descrito, assinale a alternativa INCORRETA:","options":{"A":"Na avaliação laboratorial deste paciente, devemos observar elevados índices de uréia sérica e\nrelação uréja/creatinina acima de 50.","B":"Os dados clínicos apresentados nos permitem afirmar que este paciente apresenta risco elevado\npara complicações e óbito, sendo indicada\ntratamento intervencionista urgente.","C":"Admissão do paciente com choque grave por si já fecha critério para tratamento cirúrgico\nprecoce para controle do sangramento.","D":"Caso a endoscopia digestiva alta não evidencie foco de sangramento, a angio-tomografia é\nopção adequada para identificação do sítio de\nsangramento."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-362502","number":"362502","sourceNumber":"362502","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo masculino, 32 anos, portador de Retocolite Ulcerativa procura\natendimento médico por dor abdominal. Teve o\ndiagnóstico fechado após crises de diarreia\nsanguinolenta, sendo submetido a colonoscopia na época. Desde então vem sendo tratado por\naminossalicilatos orais, porém refere uso irregular da medicação. A crise atual iniciou há 3 dias,\ncom cólica abdominal difusa progressiva associada a quadro de diarreia com sangue. Evoluiu com\npiora do estado geral, iniciando febre diária, piora da frequência e volume sanguinolento da\ndiarreia\n(cerca de 10 episódios ao dia), anorexia e queda do estado geral. Ao exame físico, encontra-se em\nREG, pálido, taquicárdico, levemente dispneico e normotenso. Seu abdome é algo distendido,\ndoloroso à palpação profunda difusamente, sem irritação peritoneal. Sua investigação laboratorial\nevidenciou Leucograma: 16.000, Hb: 9g/dl, Proteína C reativa: 68mg/dl e VHS: 75mm/h. Sobre o\ncaso descrito, assinale a alternativa CORRETA:","options":{"A":"Há indicação de internação hospitalar para ressuscitação volêmica, monitorização e início do\ntratamento clínico com opióides para a dor e loperamida para o quadro diarreico.","B":"O tratamento da crise aguda com ciclosporina e infliximabe podem evitar a evolução para\ntratamento cirúrgico de urgência.","C":"Evolução para megacólon tóxico piora bastante o prognóstico deste paciente, estando indicado\no enema opaco baritado para confirmação do seu\ndiagnóstico.","D":"O risco iminente de sepse contraindica o uso de corticoides neste caso."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-327241","number":"327241","sourceNumber":"327241","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo feminino, 13 anos, refere quando de dor tipo cólica, em epigástrio,\nque migrou para FID, com aumento progressivo\nde intensidade, associada a náuseas e vômitos.\nEvolução de 48 horas. Nega febre e diarreia. Refere menarca há cerca de 6 meses, com ciclos\nregulares. Nega leucorréia. Seu abdome é plano, flácido, doloroso à palpação profunda em FID,\ncom sinais de Blumberg e Rovsing positivos. Sobre o caso acima, assinale a alternativa CORRETA:","options":{"A":"Dados como a idade da paciente, o ciclo menstrual regular e o tempo de evolução do quadro\nagudo nos permitem afirmar que o tratamento\nnão-cirúrgico com antibioticoterapia pode ser efetivo\npara o quadro acima.","B":"A presença do sinal de Rovsing indica laparotomia exploradora imediata.","C":"A abordagem laparoscópica pode ser tanto diagnóstica quanto terapêutica para o caso acima.","D":"A ausência de febre exclui o diagnóstico de abdome agudo inflamatório, estando indicada\ninvestigação com tomografia computadorizada de abdome."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-327245","number":"327245","sourceNumber":"327245","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo feminino, 22 anos de idade, dá entrada no pronto atendimento com\nquadro de dor abdominal iniciada em FID e\nirradiada para toda a pelve, de leve a moderada\nintensidade, há cerca de 8 horas, acompanhada de tontura, mal-estar e sensação de síncope. Não\nsabe referir adequadamente o caráter da dor. Nega vômitos, diarreia e sintomas urinários. Refere\nleucorréia esbranquiçada há 3 meses, ciclo menstrual irregular, com data da última menstruação há\ncerca de 2 meses. Vida sexual ativa com uso irregular de preservativos ou outros métodos\ncontraceptivos. Ao exame físico encontra-se hipocorada +++/4, FR: 25irpm, FC: 100bpm, P.A.: 90 x\n60mmHg. Abdome plano, flácido, simétrico, doloroso à palpação profunda em toda a pelve, com\nirritação peritoneal duvidosa. Refere dor ao toque vaginal. Toque retal sem alterações. Sobre o\ncaso acima, assinale a alternativa INCORRETA:","options":{"A":"O hemograma será útil para o diagnóstico sindrômico do caso acima, mas pode ser dispensável\npara a decisão de abordagem cirúrgica para o\ncaso.","B":"Caso o Beta-HCG desta paciente resulte negativo, o tratamento preferencial do caso será\nclínico, com analgesia e antibioticoterapia.","C":"A ressuscitação volêmica com Ringer Lactato e a avaliação da necessidade de transfusão de\nconcentrado de hemácias faz parte da conduta inicial do caso.","D":"O FAST, apesar de ser propedêutica idealizada para pacientes politraumatizados, pode ser\nextremamente valioso na avaliação inicial desta paciente."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-327251","number":"327251","sourceNumber":"327251","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo masculino, 65 anos, com história de constipação crônica e baixa\ningesta alimentar de fibras, vem ao pronto\nsocorro queixando dor tipo cólica, aguda, em FIE, de\nmoderada intensidade, há cerca de 48 horas, associada a náuseas, vômitos e parada de\neliminação de fezes. Refere, ainda, 1 episódio de febre baixa. Nega comorbidades como\nhipertensão e diabetes. Ao exame físico, encontra-se em BEG, eupneico, afebril,\nhemodinamicamente estável. Seu abdome é plano, flácido, bastante doloroso à palpação profunda\nem FIE, com discreta irritação peritoneal. Leucograma: 16.000, Proteína C reativa: 80mg/l. Foi\nsubmetido a Tomografia Computadorizada de abdome que evidenciou presença de múltiplos\ndivertículos em cólon sigmoide, com borramento da gordura pericólica e presença de coleção\nlíquida bloqueada de cerca de 6cm. Sobre o caso acima, assinale a alternativa CORRETA:","options":{"A":"Por tratar-se de paciente classificado como Hinchey IB, a drenagem percutânea da coleção\npericólica pode prevenir a necessidade de sigmoidectomia de urgência.","B":"O próximo passo na investigação diagnóstica deste paciente é a realização de colonoscopia\npara avaliar a presença de complicações como edema,\nhiperemia, presença de pus e erosões,\nalém de estabelecer adequadamente a classificação DICA para o caso.","C":"Por tratar-se de paciente com baixo risco para complicações cirúrgicas, o paciente pode ser\ntratado inicialmente em domicílio, com dieta líquida sem resíduos e repouso, sem uso de\nantibióticos.","D":"A presença de febre, leucocitose e proteína C reativa elevada, revela alto risco de complicações\ngraves que, quando associado aos achados\ntomográficos descritos acima, compõem indicação\nformal para colectomia esquerda e colostomia terminal à Hartmann."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-327258","number":"327258","sourceNumber":"327258","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo masculino, 55 anos, hipertenso e com história recente de angina\ninstável, dá entrada no pronto socorro\napresentando quadro de dor epigástrica em queimação,\nintensa, que migrou para todo o abdome, acompanhada de sinais claros de peritonite difusa, com\nevolução de 6 horas. Associado ao quadro abdominal, apresenta dor torácica e dispneia.\n\nSubmetido a eletrocardiograma, este evidencia alterações isquêmicas nas derivações anteriores. A\nradiografia de tórax evidencia pneumoperitoneo. Quais das condutas a seguir é a mais adequada\npara o caso?","options":{"A":"Encaminhar paciente para cateterismo coronariano imediato, previamente a laparotomia.","B":"Antibióticos, monitorização invasiva intra-operatória, laparotomia imediata e pós-operatório em\nUTI.","C":"Antibióticos, tratamento intensivo da sua condição cardíaca e cirurgia após 48 horas de\nestabilização do quadro de angina.","D":"Antibióticos e tratamento não cirúrgico do quadro abdominal."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-298209","number":"298209","sourceNumber":"298209","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo masculino, 60 anos de idade, diabético, apresenta quadro de dor\nmesogástrica que migrou para fossa ilíaca esquerda há 2 dias, com piora progressiva, associada a\nvômitos. Refere história de constipação crônica. Não defecou no período, porém eliminava flatos.\nAo exame físico, encontrava-se em BEG, eupneico, taquicárdico, desidratado e normotenso, com\nabdome globoso, flácido, doloroso à palpação profunda em fossa ilíaca esquerda e discreta\nirritação peritoneal. Leucograma: 14.000. Foi internado para observação clínica, sendo iniciada\nantibioticoterapia, analgesia e mantido em dieta zero. Após 72 horas de internação, apresentou\npiora do quadro geral, com migração da dor para toda a pelve, piora da sua intensidade e início de\npicos febris. Está toxemiado, taquicárdico, levemente eupneico e hipotenso, e seu abdome agora\napresenta plastrão palpável em fossa ilíaca esquerda e irritação peritoneal em andar inferior. Sobre\no quadro descrito, assinale a alternativa CORRETA:","options":{"A":"Os dados acima nos permitem classificar a patologia do paciente como Hinchey 2, estando\nindicado o escalonamento da antibioticoterapia e manutenção da observação clínica.","B":"A sigmoidectomia com anastomose primária término-terminal é conduta provavelmente\ninadequada para o caso.","C":"A evolução insatisfatória do caso indica investigação colonoscópica para definição da conduta\nterapêutica adequada.","D":"A ultrassonografia teria definido conduta cirúrgica no momento da internação deste paciente."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-298211","number":"298211","sourceNumber":"298211","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo feminino, 28 anos, grávida de 32 semanas, inicia quadro de dor tipo\ncólica em mesogástrio que migra para o flanco direito, de moderada intensidade, associada a\nnáuseas e vômitos, há cerca de 36 horas. Nega febre, sintomas urinários, leucorréia e alterações\nno hábito intestinal. Ao exame físico, encontra-se em BEG, eupneica, afebril, hemodinamicamente\nestável. Seu abdome é gravídico, com útero palpável acima da cicatriz umbilical. Movimentos fetais\npalpáveis. Ausculta do foco cardíaco fetal: 140bpm. Dor à palpação profunda em flanco direito, com\ndescompressão brusca bastante dolorosa. Toque vaginal: colo uterino fechado. O hemograma\nrevela 12.000 leucócitos com desvio à esquerda, hemoglobina e hematócrito normais para o estado\ngravídico. EAS sem alterações. Sobre o caso acima, assinale a alternativa CORRETA:","options":{"A":"A postergação do tratamento cirúrgico urgente para esta paciente aumenta as chances de parto\nprematuro e sofrimento fetal.","B":"A ausência de febre e o estado gravídico sugerem que a antibioticoterapia de largo espectro é o\ntratamento de escolha para o caso acima.","C":"Os dados clínicos são insuficientes para determinação de diagnóstico e conduta, estando\nindicada a investigação com tomografia computadorizada.","D":"O estado gravídico contraindica tratamento laparoscópico para o caso."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-298217","number":"298217","sourceNumber":"298217","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo masculino, 28 anos, vem ao pronto atendimento queixando dor\nsubesternal e epigástrica severas, que o\nacordaram durante a madrugada. O paciente refere ter ido\nà festa na noite anterior e ingerido uma quantidade significativa de álcool que o fez vomitar várias\nvezes ao chegar ao seu domicílio. Ao exame físico, o paciente apresentava-se com fascies de dor,\nfebril (38,8ºC), taquicárdico, taquipneico e normotenso. A ausculta do tórax revelou murmúrio\nvesicular diminuído à esquerda, ausência de ruídos adventícios e exame cardíaco apresentando\ntaquicardia sem outras alterações. Seu abdome era doloroso à palpação profunda do epigástrio,\nsem sinais de irritação peritoneal. Sua investigação laboratorial revelou leucocitose importante\n(26.000 leucócitos com desvio à esquerda). Hematócrito, hemoglobina, contagem de plaquetas,\ndosagens de amilase, bilirrubinas e transaminases dentro da normalidade. Foi submetido a ECG\nque evidenciou taquicardia sinusal. A radiografia de tórax evidenciou derrame pleural associado a\npequeno pneumotórax à esquerda e pneumomediastino. Sobre o caso acima, assinale a alternativa\nCORRETA:","options":{"A":"O próximo passo para o diagnóstico deste paciente é a tomografia de tórax com contraste oral\niodado.","B":"O esofagograma contrastado com bário é o estudo radiográfico mais eficaz e menos mórbido\nindicado para o caso.","C":"Os dados acima nos permitem afirmar que a melhor opção de tratamento deste paciente é a\ndrenagem fechada de tórax à esquerda, manutenção de dieta oral sem gorduras, antibioticoterapia\ne inibidores de bomba de prótons.","D":"Os dados acima nos permitem afirmar que a endoscopia digestiva alta é contraindicada para\neste paciente por aumentar significativamente o índice de mortalidade."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-286708","number":"286708","sourceNumber":"286708","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente de 30 anos, sem comorbidades prévias, apresentando quadro de dor\nabdominal e diarreia aquosa há 6 semanas, com\nmuco, pus e sangue. Submetido a colonoscopia\nque evidenciou múltiplas úlceras em íleo terminal, cólon direito e transverso, com áreas\nentremeadas de mucosa sã. Exame proctológico identificando fístula perianal. O diagnóstico mais\nprovável é:","options":{"A":"Tuberculose intestinal.","B":"Amebíase.","C":"Doença de Crohn.","D":"Retocolite ulcerativa."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-286709","number":"286709","sourceNumber":"286709","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente com diagnóstico de RCUI (retocolite ulcerativa) que evoluiu para a forma\ngrave da doença, sem melhoras após corticoterapia venosa habitual, tem como melhor opção\nterapêutica:","options":{"A":"Metotrexate.","B":"Ciclosporina venosa.","C":"Corticoide em doses imunossupressoras.","D":"Mesalazina."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-286719","number":"286719","sourceNumber":"286719","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo feminino, 56 anos, apresenta quadro de dor abdominal difusa, tipo\ncólica, de intensidade progressiva, há 3 dias, associada à parada de eliminação de gases e fezes.\nApresentou 2 episódios de vômitos de coloração escura e nega febre. Refere constipação crônica\nque piorou nos últimos 6 meses, com perda de peso não referido. Ao exame físico, apresenta-se\nem regular estado geral, algo emagrecida, bastante desidratada, taquicárdica, levemente\ntaquipneica e hipotensa. Seu abdome é distendido, hipertimpânico, difusamente doloroso à\npalpação, sem sinais de irritação peritoneal. Movimento peristáltico visível a nível do epigástrio.\n\nRuídos hidroaéreos aumentados em volume e frequência. Na radiografia de abdome, observamos\nvolumosa distensão de cólon com interrupção do\npadrão gasoso a nível do sigmoide, ausência de\ngás no reto e discreta presença de gases no intestino delgado. Assinale a alternativa INCORRETA:","options":{"A":"O próximo passo no tratamento desta paciente é a colonoscopia, por ser diagnóstica e\nterapêutica neste caso.","B":"Há indicação de laparotomia urgente devido ao risco de perfuração do ceco.","C":"O tratamento inicial com sondagem nasogástrica provavelmente será pouco efetivo no alívio da\ndistensão abdominal desta paciente.","D":"A radiografia de abdome sugere que esta paciente apresenta válvula ileocecal competente."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-286721","number":"286721","sourceNumber":"286721","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo masculino, industriário, 54 anos, é conduzido por familiares ao pronto\natendimento devido a ?desmaio no banheiro? pela manhã. É admitido algo sonolento, anictérico,\nhipocorado +++/4, taquicárdico, discretamente dispneico e hipotenso. Seu exame cardiopulmonar\nnão tem alterações e seu abdome é atípico, sem circulação colateral, plano, flácido, indolor, sem\nmassas palpáveis. Realizou um hemograma de urgência que evidenciou 7.500 leucócitos,\nhemoglobina 6,3 g/dl, hematócrito 18,7% e plaquetas 350.000. Após ressuscitação volêmica com\nRinger lactato, seu status hemodinâmico e o nível de consciência normalizaram. Então o paciente\nreferiu que vinha apresentando abundantes fezes escuras ?como açaí? há 1 semana. Nega\nvômitos, disfagia, perda de peso e demais sintomas. Refere epigastralgia crônica, tratando-a por\nconta própria com antiácidos. Assinale a alternativa CORRETA:","options":{"A":"Caso a endoscopia digestiva alta evidencie lesão gástrica ulcerosa classe IIC de Forrest, o\npróximo passo é laparotomia urgente para controle do foco de sangramento.","B":"A evolução subaguda do caso associada a suspeita de hemorragia digestiva alta sugere\nprovável síndrome de Mallory-Weiss.","C":"O tratamento deste paciente provavelmente envolverá inibidores de bomba de prótons.","D":"O uso do balão de Sengstaken-Blakemore é essencial na abordagem terapêutica inicial deste\npaciente."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-286725","number":"286725","sourceNumber":"286725","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo masculino, 16 anos, é atendido no pronto-socorro apresentando\nquadro de dor tipo cólica em epigástrio que\nmigrou para fossa ilíaca direita há 2 dias, associada a\nvômitos e 1 episódio de febre baixa. Seu estado geral é bom e o paciente se encontra\nhemodinamicamente estável. O hemograma evidenciou 18.000 leucócitos com desvio à esquerda e\na Proteína C Reativa era 35 mg/dl. Para a tomada da decisão terapêutica deste paciente, foi\nrealizada tomografia de abdome com contraste venoso que evidenciou apêndice aumentado de\nvolume, paredes espessadas, contendo fecalito no seu interior, sem sinais de perfuração ou\nabscesso. Sobre a conduta do caso, assinale a alternativa CORRETA:","options":{"A":"Por tratar-se de apendicite aguda não complicada, este paciente seria bom candidato para\nmanejo não cirúrgico, com antibioticoterapia exclusiva.","B":"Caso a tomografia evidenciasse abscesso intracavitário, a abordagem laparoscópica estaria\ncontraindicada.","C":"Se a abordagem cirúrgica confirmar os achados tomográficos, a dose única de cefoxitina durante\na indução anestésica deve ser suficiente no\ntratamento deste paciente.","D":"Os dados nos permitem afirmar que a melhor conduta para o caso é apendicectomia\nconvencional urgente, com pós-operatório em unidade de tratamento semi-intensiva."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-286726","number":"286726","sourceNumber":"286726","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo masculino, 65 anos, vem ao seu consultório trazendo consigo uma\ntomografia que o deixou bastante preocupado. O exame foi realizado na vigência de uma queda no\ndomicílio em que teve uma contusão abdominal há 2 meses atrás. O laudo desta tomografia não\nevidenciou quaisquer lesões abdominais traumáticas, porém foram observados vários divertículos\nem cólon descendente e sigmoide. O paciente nega história de dor abdominal na Fossa Ilíaca\nEsquerda, referindo apenas constipação crônica. Qual das seguintes orientações ao paciente é\nINADEQUADA?","options":{"A":"Pacientes com diagnóstico de divertículos no cólon esquerdo devem ser encaminhados para\nressecção cirúrgica dos mesmos devido ao alto risco de evolução para doença maligna.","B":"A doença diverticular dos cólons é uma condição bastante comum após os 60 anos de idade,\nprincipalmente quando o paciente apresenta constipação crônica?.","C":"A presença dos divertículos no intestino grosso não causa sintomas, porém há chances que eles\ncompliquem com episódios de sangramento ou inflamação e dor, necessitando avaliação médica\nimediata.","D":"Quadros inflamatórios leves podem ser tratados em casa, com antibióticos e dieta, no entanto\ncasos mais graves demandam internação\nhospitalar e apresentam risco de tratamento cirúrgico\nurgente, inclusive com realização de colostomia."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-286732","number":"286732","sourceNumber":"286732","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo feminino, 28 anos, é trazida por familiares para avaliação médica\ndevido a quadro de diarreia com muco e\nsangue há 2 semanas, com piora progressiva, associada a\ntenesmo e cólica em Fossa Ilíaca Esquerda (FIE) e Flanco Esquerdo (FE) de leve intensidade que\nmelhorava após a defecação. Nega vômitos e febre. Nega episódios anteriores. Encontrava-se\nbastante pálida e desidratada, taquicárdica, eupneica e normotensa. Seu abdome era plano,\nflácido, indolor à palpação. Toque retal discretamente doloroso, com sangue em dedo de luva, sem\nmassas ou nodulações palpáveis. A paciente foi então internada para investigação. Ao hemograma:\nhemoglobina 9g/dl e hematócrito 28%. Foi submetida a colonoscopia que evidenciou reto e cólon\nsigmóide com mucosas circunferencialmente acometidas, bastante hiperemiadas e friáveis,\ncontendo múltiplas úlceras rasas. Assinale a alternativa INCORRETA:","options":{"A":"Leucocitose discreta, elevados níveis de Proteína C Reativa e de Calprotectina fecal são\nesperados no perfil laboratorial desta paciente.","B":"Caso não seja tratada adequadamente, esta paciente pode evoluir com múltiplas fístulas\nperianais complexas.","C":"O tratamento inicial desta paciente possivelmente envolverá Mesalazina oral e retal e\ncorticoides.","D":"O uso de Infliximabe não está indicado neste momento do tratamento desta paciente."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-256588","number":"256588","sourceNumber":"256588","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Sobre o rastreio do câncer coloretal (CCR), qual das opções não se relaciona aos\npacientes com risco intermediário de desenvolvimento de CCR?","options":{"A":"Idade inferior a 50 anos","B":"Paciente sem história de adenoma, pólipo séssil ou CCR","C":"Paciente sem história de doença inflamatória intestinal","D":"Paciente com história familiar negativa para CCR"},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-256590","number":"256590","sourceNumber":"256590","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Enunciado está relacionado para as questões 18 e 09. Criança, estudante, masculino,\npardo, procurou o pronto atendimento médico com\nqueixa de dor abdominal iniciada há cerca de 10\ndias, acompanhado de diarréia, náuseas e vômitos. Ao exame físico apresentava dor, sinais de\ndesidratação e febre (38°C). O exame abdominal tinha peristalse débil, tenso, doloroso à palpação\nsuperficial e profunda com sinais de peritonite difusa e presença de massa palpável em fossa ilíaca\ndireita. Demais aparelhos e sistemas sem alterações. Suspeitando de um abdome agudo\ninflamatória qual seria sua hipótese?","options":{"A":"Trombose Mesentérica","B":"Apendicite Aguda Perfurada","C":"Doença Inflamatória Pélvica","D":"Diverticulite"},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-256591","number":"256591","sourceNumber":"256591","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Enunciado está relacionado para as questões 18 e 09. Criança, estudante, masculino,\npardo, procurou o pronto atendimento médico com\nqueixa de dor abdominal iniciada há cerca de 10\ndias, acompanhado de diarréia, náuseas e vômitos. Ao exame físico apresentava dor, sinais de\ndesidratação e febre (38°C). O exame abdominal tinha peristalse débil, tenso, doloroso à palpação\nsuperficial e profunda com sinais de peritonite difusa e presença de massa palpável em fossa ilíaca\ndireita. Demais aparelhos e sistemas sem alterações. Quais exames laboratoriais devemos\nsolicitar?","options":{"A":"Hemograma Completo, Coagulograma, TAP, sódio, cloro, potássio e EAS","B":"Hemograma Completo, Bilirrubinas, Proteínas e Amilase","C":"Coagulograma, EAS, Proteínas e TAP","D":"Hemograma Completo, TGO, TGP, Gama GT, FAL, Proteínas e VHS"},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-252233","number":"252233","sourceNumber":"252233","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Menor de 12 anos, estudante, masculino, pardo, procurou atendimento médico por\nqueixa de dor abdominal iniciada há cerca de\n12 dias. Relatava durante o período episódios de\ndiarreia, náuseas e vômitos. O exame físico demonstrava dor, sinais de desidratação e febre\n(38°C). O exame abdominal tinha peristalse débil, tenso, doloroso à palpação superficial e profunda\ncom sinais de peritonite difusa e presença de massa palpável em fossa ilíaca direita. Demais\naparelhos e sistemas sem alterações. Qual seria a melhor conduta nesse paciente?","options":{"A":"Lavado peritoneal o mais precoce possível.","B":"Aguardar e esgotar todos os exames por imagem para darmos início a um tratamento clínico a\nnível domiciliar.","C":"Indicar laparotomia exploradora baseado nos achados de história e exame físico.","D":"Antibioticoterapia para esfriar o processo."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-252239","number":"252239","sourceNumber":"252239","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Uma doença que afeta 2% da população, localizada a 2 pés da válvula ileocecal e que\nnos pacientes sintomáticos esta abaixo de 2\nanos de idade:","options":{"A":"Ileite congênita.","B":"Divertículo falso de Meckel.","C":"Intussuscepção.","D":"Divertículo verdadeiro de Meckel."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-252240","number":"252240","sourceNumber":"252240","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Qual a principal causa de abdome agudo na gestante?","options":{"A":"Diverticulite aguda.","B":"Colecistite aguda.","C":"Ileite aguda.","D":"Apendicite aguda."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-208311","number":"208311","sourceNumber":"208311","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Malformação congênita, localizada na borda antimesentérica do íleo terminal refere-se\na:","options":{"A":"Bandas de Ladd.","B":"Divertículo de Meckel.","C":"Onfalocele.","D":"Cisto mesentérico."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-208326","number":"208326","sourceNumber":"208326","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A classificação de Hinchey é utilizada:","options":{"A":"No Cisto de Colédoco","B":"Na Hérnia Inguinal","C":"Na Pancreatite","D":"Na Diverticulite"},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-208335","number":"208335","sourceNumber":"208335","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente alcoólatra, com vários episódios eméticos prévios, apresenta hematêmese. Na\nEndoscopia Digestiva Alta evidencia-se lacerações tipo fissuras na mucosa e submucosa do\nesôfago, próximo a junção gástrica. Corresponde a qual patologia?","options":{"A":"Úlcera de Marjolin","B":"Síndrome de Mallory Weiss","C":"Esofago de Barret","D":"Lesão de Dieulafoy"},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-208419","number":"208419","sourceNumber":"208419","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo masculino, 70 anos, hipertenso e cardiopata, dá entrada no serviço\nde pronto atendimento com quadro de\nhematoquezia e evoluiu com vários episódios de\nenterorragia, há 24 horas. O paciente se encontra hipocorado ++/4, FC: 100 bpm, FR: 26 irpm, PA:\n110 x60 mmHg. Seu exame físico do abdome não revelou alterações. Realizou um hemograma que\ndemonstrou hematócrito de 27% e hemoglobina 9 g/dL. Assinale a alternativa INCORRETA:","options":{"A":"Uma vez que o paciente apresenta instabilidade hemodinâmica, a abordagem mais efetiva para\no caso é a laparotomia urgente para a\ndefinição do foco do sangramento e sua resolução.","B":"Há uma incidência crescente das hemorragias digestivas baixas no mundo devido ao aumento\nda idade da população associado ao uso crônico\nde anticoagulantes.","C":"A principal hipótese etiológica para o caso é o sangramento de divertículo no cólon direito,\nporém a angiodisplasia e a neoplasia de cólon são diagnósticos diferenciais.","D":"A endoscopia digestiva alta e a tomografia com contraste venoso podem fazer parte do\norganograma de investigação deste paciente."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-208405","number":"208405","sourceNumber":"208405","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo masculino, 16 anos, dá entrada no pronto atendimento com quadro\nde dor tipo cólica em epigástrio, que migrou\npara a FID (Fossa ilíaca direita), associada a vômitos.\nEvolução de 3 dias. Refere 1 episódio de febre baixa hoje. Nega diarreia e sintomas urinários. O\nPaciente está em bom estado geral, eupneico, afebril, normotenso. Seu abdome é plano, flácido,\ndoloroso à palpação profunda em FID, com discreto plastrão palpável. Sinal de Blumberg positivo.\nLeucograma: 14.000 mil/mm³. USG prejudicada por excesso de gases, evidenciando apenas\npequena quantidade de líquido livre em FID e pelve. Assinale a alternativa CORRETA:","options":{"A":"A abordagem cirúrgica laparoscópica é factível para o caso acima mesmo em situação de\nperitonite purulenta.","B":"Por tratar-se de paciente jovem, imunocompetente, hemodinamicamente estável, afebril e com\ndoença em fase inicial de evolução, o\ntratamento exclusivo com antibióticos pode ser tentado,\ndevendo ser instituído tratamento cirúrgico se não houver melhora após 48h.","C":"Já que a USG não foi adequada para o diagnóstico e estadiamento da doença, o próximo passo\nna conduta deste paciente é a realização de\ntomografia.","D":"A observação de níveis hidroaéreos à radiografia de abdome confirmaria a necessidade de\ntratamento cirúrgico."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-176069","number":"176069","sourceNumber":"176069","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo feminino, 72 anos, internada há 7 dias devido ao quadro de diarreia\nmucossanguinolenta (cerca de 3 episódios ao dia), acompanhada de leve dor abdominal difusa,\ntipo cólica, tontura e astenia. Não apresentou febre no período. Nega diabetes e outras\ncomorbidades. Deu entrada com sinais de hipovolemia leve que melhoraram após expansão com\ncristaloides. Seus exames laboratoriais evidenciam leucograma = 14.000; hematócrito = 32%;\nhemoglobina = 11 g/dl; VHS = 10 mm/h e albumina sérica normal. Foi submetida à colonoscopia\nque evidenciou múltiplas úlceras rasas, coalescentes, friáveis, que acometiam cólon descendente,\nsigmoide e reto, circunferencialmente, poupando a região anal. Assinale a alternativa CORRETA:","options":{"A":"Há indicação de investigação tomográfica para avaliar a possibilidade de metástases hepáticas.","B":"Há indicação de retossigmoidectomia de urgência devido ao quadro de megacólon tóxico com\npossível evolução para perfuração e peritonite.","C":"O exame histopatológico provavelmente evidenciará glândulas da mucosa de arquitetura\naberrante, com atipia celular, infiltrado\nneutrofílico ausente e padrão invasivo de camadas\nprofundas da parede do cólon.","D":"A mesalazina e corticoides provavelmente farão parte do tratamento desta paciente."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-176098","number":"176098","sourceNumber":"176098","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo masculino, 38 anos, vem ao pronto-socorro apresentando dor\nabdominal severa associada a dor\nretroesternal. O quadro iniciou há 12h, após o paciente retornar\nde uma festa onde ingeriu grande quantidade de álcool, que ocasionou desconforto abdominal,\nnáuseas e vários episódios de vômitos vigorosos, evoluindo com o quadro doloroso. Nega\nhematêmese. O paciente encontra-se bastante ansioso, com fácies de dor, desidratado e febril\n(38,8°C), FC = 120 bpm, P.A = 100 x 70 mmHg; FR = 30 irpm. A ausculta pulmonar evidenciou\ndiminuição do murmúrio vesicular em base esquerda. Ausculta cardíaca normal. A palpação do\nepigástrio é dolorosa, com defesa voluntária. Leucograma = 26.000; hematócrito = 37% e\nhemoglobina = 11 g/dl. Amilase e enzimas hepáticas normais. ECG normal, exceto pela taquicardia.\nRadiografia de tórax evidencia discreta efusão pleural e pneumotórax à esquerda, além de\npneumomediastino. Sobre a avaliação e conduta deste paciente, assinale a alternativa CORRETA:","options":{"A":"O próximo passo na avaliação deste paciente é a endoscopia digestiva alta pelo provável\ndiagnóstico de síndrome de Mallory-Weiss.","B":"A história de ingesta alcoólica sugere lesão aguda da mucosa gástrica e esofagite de refluxo,\nestando indicado o tratamento clínico com bloqueadores de bomba de prótons.","C":"Tomografia computadorizada de tórax com contraste oral e toracotomia precoce provavelmente\nserão decisivos no prognóstico deste paciente.","D":"O esofagograma baritado é o exame mais indicado para o diagnóstico do caso neste momento."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-176097","number":"176097","sourceNumber":"176097","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A complicação de prolapso dos estomas intestinais é mais frequente em alça de qual\nsegmento colônico?","options":{"A":"Transverso.","B":"Ceco.","C":"Ascendente.","D":"Descendente."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-176058","number":"176058","sourceNumber":"176058","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Assinale a alternativa CORRETA sobre tumores carcinoides:","options":{"A":"A maioria dos pacientes com esses tumores apresentam a síndrome carcinoide, que inclui\nmanifestações vasomotoras, cardíacas e gastrointestinais.","B":"Quando ocorrem no intestino delgado, o duodeno é o local mais acometido.","C":"Não apresentam potencial de malignidade.","D":"No trato gastrointestinal, o local mais afetado é o apêndice."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-151877","number":"151877","sourceNumber":"151877","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Qual a localização mais frequente dos tumores carcinoides?","options":{"A":"Intestino Delgado.","B":"Trato respiratório.","C":"Pâncreas.","D":"Reto."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-151886","number":"151886","sourceNumber":"151886","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Sobre a doença celíaca, podemos afirmar que:","options":{"A":"São fatores de risco para doença celíaca os indivíduos com diabete melito tipo I e II, doença\nautoimune da tireoide, cirrose biliar primária, síndrome de Turner e síndrome de Down.","B":"A amamentação e o tempo de introdução do trigo na dieta podem reduzir o risco ou atrasar o\naparecimento da doença celíaca em crianças sob risco.","C":"O tratamento da doença celíaca previne a progressão da doença, porém não há remissão com\nmelhora do padrão histológico.","D":"O tratamento é realizado com corticoide, seguido de manutenção com azatioprina."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-324674","number":"324674","sourceNumber":"324674","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente, sexo feminino, 65 anos de idade, procura o Pronto Socorro por\nempachamento e distensão abdominal há cinco\ndias. A paciente apresentou náuseas e alguns\nepisódios de vômitos nas últimas 24 horas. Relata, também, hiporexia, perda de peso e obstipação\nprogressiva, há três meses, não sendo investigada previamente. A paciente realizou artroplastia\ntotal de quadril esquerdo há 5 anos. Ao exame físico, regular estado geral, corada, desidratada, T\naxilar: 36ºC, FC: 88bpm, PA: 128x78mmHg, FR: 24imp; ausculta cardíaca e respiratória sem\nalterações; abdome distendido, tenso, com dor à palpação difusa e com descompressão brusca\nnegativa; toque retal sem alterações. Foi realizada radiografia de abdome. Diante desse caso\nclínico e da análise do exame de imagem, indique a principal suspeita etiológica que levou a\npaciente a procurar o Pronto Socorro.","options":{"A":"Aderência intestinal.","B":"Volvo de sigmoide.","C":"Neoplasia maligna de cólon.","D":"Fecaloma."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-324675","number":"324675","sourceNumber":"324675","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente, sexo feminino, 65 anos de idade, procura o Pronto Socorro por\nempachamento e distensão abdominal há cinco\ndias. A paciente apresentou náuseas e alguns\nepisódios de vômitos nas últimas 24 horas. Relata, também, hiporexia, perda de peso e obstipação\nprogressiva, há três meses, não sendo investigada previamente. A paciente realizou artroplastia\ntotal de quadril esquerdo há 5 anos. Ao exame físico, regular estado geral, corada, desidratada, T\naxilar: 36ºC, FC: 88bpm, PA: 128x78mmHg, FR: 24imp; ausculta cardíaca e respiratória sem\nalterações; abdome distendido, tenso, com dor à palpação difusa e com descompressão brusca\nnegativa; toque retal sem alterações. Foi realizada radiografia de abdome. Indique o exame\ncomplementar que deveria ter sido realizado há três meses, no momento em que se iniciaram os\nprimeiros sintomas.","options":{"A":"Tomografia computadorizada com contraste.","B":"Colonoscopia.","C":"Radiografia de abdome.","D":"Ultrassonografia de abdome."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-324676","number":"324676","sourceNumber":"324676","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente, sexo feminino, 65 anos de idade, procura o Pronto Socorro por\nempachamento e distensão abdominal há cinco\ndias. A paciente apresentou náuseas e alguns\nepisódios de vômitos nas últimas 24 horas. Relata, também, hiporexia, perda de peso e obstipação\nprogressiva, há três meses, não sendo investigada previamente. A paciente realizou artroplastia\ntotal de quadril esquerdo há 5 anos. Ao exame físico, regular estado geral, corada, desidratada, T\naxilar: 36ºC, FC: 88bpm, PA: 128x78mmHg, FR: 24imp; ausculta cardíaca e respiratória sem\nalterações; abdome distendido, tenso, com dor à palpação difusa e com descompressão brusca\nnegativa; toque retal sem alterações. Foi realizada radiografia de abdome. Indique a conduta\ncirúrgica mais adequada, caso a paciente não apresente melhora com o tratamento clínico\ninstituído no Pronto Socorro.","options":{"A":"Lavagem intestinal no centro cirúrgico.","B":"Peritoneostomia descompressiva.","C":"Videolaparoscopia para reversão do volvo.","D":"Retossigmoidectomia com colostomia."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-2/324676.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-294454","number":"294454","sourceNumber":"294454","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Mulher, 21 anos de idade, procura atendimento ambulatorial para investigação de\ndiarreia crônica. Faz uso de anticoncepcional injetável. Ao exame, apresenta-se em bom estado\ngeral, descorada +/4+. Realizados exames laboratoriais, com Hb: 10,5 g/dl, ferritina: 25 ng/ml,\nvitamina D: 11 ng/dl. Solicitada endoscopia digestiva alta, com achado de redução do pregueado\nmucoso em segunda porção duodenal. Diante do quadro clínico, com relação às alterações\nesperadas para confirmação do diagnóstico mais provável, é CORRETO afirmar:","options":{"A":"As lesões acometem mais o íleo, mas podem ocorrer em todo o tubo digestivo.","B":"Os anticorpos são úteis para o diagnóstico, sendo a biópsia gástrica o padrão-ouro.","C":"A realização de uma colonoscopia é essencial para avaliação, pois as alterações são mais\nfrequentes no cólon.","D":"No anatomopatológico, observa-se redução da relação vilo/cripta e infiltração de linfócitos na\nmucosa."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-294455","number":"294455","sourceNumber":"294455","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Mulher, 21 anos de idade, procura atendimento ambulatorial para investigação de\ndiarreia crônica. Faz uso de anticoncepcional\ninjetável. Ao exame, apresenta-se em bom estado\ngeral, descorada +/4+. Realizados exames laboratoriais, com Hb: 10,5g/dL, ferritina 25ng/mL,\nvitamina D 11ng/dL. Solicitada endoscopia digestiva alta, com achado de redução do pregueado\nmucoso em segunda porção duodenal. Diante do quadro clínico, Identifique o anticorpo associado\nao diagnóstico mais provável.","options":{"A":"Anticélula parietal.","B":"Antitransglutaminase tecidual.","C":"Anti-Saccharomyces cerevisae (ASCA).","D":"Anticitoplasma de neutrófilo (ANCA)."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-294456","number":"294456","sourceNumber":"294456","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Mulher, 21 anos de idade, procura atendimento ambulatorial para investigação de\ndiarreia crônica. Faz uso de anticoncepcional injetável. Ao exame, apresenta-se em bom estado\ngeral, descorada +/4+. Realizados exames laboratoriais, com Hb: 10,5g/dL, ferritina 25ng/mL,\nvitamina D 11ng/dL. Solicitada endoscopia digestiva alta, com achado de redução do pregueado\nmucoso em segunda porção duodenal. Diante do quadro clínico, Indique a conduta terapêutica\ninicial mais adequada.","options":{"A":"Suspender o metódo contraceptivo.","B":"Adotar dieta isenta de glúten.","C":"Realizar corticoterapia.","D":"Fazer uso de Imunobiológico."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-284589","number":"284589","sourceNumber":"284589","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente, sexo feminino, 30 anos de idade, é levada ao pronto-socorro do Hospital\nRegional com história de dor em abdome\ninferior, de moderada intensidade, há 12 horas, sem\nmelhora com analgésico comum. A paciente refere também hiporexia, alguns episódios de náuseas\ne vômitos, disúria e polaciúria há dois dias. Nega outros sintomas e comorbidades. Ao exame físico,\nbom estado geral, corada, desidratada +1/+4, FC: 94 bpm, PA: 110 x 74 mmHg, FR: 18 imp, T:\n37,9ºC; auscultas cardíaca e respiratória sem alterações; abdome um pouco distendido, ruídos\nhidroaéreos um pouco aumentados difusamente, flácido, dor à palpação profunda de hipogástrio,\nsinal de Giordano negativo. Realizados exames laboratoriais que apresentaram Hb: 12 g/dl, Ht =\n36%, Leucócitos totais: 14.000 células/mm³ (Bastões 4%), Ureia: 35 mg/dl, Creatinina: 1,0 mg/dl,\nNa: 142 mEq/L. Exame de urina: leucócitos 1.000.000 céls/ml, hemácias 1.000.000 céls/ml. Foi\nrealizada tomografia computadorizada de abdome. Indique a principal suspeita diagnóstica que\nmotivou a paciente a procurar o pronto-socorro.","options":{"A":"Cistite aguda.","B":"Doença inflamatória pélvica aguda.","C":"Apendicite aguda.","D":"Gravidez ectópica."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-2/284589.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-284590","number":"284590","sourceNumber":"284590","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente, sexo feminino, 30 anos de idade, é levada ao pronto-socorro do Hospital\nRegional com história de dor em abdome\ninferior, de moderada intensidade, há 12 horas, sem\nmelhora com analgésico comum. A paciente refere também hiporexia, alguns episódios de náuseas\ne vômitos, disúria e polaciúria há dois dias. Nega outros sintomas e comorbidades. Ao exame físico,\nbom estado geral, corada, desidratada +1/+4, FC: 94 bpm, PA: 110 x 74 mmHg, FR: 18 imp, T:\n37,9ºC; auscultas cardíaca e respiratória sem alterações; abdome um pouco distendido, ruídos\nhidroaéreos um pouco aumentados difusamente, flácido, dor à palpação profunda de hipogástrio,\nsinal de Giordano negativo. Realizados exames laboratoriais que apresentaram Hb: 12 g/dl, Ht =\n36%, Leucócitos totais: 14.000 células/mm³ (Bastões 4%), Ureia: 35 mg/dl, Creatinina: 1,0 mg/dl,\nNa: 142 mEq/L. Exame de urina: leucócitos 1.000.000 céls/ml, hemácias 1.000.000 céls/ml. Foi\nrealizada tomografia computadorizada de abdome. Identifique outro exame complementar que\npoderia ajudar na confirmação do diagnóstico dessa paciente.","options":{"A":"Ultrassonografia de rins e vias urinárias.","B":"Dosagem de beta HCG sérico.","C":"Videolaparoscopia.","D":"Radiografia de abdome agudo."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-2/284590.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-284591","number":"284591","sourceNumber":"284591","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente, sexo feminino, 30 anos de idade, é levada ao pronto-socorro do Hospital\nRegional com história de dor em abdome\ninferior, de moderada intensidade, há 12 horas, sem\nmelhora com analgésico comum. A paciente refere também hiporexia, alguns episódios de náuseas\ne vômitos, disúria e polaciúria há dois dias. Nega outros sintomas e comorbidades. Ao exame físico,\nbom estado geral, corada, desidratada +1/+4, FC: 94 bpm, PA: 110 x 74 mmHg, FR: 18 imp, T:\n37,9ºC; auscultas cardíaca e respiratória sem alterações; abdome um pouco distendido, ruídos\nhidroaéreos um pouco aumentados difusamente, flácido, dor à palpação profunda de hipogástrio,\nsinal de Giordano negativo. Realizados exames laboratoriais que apresentaram Hb: 12 g/dl, Ht =\n36%, Leucócitos totais: 14.000 células/mm³ (Bastões 4%), Ureia: 35 mg/dl, Creatinina: 1,0 mg/dl,\nNa: 142 mEq/L. Exame de urina: leucócitos 1.000.000 céls/ml, hemácias 1.000.000 céls/ml. Foi\nrealizada tomografia computadorizada de abdome. Indique o tratamento mais adequado que deve\nser instituído.","options":{"A":"Prescrever antibiótico e internar.","B":"Prescrever antibiótico oral para casa.","C":"Internar e prescrever metotrexato.","D":"Realizar laparotomia exploradora."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-2/284591.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-358777","number":"358777","sourceNumber":"358777","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A dor abdominal aguda é uma queixa frequente na APS, e não é raro ver pacientes\ncom esta queixa apresentarem quadros que\nnecessitem de intervenções mais urgentes. Analise as\nalternativas a seguir sobre a abordagem da dor abdominal aguda na APS e assinale a correta.","options":{"A":"A obstrução intestinal se caracteriza por dor em cólicas de localização dependente do local da\nobstrução e embora normalmente curse com parada da eliminação de fezes, casos de\n\nsemi-oclusão podem cursar com diarreia paradoxal.","B":"A presença do sinal de Murphy confirma o diagnóstico de colecistite aguda e os pacientes\ndevem receber uma dose de antibiótico enquanto aguardam encaminhamento ao serviço de\ncirurgia de urgência.","C":"Pacientes com dor em faixa em abdome superior têm suspeita aumentada de pancreatite, que\nexige intervenção cirúrgica imediata.","D":"Dor periumbilical com irradiação para fossa ilíaca direita com defesa voluntária à palpação local\ntem sido descritas como sinal sugestivo de apendicite aguda, porém menos da metade das\npessoas com quadro semelhante tem confirmação deste diagnóstico após cirurgia.","E":"Dor em flanco com irradiação para as costas e para a região genital levanta a suspeita de\nurolitíase, e a melhor opção de manejo da dor é a administração de antiespasmódicos por via\nvenosa."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-343355","number":"343355","sourceNumber":"343355","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A conduta mais adequada para este quadro é:","options":{"A":"Cirurgia de emergência.","B":"Correção de distúrbios hidroeletrolíticos e ácido-base, e cirurgia de urgência assim que\nestabilização clínico-laboratorial.","C":"Redução hidrostática ou pneumática.","D":"Correção de distúrbios hidroeletrolíticos e ácido-base e redução do volume da dieta em 30%,\ninibidor de bomba de prótons e reavaliação em 1 semana."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-343362","number":"343362","sourceNumber":"343362","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Jovem, masculino, há 3 dias com hiporexia, náuseas, desconforto epigástrico,\nqueixando-se hoje de piora da dor, mais\nlocalizada em fossa ilíaca direita associada a 2 picos de\nfebre aferida. Ao exame físico: bom estado geral, corado, hidratado, eupneico, anictérico. Exame\nfísico cardiopulmonar normal, exceto leve taquicardia. Ruídos abdominais presentes, sem\nalterações na inspeção, porém com dor a palpação de fossa ilíaca direita. Sinal de Blumberg\npresente. Foi submetido a exames laboratoriais que resultaram em um escore de Alvarado de 10\npontos. Não há exames de imagem disponível no serviço. A conduta mais adequada é:","options":{"A":"Transferência para realizar tomografia de abdome.","B":"Cirurgia.","C":"Alta com sintomáticos.","D":"Anti-inflamatório não hormonal e reavaliação em 48h."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-343363","number":"343363","sourceNumber":"343363","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente feminina, 80 anos, internada com diverticulite aguda, submeteu-se à\ntomografia de abdome com contraste endovenoso\nque evidenciou processo inflamatório colônico\ncom divertículos e a presença de coleção pélvica bloqueada. Trata-se de diverticulite aguda,\nclassificada por Hinchey (clássica) em grau:","options":{"A":"II","B":"III","C":"IV","D":"IV"},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-314289","number":"314289","sourceNumber":"314289","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo masculino, 22 anos de idade, proveniente do interior da Bahia com\nqueixa de diarreia aquosa, três dejeções ao dia, há dois meses, por vezes associada a esteatorréia\ne astenia. A alternativa que contém agentes infecciosos causadores de diarreia disabsortiva é","options":{"A":"Entamoeba coli e Taenia glabrata","B":"Ascaris lumbricoides e Endolimax nana","C":"Strongyloides stercoralis e Giardia lamblia","D":"Clostridioide (Clostridium) difficile e Salmonella","E":"Schistosoma mansoni e Entamoeba histolytica"},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-281874","number":"281874","sourceNumber":"281874","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Nos quadros de diverticulite aguda, pela classificação tomográfica de Hinchey, o\nachado de abscesso pélvico, é classificado em:","options":{"A":"Hinchey I","B":"Hinchey II","C":"Hinchey III","D":"Hinchey IV"},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-281876","number":"281876","sourceNumber":"281876","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente de 72 anos, hipertensa e diabética, queixando-se de dor abdominal de início\nhá 2 dias associada a vômitos, distensão\nabdominal e redução da eliminação de flatos e fezes.\n\nRelata que nos últimos meses apresentou várias crises de cólicas abdominais necessitando de\nmedicação endovenosa para alívio. Nega febre. Nega perda ponderal. Nega sangramento\ngastrointestinal. Ao exame: regular estado geral, desidratada +/4+, corada, anictérica, acianótica,\nafebril. Abdome distendido, com ruídos presentes doloroso a palpação difusa, mas sem sinais de\nirritação peritoneal. Toque retal com ampola vazia. Pela hipótese de síndrome obstrutiva, realizou a\ntomografia de abdome abaixo. A principal hipótese diagnóstica é:","options":{"A":"Síndrome de Bouveret Duodenal.","B":"Cólon Biliar.","C":"Neoplasia de Sigmoide.","D":"Síndrome Ogilvie."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-2/281876.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-249977","number":"249977","sourceNumber":"249977","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Na Doença de Crohn (DC) os pacientes com infecções ou abscessos devem receber\nantibioticoterapia apropriada com drenagem cirúrgica ou percutânea, sendo correto que:","options":{"A":"Conforme o mais apropriado, considerando as condições assistenciais do local de atendimento.","B":"Conforme o mais apropriado, independente das condições assistenciais do local de atendimento.","C":"Independentemente de ser o mais apropriado, considerando as condições assistenciais do local\nde atendimento.","D":"Conforme o menos apropriado, considerando as condições assistenciais e não do local de\natendimento."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-249714","number":"249714","sourceNumber":"249714","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A causa mais frequente de hemorragia digestiva baixa em pacientes na sexta e sétima\ndécadas de vida é:","options":{"A":"neoplasia.","B":"angiodisplasia.","C":"polipose colônica.","D":"doença hemorroidária.","E":"doença diverticular do cólon."},"answer":"E","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-249985","number":"249985","sourceNumber":"249985","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Sobre a terapia da doença de Crohn assinale a alternativa correta:","options":{"A":"O corticoide é útil para induzir a remissão da doença e mantê-la.","B":"A azatioprina é útil para induzir a remissão da doença e mantê-la.","C":"A azatioprina é útil para manter a remissão da doença.","D":"O corticoide é útil para manter a remissão da doença."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-249986","number":"249986","sourceNumber":"249986","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A aterapia biológica com anti-TNF, infliximabe ou adalimumabe é útil na doença de\nCrohn para:","options":{"A":"Induzir a remissão da doença e mantê-la.","B":"Curar a doença.","C":"Induzir a remissão da doença sem mantê-la.","D":"Manter a remissão da doença sem induzi-la."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-249992","number":"249992","sourceNumber":"249992","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente masculino, 18 anos, sem comorbidades, há 2 dias com hiporexia, náuseas,\nassociado a desconforto epigástrico,\nprocurou pronto-socorro hoje, pois a dor havia piorado, mais\nintensa, mais localizada em fossa ilíaca direita junto com 2 picos de febre aferida. Nega vômitos.\nAo\nexame, bom estado geral, corado, hidratado, eupneico, anictérico. Exame físico cardiopulmonar\nnormal, exceto por frequência cardíaca de 112 bpm. Ao exame abdominal: ruídos presentes, sem\nalterações na inspeção, porém com dor a palpação de fossa ilíaca direita. Sinal de Blumberg\npresente. Foi submetido a exames laboratoriais que, somado aos dados acima resultaram em um\nescore de Alvarado de 09 pontos. Não há exames de imagem disponível no serviço. A conduta\nmais adequada é:","options":{"A":"Transferência imediata para realizar ecografia de abdome.","B":"Jejum, hidratação, analgesia e transferência para exames de imagem.","C":"Apendicectomia.","D":"Alta com sintomáticos."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-249993","number":"249993","sourceNumber":"249993","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Jovem de 19 anos após abuso de cocaína dá entrada em sala de emergência trazido\npelo serviço de resgate apresentando hematêmese\nfranca, em grande volume, de início há 10\nminutos. Na admissão em sala de emergência apresenta-se em mal estado geral, descorado,\npálido, comatoso, apresentando vários episódios de vômitos em grande quantidade. Pressão\narterial: 80x40mmHg, Frequência cardíaca: 145bpm, Frequência respiratória: 31irpm, Saturação de\noxigênio periférica: 89%. A conduta mais adequada neste momento, respectivamente por ordem de\nprioridade é:","options":{"A":"1- Endoscopia digestiva alta para diagnóstico e tratamento da lesão; 2- intubação orotraqueal; 3-\nreposição volêmica.","B":"1- Endoscopia digestiva alta para diagnóstico e tratamento da lesão; 2- reposição volêmica; 3-\nintubação orotraqueal.","C":"1- Intubação orotraqueal; 2-endoscopia digestiva alta para tratamento da lesão; 3- reposição\nvolêmica.","D":"1-Intubação orotraqueal e reanimação volêmica; 2- endoscopia digestiva alta para diagnóstico e\ntratamento."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-249995","number":"249995","sourceNumber":"249995","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Idoso, 68 anos, queixando-se de dor abdominal há 4 dias, mais localizada em fossa\nilíaca esquerda, associada à febre, diarreia e\nqueda do estado geral. Queixa-se também de disúria.\nNega vômitos. Foi internado para investigação e realizado tomografia abdominal com contraste\nendovenoso (imagem abaixo). Ao exame físico: regular estado geral, corada, hidratada. Aparelho\ncardiopulmonar sem alterações. Abdome com ruídos presentes, flácido, doloroso em fossa ilíaca\nesquerda e hipogástrio, sem sinais de peritonite. Hemograma com leucocitose, função renal normal,\ne exame de urina com leucocitúria abundante. Assinale a alternativa correta:","options":{"A":"Trata-se de diverticulite aguda simples - Hinchey II.","B":"Trata-se de diverticulite aguda, complicada com fístula colovesical.","C":"Trata-se de doença diverticular do cólon complicada com abscesso em loja renal esquerda.","D":"Trata-se de diverticulite aguda complicada, Hinchey III, com sinais tomográficos de\npneumoperitônio."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-2/249995.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-218122","number":"218122","sourceNumber":"218122","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Considerando a classificação do abdome agudo, segundo a natureza do processo\ndeterminante, numere a segunda coluna de acordo\ncom a primeira. (1) Perfurante; (2) Obstrutivo;\n\n(3) Inflamatório; ( ) Apendicite; ( ) Cálculo biliar; ( ) Úlcera péptica; ( ) Hérnia estrangulada. A\nalternativa que contém a sequência CORRETA, de cima para baixo, é:","options":{"A":"1, 2, 3, 3.","B":"2, 2, 3, 1.","C":"2, 3, 1, 3.","D":"3, 2, 1, 2.","E":"3, 1, 2, 1."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-215583","number":"215583","sourceNumber":"215583","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A apendicite aguda é a causa mais comum de urgência abdominal aguda\n\nnão-traumática na criança entre os 4 e os 15 anos de idade. Assinale a alternativa INCORRETA.","options":{"A":"O principal fator desencadeante da apendicite aguda é a obstrução intrínseca da luz apendicular,\ncom proliferação bacteriana, que é seguida de\nprocesso inflamatório inicial.","B":"O diagnóstico da apendicite aguda é eminentemente clínico e evidenciado pela palpação do\nabdome, onde se observa dor localizada na fossa ilíaca direita.","C":"Devem ser consideradas no diagnóstico diferencial: gastroenterocolite, diverticulite de Meckel,\ninfecções urinárias, adenite mesentérica, peritonite primária, pneumonia, entre outros.","D":"A complicação mais frequente no pós-operatório da apendicectomia é a formação de abscessos\nintraperitoneais."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-157725","number":"157725","sourceNumber":"157725","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Sobre as síndromes polipoides, indique a alternativa falsa:","options":{"A":"A polipose adenomatosa familiar está associada à mutação no gene APC, situado no braço\nlongo do cromossomo 5q21. Essa mutação determina polipose gastrointestinal e diversas\nmanifestações extracolônicas.","B":"Desde a descrição original de polipose associada a cistos epidermoides e osteoma, a\ncombinação de polipose adenomatosa familiar e\nmanifestações extracolônicas é conhecida como\nSíndrome de Turcot.","C":"Todas as células do epitélio colunar em portadores da polipose adenomatosa familiar possuem\nmutação germinativa do gene APC, por esta razão é indicado colectomia profilática.","D":"A associação de pigmentação mucocutânea e polipose gastrointestinal é encontrada na\nsíndrome de Peutz-Jeghers. O potencial de\nmalignidade já foi descrita por numerosos autores,\nacumulando evidências suficientes que sugerem um risco aumentado para desenvolver neoplasias\nno trato digestivo."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-139791","number":"139791","sourceNumber":"139791","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Em crianças com doença celíaca, o tratamento dietético está baseado em:","options":{"A":"Evitar ingestão de arroz e milho.","B":"Evitar ingestão de alimentos que contenham cevada, trigo, centeio e aveia.","C":"Suspender o leite de vaca e seus produtos da alimentação habitual da criança.","D":"Evitar ingestão de alimentos que contenham cacau."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-139790","number":"139790","sourceNumber":"139790","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Criança, 2 anos de idade, apresenta quadro diarreico há 1 ano com episódios\nesporádicos de vômitos, hiporexia,\nirritabilidade, déficit de crescimento, distensão abdominal,\ndiminuição do tecido celular subcutâneo e atrofia da musculatura glútea. A mãe relata que as\nfezes são volumosas, fétidas e gordurosas. Acerca desse caso clínico, assinale a alternativa que\napresenta a PRINCIPAL hipótese diagnóstica.","options":{"A":"Doença celíaca.","B":"Má rotação intestinal.","C":"Megacólon congênito.","D":"Giardíase."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-350868","number":"350868","sourceNumber":"350868","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Mulher de 31 anos com quadro de dor abdominal de início há 3 dias, em região\nperiumbilical, associada a distensão, diarreia e\nvômitos. O vômito tem aspecto esverdeado com\nresíduos alimentares, evoluindo para vômitos biliosos. A diarreia é líquida e com pouco resíduo.\nRealizou cirurgia há 2 semanas para histerectomia transabdominal devido a mioma volumoso. Uma\nradiografia é solicitada. Qual o diagnóstico mais provável?","options":{"A":"Diarreia por abscesso pélvico.","B":"Obstrução intestinal por brida.","C":"Semiobstrução intestinal.","D":"Íleo paralítico."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-350867","number":"350867","sourceNumber":"350867","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Uma paciente de 37 anos é submetida a ressecção extensa de intestino: dois terços\ndistais do delgado e ressecção do colon\nascendente, devido a vasculite lúpica com isquemia\naguda. Ao final da cirurgia, restaram 1,2 metros de delgado proximal e cólon a partir do ângulo\nhepático. Uma anastomose entre delgado e cólon é realizada. porém a paciente estará com\nintestino bastante encurtado. Qual a principal deficiência alimentar esperada para essa paciente?","options":{"A":"Anemia megaloblástica.","B":"Distúrbio eletrolítico.","C":"Deficiência proteica.","D":"Desidratação."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-350865","number":"350865","sourceNumber":"350865","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Mulher de 54 anos hipertensa e diabética, em uso habitual de suas medicações, é\nsubmetida a drenagem percutânea de abscesso hepático em segmento VIII, um dreno do tipo \"pig\ntail\" é deixado. A drenagem foi eficaz e inicialmente correspondeu a 360ml de aspecto\nachocolatado. Dois dias depois do procedimento, a paciente refere fezes pretas e mal cheirosas,\ncerca de 5 episódios, drenagem sanguinolenta pelo dreno e vômitos com sangue. Ao exame está\npálida, tendo sido iniciado reposição volêmica e de hemoderivados. Sua hemoglobina estava\n7,5g/dl antes da transfusão. Coagulograma normal. Apesar das medidas, o aspecto da fezes e do\ndreno continua inalterado. Qual medida deve ser submetida essa paciente nesse momento?","options":{"A":"Retirada do dreno \"pig tail\" e observação.","B":"Embolização hepática por cateterização arterial.","C":"Seguestrectomia hepática ou destelhamento do abscesso.","D":"Colangiografia endoscópica retrógrada e passagem de stent."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-350860","number":"350860","sourceNumber":"350860","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente de 35 anos, previamente saudável, compareceu à consulta com história de 3\nmeses de episódios de rubor facial intermitente que se tornou mais frequente e intenso no último\nmês, e ainda associado a diarreia profusa. Ao exame: intensa hiperemia facial e tronco superior.\nPA: 110x50mmHg, sem história de hipertensão. Uma ultrassonografia do abdome identificou\ndiversos nódulos hepáticos. Qual exame deve ser solicitado para confirmação diagnóstica?","options":{"A":"Gastrina sérica.","B":"Cortisol sérico e urinário.","C":"Metanefrinas sérica e urinária.","D":"5 hidroxiindolacético urinário."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-350820","number":"350820","sourceNumber":"350820","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um adolescente de 13 anos de idade vem ao ambulatório com queixas de longa\nduração de diarreia, dor abdominal e perda de\npeso. Em consulta anterior, o médico comentou a\nparada no crescimento e a presença de anemia. Também apresenta picos febris e lesões de pele.\nNão há sangue nas fezes nem sangramento retal. Qual a principal hipótese diagnóstica?","options":{"A":"Colite ulcerativa.","B":"Doença de Crohn.","C":"Alergia Alimentar Múltipla.","D":"Distúrbios funcionais de defecação."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-321285","number":"321285","sourceNumber":"321285","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Homem de 56 anos, previamente saudável, comparece à emergência com queixa de\ndor na Fossa Ilíaca Esquerda (FIE) e\nobstipação progressiva há 4 dias. O paciente não defeca há 2\ndias e elimina poucos flatos. Refere ainda 2 episódios de febre 38 graus Celsius. Ao exame: bom\nestado geral, FC 96 bpm, abdome algo distendido, RHA diminuídos, flácido a palpação com defesa\nem FIE, onde se palpa um plastrão. Exames: leucócitos 16.000 mm³ e PCR 15 mg/dl. Tomografia\nmostra distensão colônica moderada, espessamento da parede de sigmoide com borramento\ndiscreto da gordura mesocólica adjacente. Sem outros achados. Qual a melhor conduta para esse\npaciente?","options":{"A":"Tratar com antibióticos venosos e programar colectomia eletiva.","B":"Indicar colostomia proximal, antibióticos para aliviar essa crise.","C":"Realizar colectomia com colostomia à Hartman nesse internamento.","D":"Tratar com antibióticos orais e manter uma dieta líquida até alívio da obstipação."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-321286","number":"321286","sourceNumber":"321286","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Há pelo menos 5 anos, um jovem de 25 anos, sexo masculino, é submetido à\ncolonoscopia pois sua família é acompanhada por mutação genética do gene APC. Os achados\nforam: ausência de pólipos no reto, cerca de 20 pólipos colônicos principalmente a direita, sendo\num de cerca de 3 cm, no cécum, de aspecto vegetante e sessil que foi biopsiado. Alguns pólipos\nremovidos foram compatíveis com pólipos adenomatosos, tipo tubular e a lesão vegetante foi\ncompatível com adenocarcinoma bem diferenciado. A tomografia de abdome foi normal. Qual\nopção cirúrgica é mais adequada para esse paciente?","options":{"A":"Proctocolectomia total com linfadenectomia e anastomose ileoanal manual.","B":"Proctocolectomia total com linfadenectomia e confecção de ileostomia definitiva.","C":"Colectomia direita com linfadenectomia e confecção de anastomose ileotransversa.","D":"Colectomia total com linfadenectomia e anastomose colorretal ao nível do promontório."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-292799","number":"292799","sourceNumber":"292799","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente de 85 anos apresenta dor abdominal aguda há 48h. A dor é difusa, porém\nmais intensa em Fossa Ilíaca Direita (FID). HPP: DM e HAS compensadas com medicações. A\ntomografia sem contraste sugere apêndice espessado, líquido em FID e pelve compatível com\napendicite. Qual deve ser a conduta para esse paciente?","options":{"A":"Apendicectomia videolaparoscópica.","B":"Apendicectomia aberta infraumbilical.","C":"Drenagem percutânea e apendicectomia em 4 semanas.","D":"Colonoscopia, para avaliar neoplasia de base apendicular."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-292804","number":"292804","sourceNumber":"292804","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente cirrótico de 56 anos é admitido na emergência com hematêmese\nimportante. Os exames detectaram uma queda\nde hemoglobina de 14 g/dl (referência de exame\nrealizado 1 mês atrás) para 6 g/dl. Inicialmente, foi realizada a reposição volêmica e medicado com\ninibidor de bomba de prótons, vasopressina e vitamina K. Aparentemente, apresenta uma remissão\ndo sangramento e uma endoscopia foi solicitada. Qual das seguintes fontes de sangramento\napresenta maior risco de recorrência da hemorragia para esse paciente?","options":{"A":"Laceração de Mallory-Weiss.","B":"Varizes gastroesofágicas.","C":"Gastropatia hipertensiva.","D":"Úlcera Forrest IIb."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-259696","number":"259696","sourceNumber":"259696","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente, 72 anos, foi admitido em um hospital secundário, com história de perda\nponderal de 20 kg em 3 meses e quadro clínico\nsugestivo de abdome agudo obstrutivo. Durante a\nlaparotomia, foi evidenciada neoplasia de reto superior estenosante e grande distensão colônica à\nmontante. Qual a melhor estratégia operatória para essa laparotomia?","options":{"A":"Colostomia em alça para descompressão colônica.","B":"Colectomia total com ileorretoanastomose e linfadenectomia.","C":"Retossigmoidectomia com linfadenectomia e anastomose primária.","D":"Retossigmoidectomia com linfadenectomia e colostomia à Hartmann."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-259707","number":"259707","sourceNumber":"259707","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Criança, sexo masculino, 4 anos, acompanhado da mãe que relata sangramento retal\nmaciço há 3 horas associado à taquicardia e sonolência. Nega dor abdominal. Ao toque retal, sem\nsangue em dedo de luva. Após reposição volêmica e estabilidade hemodinâmica, foi realizada\nendoscopia digestiva alta que foi normal. Qual o diagnóstico mais provável?","options":{"A":"Trombose de veia porta.","B":"Divertículo de Meckel.","C":"Enterocolite necrotizante.","D":"Intussussepção ileo-cólica."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-259739","number":"259739","sourceNumber":"259739","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente de 3 anos é atendido no ambulatório com quadro de diarreia crônica,\nacompanhada de distensão abdominal, perda de\npeso, inapetência, alteração de humor com\nirritabilidade e vômitos esporádicos. O paciente também se apresentava emagrecido, com\ndiminuição do tecido celular subcutâneo e atrofia da musculatura glútea. Mãe trouxe um\nhemograma que apresentava anemia. Dentre as opções a seguir, a conduta mais adequada para a\nconfirmação diagnóstica dessa criança e o tratamento indicado é:","options":{"A":"A pesquisa de anticorpos IgE específicos para o leite de vaca, teste de puntura ou prick test e\ndieta de exclusão de proteína do leite de vaca.","B":"A pesquisa de anticorpos IgG específicos para o leite de vaca, teste de puntura ou prick test e\ndieta de exclusão de proteína do leite de vaca.","C":"Anticorpo Antitransglutaminase IgA (AAT)/histopatológico da biópsia de intestino delgado, se\nanticorpo ATT positivo, e dieta de exclusão de glúten.","D":"Anticorpo Antigliadina Deaminada (AAGD)/tipagem HLA-DQ2 e DQ8, se anticorpo AAGD\npositivo, e dieta de exclusão de glúten e contaminantes."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-234006","number":"234006","sourceNumber":"234006","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente, sexo masculino, 30 anos, acompanhado em ambulato?rio especializado em\ndoenc?a inflamato?ria intestinal por doenc?a de\nCrohn, com diagno?stico ha? 10 anos e em uso de\nimunobiolo?gico. Submetido a duas cirurgias pre?vias com enterectomias. Chegou ao\n\npronto-socorro com queixa de distensa?o e dor abdominal em co?lica, vo?mitos amarelados e\ndiminuic?a?o da eliminac?a?o de flatos. Foi passada uma sonda nasoga?strica descompressiva e\nreferido a um servic?o tercia?rio. Foi institui?do tratamento cli?nico e solicitada entero\ntomografia\nque evidenciou mu?ltiplas estenoses curtas (< 10 cm) sugestivas de fibrose cro?nica em\nsegmentos de intestino delgado, sem alterac?o?es no co?lon. Mediante melhora apenas parcial\ndos sintomas, foi solicitada avaliac?a?o ciru?rgica. Com base na situac?a?o cli?nica exposta, qual\na estrate?gia ciru?rgica ideal?","options":{"A":"Realizar plastias das estenoses (estenoplastias ou estricturoplastias).","B":"Realizar cirurgia para derivac?a?o interna (\"by-pass\" i?leo transverso).","C":"Ressecar as estenoses com margem livre de doenc?a e anastomosar.","D":"Ressecar as estenoses sem margem livre de doenc?a e anastomosar."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-234009","number":"234009","sourceNumber":"234009","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Uma paciente com 35 anos de idade procurou a demanda esponta?nea de\natendimentos em unidade ba?sica de sau?de\npois queria fazer uma colonoscopia e estava muito\npreocupada com o diagno?stico de ca?ncer colorretal em sua irma? de 37 anos. Ela era totalmente\nassintoma?tica e relatava que o pai faleceu aos 58 anos por uma obstruc?a?o intestinal provocada\npor um ca?ncer colorretal, e que um tio paterno foi operado em decorre?ncia de um tumor de ceco,\naos 55 anos. A paciente negava comorbidades e seu exame fi?sico foi completamente normal.\n\nConsiderando a situac?a?o cli?nica apresentada, qual deve ser a forma proposta para\nrastreamento de ca?ncer colorretal a essa paciente?","options":{"A":"Solicitar pesquisa de sangue oculto nas fezes e a colonoscopia, se for positiva.","B":"Orientar a realizac?a?o de colonoscopia a partir dos 40 anos, repetindo o exame a cada 5 anos.","C":"Solicitar colonoscopia e mediante resultado normal repetir o exame a cada um ou dois anos.","D":"Orientar a realizac?a?o de colonoscopia a partir dos cinquenta anos, repetindo o exame a cada\ndez anos."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-234015","number":"234015","sourceNumber":"234015","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo masculino, 42 anos, procurou a UPA com relato de que há dois dias\napresenta vômitos, inicialmente claros e, posteriormente, com conteúdo fecaloide, redução na\neliminação de fezes e flatos, associada à dor abdominal em cólica difusa no abdome. Ao exame da\nadmissão, se observava cicatriz mediana de cirurgia anterior por ferimento por arma branca há dez\nanos, distensão abdominal importante e aparentemente sem hérnias de parede abdominal. Foram\nrealizadas radiografias simples de abdome e tórax e o paciente foi regulado para um serviço de\nemergência cirúrgica, onde foi feita a opção por tratamento conservador com medidas de suporte e\ndescompressão gástrica. Atualmente, está com 48 horas de tratamento conservador com o mesmo\nquadro clínico de entrada (não houve piora ou melhora). Qual deve ser a próxima conduta?","options":{"A":"Manter conduta conservadora por mais 48 horas.","B":"Solicitar tomografia computadorizada do abdome.","C":"Solicitar ressona?ncia nuclear magne?tica do abdome.","D":"Indicar abordagem ciru?rgica (laparotomia exploradora)."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-199768","number":"199768","sourceNumber":"199768","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente foi atendido na UPA e referido a uma emergência cirúrgica. Ele tem 62\nanos, e queixa de dor abdominal em Fossa\nIlíaca Esquerda (FIE) de intensidade crescente nos\núltimos 4 dias. Teve 3 episódios de febre (T = 38,7°C) nas últimas 48 horas, está taquicárdico (FC =\n102 bpm), nega anorexia ou vômitos ou parada da eliminação de flatos. Ao exame abdominal, tem\ndor à palpação superficial e profunda localizada em FIE com ausência de descompressão brusca\nou distensão abdominal ou outros sinais de irritação peritoneal. Foi realizada tomografia de abdome\nque revelou presença de espessamento da parede do sigmoide e de sinais sugestivos de\ninflamação do mesocólon correspondente, pequena coleção com conteúdo hidroaéreo pericólica de\n2 cm e ausência de pneumoperitônio. Qual deve ser a conduta proposta?","options":{"A":"Internar o paciente com prescrição de jejum e antibióticos parenterais.","B":"Contra referir o paciente à UPA para tratamento clínico conservador.","C":"Solicitar colonoscopia para confirmar o diagnóstico de diverticulite.","D":"Indicar e encaminhar para laparotomia de urgência."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-199688","number":"199688","sourceNumber":"199688","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um jovem de 19 anos retorna à UPA após 8 horas do primeiro atendimento, com\npersistência de dor abdominal, antes\ntratada com analgésico endovenoso. No momento, queixa-se\nde dor periumbilical com predominância à direita, náuseas e anorexia. Em sua avaliação,\nobservam-se os achados de leve sensibilidade à descompressão em fossa ilíaca direita,\ntemperatura = 37,8°C, sinais de Dunphy e do obturador positivos. Laboratório com Hb = 11,7 g/dl,\nleucócitos = 11.840/mm³ e 7% de bastões. O paciente realizou ultrassonografia abdominal que foi\nprejudicada pela presença gasosa e descreve pouco líquido livre em pelve. Qual a conduta a ser\ntomada?","options":{"A":"Iniciar protocolo de tratamento clínico de apendicite aguda.","B":"Indicar tratamento cirúrgico para realização da apendicectomia.","C":"Transferir para realização de tomografia abdominal sem contraste.","D":"Analgesia e antibiótico venoso, repetir o ultrassom com 8 a 12 horas."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-199823","number":"199823","sourceNumber":"199823","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um homem de 29 anos apresenta diarreia com fezes pastosas misturadas com sangue\nvivo, 4?5 vezes ao dia, há dois anos. No\ninício do quadro, realizou colonoscopia com biópsias do\nsigmoide que mostrou infiltrado misto difuso, linfoplasmocitose basal, atrofia e irregularidade de\ncriptas, e erosões superficiais. Há 6 meses, iniciou dor lombar persistente, que o desperta do sono,\npiora ao acordar, e que melhora 2 horas após iniciar suas atividades. Apresenta hematócrito de\n32%, hemoglobina de 10,5 g/dl, proteína C-reativa elevada, antígeno HLA-B27 reagente.\n\nRessonância magnética mostra sinais de inflamação sacroilíacas intra-articular com edema\nimportante da medula óssea justa-articular.\nQual tratamento medicamentoso traz mais benefício\npara este doente?","options":{"A":"Budesonida oral.","B":"Infliximabe e azatioprina.","C":"Mesalazina e tacrolimus.","D":"Sulfassalazina e prednisona."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-172959","number":"172959","sourceNumber":"172959","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente de 60 anos, sexo feminino, apresenta hematoquezia e alteração do hábito\nintestinal. Durante investigação, o toque\nretal revelou uma lesão circunferencial de aspecto\nneoplásico a 3 cm da linha pectínea com biópsia de adenocarcinoma. A colonoscopia não\ndemonstrou outras lesões sincrônicas no restante do cólon. Os exames de estadiamento não\nrevelaram metástases sistêmicas. A ressonância do reto demonstrou que a lesão infiltra para além\nda muscular própria e com um linfonodo suspeito no mesorreto (cT3, cN1). Qual a melhor\nabordagem terapêutica inicial para o caso?","options":{"A":"Amputação abominoperineal do reto.","B":"Radioterapia associada à quimioterapia.","C":"Ressecção local por abordagem transanal.","D":"Ressecção anterior do reto com preservação esfincteriana."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-172943","number":"172943","sourceNumber":"172943","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Homem, 20 anos, iniciou quadro de dor abdominal há 6 dias associada a febre e\nvômitos nas últimas 72 horas. Foi submetido\nà apendicectomia, incisão mediana infraumbilical,\ndevido à apendicite aguda, com abscesso em fossa ilíaca direita. Foi coletado material para cultura\ne realizada drenagem da cavidade com dreno tubulolaminar. No 2º pós-operatório, após a\nrealimentação, o paciente começou a apresentar distensão abdominal, náuseas e vômitos,\ninicialmente biliosos e, depois, fecaloides. Após zerar a dieta, qual a melhor conduta a ser\ntomada?","options":{"A":"Requerer pré-operatórios e indicar laparotomia exploradora","B":"Providenciar hemograma, PCR e ultrassonografia abdominal total.","C":"Passar sonda nasogástrica e solicitar radiografia de tórax e abdome.","D":"Solicitar hemocultura e iniciar antibioticoterapia de acordo com a cultura."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-172944","number":"172944","sourceNumber":"172944","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Uma mulher de 25 anos apresenta diarreia aquosa, sem sangue e sem gordura, 5 a 6\nvezes ao dia, há 5 semanas. Refere\ndistensão abdominal e piora da diarreia após a ingestão de\npizza, queijo, leite, suco de maçã. Nega febre e relata perda ponderal de 6 kg no período da\ndoença (peso habitual = 67 kg). Faz uso de fluoxetina 20 mg/dia. Foi colecistectomizada há 4\nmeses e tem diagnóstico de fibromialgia. A avaliação ginecológica é normal. Traz os seguintes\nexames: hematócrito, hemoglobina e glicemia de jejum normais, VHS = 60 mm (VR = até 16 mm);\nferritina = 10 µg/L (VR = 10-150 µg/L); vitamina B12 = 86 pmol/L (VR = 206-735 pmol/L); vitamina D\n\n= 27 pmol/L (VR = 36-180 pmol/L). O exame físico é normal. Legenda: VR = valor de referência.\nVHS = velocidade de hemossedimentação. O seu\nobjetivo é chegar a um diagnóstico mais\nprovável. Qual dos procedimentos a seguir é o mais eficaz neste momento?","options":{"A":"Colonoscopia.","B":"Antitransglutaminase IgA.","C":"Teste de tolerância a lactose.","D":"Pesquisa de toxina para Clostridium difficile."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-172992","number":"172992","sourceNumber":"172992","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Criança de dois anos de idade chega à Emergência com relato de aspiração de corpo\nestranho, apesar de nenhum adulto ter presenciado o evento. Apresenta sintomas de obstrução,\nerosão ou perfuração em estômago ou intestino: dor abdominal, náuseas, vômitos, febre,\nhematoquezia. Radiografias revelam pneumoperitônio e distensão de alças com nível líquido. Qual\na principal hipótese diagnóstica?","options":{"A":"Ingestão cáustica.","B":"Ingestão de moedas.","C":"Ingestão de ímãs ou baterias.","D":"Ingestão de objetos pontiagudos."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-150795","number":"150795","sourceNumber":"150795","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Mulher de 68 anos submetida à colectomia parcial por pólipo gigante em cólon\ndescendente por laparoscopia. A cirurgia foi\nsem intercorrências, exceto pelo fato da grande\nadiposidade visceral, dificultando de certo modo o procedimento. Evoluiu sem queixas, mantém\npulso de 90 bpm, abdome levemente distendido, flácido e pouco doloroso à palpação. Ruídos\nhidroaéreos ausentes. Esse quadro persiste até o quarto dia pós-operatório, apesar de eletrólitos\nnormais, leucócitos de 13.000/mm3 e proteína C-reativa de 9,3 mg/dl. Diante do quadro descrito,\nqual a conduta mais adequada nesse momento?","options":{"A":"Realizar uma laparoscopia diagnóstica.","B":"Solicitar tomografia para orientar a conduta.","C":"Realizar laparotomia para possível colostomia.","D":"Solicitar ultrassonografia abdominal e iniciar antibióticos."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-150842","number":"150842","sourceNumber":"150842","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Menina de 2 anos é atendida no ambulatório de Pediatria, com história de ter\napresentado dois episódios de evacuações com\nsangue vermelho vivo profuso, nos últimos 3\nmeses. Nega história de dor abdominal e febre, mesmo durante os eventos acima. Nega ainda\nalterações outras do hábito intestinal no período intercrise. Criança eutrófica com exame físico\nnormal, exceto por palidez cutâneo-mucosa. Toque retal com fezes normais na ampola. Genitores\ntrazem consigo hemograma realizado no dia anterior à consulta que revela hemoglobina de 7 g/dL.\nConsiderando a hipótese diagnóstica mais provável, qual dos seguintes exames melhor definirá a\nfonte de sangramento?","options":{"A":"Enema opaco.","B":"Colonoscopia.","C":"Ultrassonografia de abdome.","D":"Cintilografia com 99mTc-pertecnetato."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-150850","number":"150850","sourceNumber":"150850","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Mulher de 68 anos, ativa, há cerca de 2 meses vem apresentando adinamia\nprogressiva, interferindo na realização de suas\natividades. Refere cansaço fácil, diminuindo seu\nrendimento nos exercícios aeróbicos. Em consulta de rotina com ginecologista, mencionou essas\nqueixas, sendo solicitados exames bioquímicos. Os exames foram normais, exceto as hemáceas:\n3,8 milhões/mm3 e Hb-9,8 g/dl e pesquisa de sangue nas fezes ++. A paciente nega quaisquer\noutros sintomas e ao exame clínico rigoroso, a médica só constatou palidez cutânea-mucosa (+/4).\nDiante do exposto, qual a sequência de exames a ser realizada?","options":{"A":"Videocolonoscopia e seguindo, tomografia abdominal.","B":"Esofagogastroduodenoscopia, videocolonoscopia e seguindo, tomografia abdominal.","C":"Tomografia abdominal, esofagogastroduodenoscopia e seguindo, videocolonoscopia.","D":"Repetir sangue oculto nas fezes, videocolonoscopia e seguindo, ultrassonografia abdominal."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-150868","number":"150868","sourceNumber":"150868","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Mulher, 30 anos, com história de episódios frequentes de diarreia com sangue,\nevoluindo com astenia, dor abdominal em\ncólica localizada na fossa ilíaca direita e febre diária há 2\nmeses, não tendo sido essa aferida por termômetro. Tem bom nível socioeconômico e ingere água\nfiltrada. Procurou o ambulatório de gastroenterologia para acompanhamento, tendo sido detectada\numa massa na região da fossa ilíaca direita. Realizou colonoscopia que mostrou uma colite erosiva\nsegmentar de sigmoide, não sendo possível avaliar o íleo terminal. A biópsia do cólon foi\ncompatível com colite crônica inespecífica e a pesquisa de anticorpo contra Saccharomyces\ncerevisiae foi negativa. O diagnóstico mais provável para o caso acima é colite associada a:","options":{"A":"Retocolite ulcerativa.","B":"Infecção bacteriana.","C":"Infecção por ameba.","D":"Doença de Crohn."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-365631","number":"365631","sourceNumber":"365631","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente de 7 anos de idade foi levado à unidade de pronto atendimento com\nqueixa de dor abdominal intermitente há 48\nhoras, localizada no quadrante inferior direito. Não\napresentou febre, porém estava mantendo a temperatura de cerca de 37,5°C nas últimas 24 horas.\nDurante a anamnese, a genitora informou que, há 10 dias, o enfermo havia apresentado quadro de\ngastroenterite aguda por 72 horas (doença autolimitada). Ao exame físico, o sinal de Blumberg era\nnegativo, mas observava-se expressão de dor abdominal à palpação profunda de todo o quadrante\ninferior à direita. Foram realizados exames laboratoriais e ultrassonografia de abdome, a qual\ndescartou a possibilidade de apendicite aguda e mostrava a presença de linfonodos aumentados\nde volume nessa topografia. Nesse caso clínico, a principal hipótese diagnóstica é","options":{"A":"diverticulo de Meckel.","B":"linfadenite mesentérica.","C":"pancolite.","D":"colecistite aguda."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-365630","number":"365630","sourceNumber":"365630","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente de 7 anos de idade foi levado à unidade de pronto atendimento com\nqueixa de dor abdominal intermitente há 48\nhoras, localizada no quadrante inferior direito. Não\napresentou febre, porém estava mantendo a temperatura de cerca de 37,5°C nas últimas 24 horas.\nDurante a anamnese, a genitora informou que, há 10 dias, o enfermo havia apresentado quadro de\ngastroenterite aguda por 72 horas (doença autolimitada). Ao exame físico, o sinal de Blumberg era\nnegativo, mas observava-se expressão de dor abdominal à palpação profunda de todo o quadrante\ninferior à direita. Foram realizados exames laboratoriais e ultrassonografia de abdome, a qual\ndescartou a possibilidade de apendicite aguda e mostrava a presença de linfonodos aumentados\nde volume nessa topografia. Considerando as informações do caso citado, assinale a alternativa\nque indica a melhor conduta para esse paciente.","options":{"A":"Internação + antibioticoterapia + analgesia.","B":"Internação + analgesia.","C":"Alta hospitalar com analgesia otimizada.","D":"Alta hospitalar com antibiótico + analgesia otimizada."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-365629","number":"365629","sourceNumber":"365629","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Uma paciente de 64 anos de idade procurou unidade de pronto atendimento com\nqueixa de dor abdominal de forte\nintensidade, localizada na fossa ilíaca à esquerda, há quatro dias.\nInformou ter apresentado febre (38,5 °C) na manhã desse dia. Associa-se ao quadro náusea e\nhiporexia. A paciente recebeu as medidas iniciais, realizou exames laboratoriais e tomografia\ncomputadorizada (TC) de abdome com contraste. A TC mostrou quadro de diverticulite aguda\nlocalizada no cólon sigmoide com formação de abscesso de aproximadamente 2,5 cm\nperidiverticular. Não foram evidenciadas imagens sugestivas de pneumoperitônio. Tendo em vista\nas informações apresentadas, qual é a melhor conduta para essa paciente?","options":{"A":"Internação hospitalar + antibioticoterapia endovenosa + suporte clínico.","B":"Internação hospitalar + antibioticoterapia endovenosa + drenagem percutânea do abscesso +\nsuporte clínico.","C":"Alta hospitalar com antibioticoterapia via oral.","D":"Internação hospitalar + drenagem percutânea + suporte clínico."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-365628","number":"365628","sourceNumber":"365628","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Uma paciente de 64 anos de idade procurou unidade de pronto atendimento com\nqueixa de dor abdominal de forte\nintensidade, localizada na fossa ilíaca à esquerda, há quatro dias.\nInformou ter apresentado febre (38,5 °C) na manhã desse dia. Associa-se ao quadro náusea e\nhiporexia. A paciente recebeu as medidas iniciais, realizou exames laboratoriais e tomografia\ncomputadorizada (TC) de abdome com contraste. A TC mostrou quadro de diverticulite aguda\nlocalizada no cólon sigmoide com formação de abscesso de aproximadamente 2,5 cm\nperidiverticular. Não foram evidenciadas imagens sugestivas de pneumoperitônio. Assinale a\nmelhor alternativa que indica o melhor esquema de tratamento com antibiótico endovenoso para a\npaciente do caso clínico mencionado.","options":{"A":"Ciprofloxacino.","B":"Cefepime + metronidazol.","C":"Ceftarolima + vancomicina.","D":"Ceftriaxona + metronidazol."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-365624","number":"365624","sourceNumber":"365624","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A principal artéria do apêndice cecal é a artéria apendicular, que é um ramo direto da\nartéria","options":{"A":"ileocólica.","B":"cólica média.","C":"mesentérica superior.","D":"cólica direita."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-365622","number":"365622","sourceNumber":"365622","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Uma paciente de 65 anos de idade, obesa, com dislipidemia, diabética e tabagista,\nprocurou atendimento de urgência queixando-se de\ndor abdominal que iniciou há dois dias. Refere\nparada de evacuação há três dias e iniciou quadro de vômitos há 12 horas. Nega febre, calafrios ou\nsintomas associados. Ao exame físico, os sinais vitais na admissão são PA = 140 mmHg x 72\nmmHg, FC = 115 bpm, glicemia capilar = 280 mg/dL e SatO2 = 93%. Foram constatados\nabaulamento na região inguinal esquerda, endurecimento local à palpação logo abaixo do\nligamento inguinal direito, com dor intensa local, abdome distendido, com dor difusa, porém sem\nsinais de irritação peritoneal. Foi feito o diagnóstico sindrômico de abdome agudo. De acordo com\nesse caso clínico, assinale a alternativa que apresenta o tipo de abdome agudo, a etiologia dos\nsintomas e a melhor conduta para a paciente.","options":{"A":"Obstrutivo-hérnia femoral encarcerada-inguinotomia","B":"Inflamatório-hérnia femoral encarcerada-laparotomia exploradora","C":"Obstrutivo-hérnia inguinal estrangulada-laparotomia exploratória","D":"Inflamatório-hérnia inguinal estrangulada-inguinotomia."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-365614","number":"365614","sourceNumber":"365614","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Uma paciente de 60 anos de idade procurou o pronto-socorro com dor abdominal\nintensa de início súbito, predominantemente\nno quadrante superior esquerdo. Ela relata náuseas,\nvômitos e ausência de evacuações. Ao exame físico, revela sensibilidade à palpação abdominal e\nsinais de peritonite localizada. Na admissão, os sinais vitais apresentavam PA = 90 mmHg x 60\nmmHg, FC = 120 bpm, FR = 28 irpm e temperatura = 37,8 °C. Ela realizou exames\ncomplementares que demonstraram: leucograma com leucocitose significativa, amilase sérica\ndentro da faixa de normalidade e lactato sérico elevado. Nesse caso clínico, o diagnóstico mais\nprovável é","options":{"A":"infarto mesentérico.","B":"diverticulite perfurada.","C":"apendicite aguda.","D":"pancreatite aguda grave."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-349749","number":"349749","sourceNumber":"349749","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Sobre doença de Crohn e colite ulcerativa, informe se é verdadeiro (V) ou falso (F) o\nque se afirma a seguir e assinale a\nalternativa com a sequência correta. ( ) O tabagismo parece\nconferir um efeito protetor na colite ulcerativa. ( ) A lesão mais característica da colite\nulcerativa é o\nabscesso das criptas de Lieberkühn. ( ) Uma característica histológica importante da doença de\nCrohn é o granuloma não caseoso, um agregado de histiócitos epitelioides circundados por\nneutrófilos e células gigantes. ( ) O paciente com doença de Crohn pode desenvolver fístulas entre\no intestino e qualquer outro órgão intra-abdominal, a maioria delas envolve o intestino delgado.","options":{"A":"V - V - F - V.","B":"F - V - F - V.","C":"V - V - V - V.","D":"V - V - F - F","E":"F - V - V - F."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-349752","number":"349752","sourceNumber":"349752","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Uma paciente gestante de 25 semanas apresenta dor em região de flanco direito há 1\ndia, associada a náuseas e vômitos. No hemograma, apresenta uma leucocitose de 11.500 (VR =\n10.000). Quanto a esse caso, é correto afirmar que","options":{"A":"se deve fazer uma ultrassonografia abdominal devido à suspeita de apendicite aguda e, caso\nnecessário, uma tomografia para melhor visualização do apêndice.","B":"há suspeita de apendicite aguda, devido à localização da dor (apêndice deslocado\ncefalicamente). Uma ultrassonografia de\nabdome pode visualizar o apêndice e ajudar a esclarecer o\ndiagnóstico.","C":"pode se tratar apenas de uma intercorrência da gestação, como dor do ligamento redondo. Para\nmelhor esclarecimento do caso, deve-se solicitar uma ressonância de abdome, já que a\nultrassonografia não é recomendada nessa idade gestacional.","D":"há grandes chances de ser uma apendicite aguda, já que a paciente tem dor em flanco direito\n(apêndice deslocado cefalicamente) e tem leucocitose, sinal de que há um processo inflamatório\nagudo vigente.","E":"se trata de uma provável colecistite, devido à topografia da dor associada à leucocitose, que\nfavorece processo inflamatório agudo."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-349773","number":"349773","sourceNumber":"349773","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Assinale a alternativa que apresenta alguns dos principais genes mutados que\ncontribuem para o surgimento do câncer\ncolorretal hereditário e um dos fatores que pode contribuir\npara a prevenção do câncer colorretal esporádico.","options":{"A":"BRCA 1 e BRCA 2 / Consumo diário de grandes quantidades de proteína.","B":"VHL e KRAS / Ingestão diária de ômega 3.","C":"BRAF e MEN1 / Dieta restrita em carnes vermelhas e gorduras.","D":"APC e MSH2 / Atividade física regular.","E":"BRCA 2 e p53 / Alimentação rica em frutas e vegetais."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-349767","number":"349767","sourceNumber":"349767","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Assinale a alternativa que apresenta 2 tipos de bactérias que estão entre as mais\nfrequentemente encontradas/isoladas na apendicite aguda perfurada.","options":{"A":"Acinetobacter baumannii e Klebsiella pneumoniae.","B":"Pseudomonas aeruginosa e Bacteroides coprosuis.","C":"Escherichia coli e Bacteroides fragilis.","D":"Campylobacter jejuni e Burkholderia cepacia.","E":"Acinetobacter baumannii e Escherichia coli."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-349764","number":"349764","sourceNumber":"349764","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Qual das seguintes alternativas apresenta a maior causa de obstrução do intestino\ndelgado?","options":{"A":"Hérnias.","B":"Doença de Crohn.","C":"Aderências.","D":"Neoplasias.","E":"Doenças neurológicas."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-349762","number":"349762","sourceNumber":"349762","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente de 65 anos apresenta dor, distensão abdominal e vômitos repetidos há 2\ndias. Não evacua e não elimina flatos há 3 dias. Os exames de imagem mostram distensão de\nintestino delgado e fezes em reto. Assinale a alternativa que apresenta a melhor conduta inicial\npara tratamento desse paciente.","options":{"A":"Coletar exames laboratoriais para detectar se há distúrbios hidroeletrolíticos e efetuar passagem\nde sonda nasogástrica para drenagem e\nhidratação.","B":"Indicar laparotomia exploradora para melhor diagnosticar e tratar o paciente, já que ele\napresenta o quadro há mais de 2 dias.","C":"Coletar exames laboratoriais para detectar se há sinais de infecção associada; passar sonda\nnasoenteral para alimentação pós-pilórica e iniciar antibióticos de forma profilática.","D":"Conversar com os familiares e indicar laparotomia exploradora com ileostomia associada, pois,\nnesses casos de distensão grande do delgado, não é recomendada anastomose primária.","E":"Coletar exames laboratoriais; realizar tomografia para melhor avaliação e, a seguir, encaminhar\no paciente para cirurgia, pois a maior parte\ndesses casos é solucionada por meio de cirurgia."},"answer":"E","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-349761","number":"349761","sourceNumber":"349761","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente de 72 anos foi submetido a uma laparotomia exploradora por diverticulite\ncomplicada de cólon sigmoide, tendo sido realizada uma cirurgia com ressecção do sigmoide,\nfechamento do coto retal e confecção de colostomia terminal no cólon descendente. Esse tipo de\ncirurgia denomina-se","options":{"A":"cirurgia de Whipple.","B":"cirurgia de Hartmann.","C":"cirurgia de Murphy.","D":"cirurgia de Duhamel.","E":"cirurgia de Wilson."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-349696","number":"349696","sourceNumber":"349696","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Uma criança de dez anos de idade apresenta quadro de abdome agudo, após período\nde dois dias com febre, vômitos e importante\ndistensão do abdome. Assinale a alternativa que\napresenta uma das condutas corretas nesse caso.","options":{"A":"Devido à urgência, não comunicar a família e proceder à laparotomia exploradora.","B":"Explicar à criança a importância da tomografia abdominal e do raio x de tórax.","C":"Proceder à sondagem gástrica, explicando que não há risco de perfuração intestinal.","D":"Solicitar exames laboratoriais: hemograma, eletrólitos, glicemia, amilase, lipase, gasometria\narterial, explicando previamente à família sua\nconduta.","E":"Avisar à farmácia hospitalar a respeito da indicação de reposição volêmica com solução salina\nhipertônica, explicando para família sua indicação."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-322127","number":"322127","sourceNumber":"322127","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Assinale a alternativa correta quanto às características das doenças inflamatórias\nintestinais ? doença de Crohn e retocolite\nulcerativa.","options":{"A":"A retocolite ulcerativa tem sua maior incidência em pacientes de 50 anos.","B":"A retocolite ulcerativa é uma doença que geralmente acomete mucosa, submucosa e muscular\ndo cólon.","C":"A retocolite ulcerativa pode estar associada a manifestações extraintestinais, como a colangite\nesclerosante, e geralmente é agravada pelo tabagismo.","D":"Tanto a retocolite ulcerativa como a doença de Crohn são mais comuns entre mulheres que\nusam contraceptivos orais em comparação com aquelas\nque não usam.","E":"O tabagismo atua como efeito protetor na doença de Crohn."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-337496","number":"337496","sourceNumber":"337496","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Uma paciente de 48 anos chega ao hospital com relato de vômitos frequentes há 1 dia,\nprogredindo para dor intensa em região subesternal nas últimas horas. Com base no caso clínico e\nnos conhecimentos médicos correlacionados, julgue o item a seguir. Uma das hipóteses\ndiagnósticas para essa paciente é a de ruptura esofágica associada à síndrome de Mallory-Weiss.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-337497","number":"337497","sourceNumber":"337497","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Uma paciente de 48 anos chega ao hospital com relato de vômitos frequentes há 1 dia,\nprogredindo para dor intensa em região subesternal nas últimas horas. Com base no caso clínico e\nnos conhecimentos médicos correlacionados, julgue o item a seguir. O diagnóstico de uma possível\nperfuração esofágica pode ser feito por meio de uma radiografia do tórax, que pode demonstrar um\nhidropneumotórax, ou de uma esofagografia com contraste.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-337498","number":"337498","sourceNumber":"337498","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Uma paciente de 48 anos chega ao hospital com relato de vômitos frequentes há 1 dia,\nprogredindo para dor intensa em região subesternal nas últimas horas. Com base no caso clínico e\nnos conhecimentos médicos correlacionados, julgue o item a seguir. O tratamento cirúrgico não\nestá indicado para todos os pacientes com perfuração do esôfago, pois a conduta depende de\nfatores como a estabilidade do paciente, a extensão da contaminação e a localização da\nperfuração. Caso o paciente esteja instável, necessitará de uma rápida avaliação e tratamento\nimediato.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-322133","number":"322133","sourceNumber":"322133","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Levado por um vizinho, um paciente de 68 anos, previamente lúcido, foi admitido em\num hospital com rebaixamento do nível de\nconsciência. Durante a investigação, foi sugerido\nprovável diagnóstico de sepse grave de foco abdominal devido a uma diverticulite aguda perfurada.\nO paciente permaneceu torporoso e, após a equipe tentar entrar em contato com a família, sem\nsucesso, o paciente foi encaminhado à cirurgia. O médico cirurgião indicou uma\nretossigmoidectomia à Hartmann ? com colostomia terminal. Qual é a melhor conduta diante dessa\nsituação?","options":{"A":"Proceder com a cirurgia, já que se trata de cirurgia de urgência, com risco ao paciente,\nnecessitando que seja feita uma colostomia para\nmelhor tratamento dele, independentemente da\nopinião da família.","B":"Aguardar a chegada da família para iniciar a cirurgia, já que eles devem decidir sobre a\nconfecção ou não de um estoma.","C":"Proceder com a cirurgia sem a confecção de estoma, pelo risco de não haver aceite da família\nquanto a esse procedimento, mesmo que seja a melhor estratégia para o paciente.","D":"Orientar o acompanhante sobre o quadro e solicitar que ele decida sobre a confecção ou não do\nestoma para o paciente, já que está acompanhando o paciente.","E":"Proceder com a cirurgia e realizar a lavagem e drenagem da cavidade para realizar,\nposteriormente, uma nova abordagem cirúrgica, devido à ausência da família."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-337505","number":"337505","sourceNumber":"337505","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente de 68 anos apresentou sangramento via retal recente, cessando\nespontaneamente. Em seguida, procurou o\natendimento médico ambulatorial para iniciar a\ninvestigação da causa desse episódio. Com base no caso descrito e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. Em mais de 95% dos pacientes com sangramento gastrointestinal\nbaixo, a fonte da hemorragia é o cólon, sendo o intestino delgado apenas ocasionalmente\nresponsável.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-337506","number":"337506","sourceNumber":"337506","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente de 68 anos apresentou sangramento via retal recente, cessando\nespontaneamente. Em seguida, procurou o\natendimento médico ambulatorial para iniciar a\ninvestigação da causa desse episódio. Com base no caso descrito e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. A cintilografia com tecnécio-99m é o método mais sensível e\npreciso para localizar o sangramento gastrointestinal, tanto no intestino delgado quanto no grosso.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-337507","number":"337507","sourceNumber":"337507","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente de 68 anos apresentou sangramento via retal recente, cessando\nespontaneamente. Em seguida, procurou o\natendimento médico ambulatorial para iniciar a\ninvestigação da causa desse episódio. Com base no caso descrito e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. A angiografia seletiva pode detectar hemorragia na faixa de 0,5\na\n1,0 mL/min e geralmente é usada para o diagnóstico de hemorragia contínua, apresentando\ncapacidade terapêutica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-337508","number":"337508","sourceNumber":"337508","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente de 68 anos apresentou sangramento via retal recente, cessando\nespontaneamente. Em seguida, procurou o\natendimento médico ambulatorial para iniciar a\ninvestigação da causa desse episódio. Com base no caso descrito e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. O carcinoma colorretal é uma das causas de hemorragia digestiva\nbaixa, porém é uma causa incomum de sangramento significativo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-337509","number":"337509","sourceNumber":"337509","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente de 68 anos apresentou sangramento via retal recente, cessando\nespontaneamente. Em seguida, procurou o\natendimento médico ambulatorial para iniciar a\ninvestigação da causa desse episódio. Com base no caso descrito e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. A angiodisplasia também pode ser uma causa de sangramento\ndigestivo baixo, suas lesões são consideradas degenerativas adquiridas e são usualmente\nassociadas à estenose da artéria aorta e à insuficiência renal, especialmente em pacientes idosos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-322145","number":"322145","sourceNumber":"322145","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Uma paciente de 32 anos teve, recentemente, diagnóstico de PAF (Polipose\nAdenomatosa Familiar) e possui aversão a cirurgias.\nQual é a orientação correta a ser feita nesse\ncaso?","options":{"A":"Orientar que a paciente possui uma síndrome genética de herança autossômica recessiva, que\ndificilmente será transmitida a outras gerações.","B":"Orientar que a paciente provavelmente precisará de intervenção cirúrgica, já que tem grandes\nchances de desenvolver um câncer colorretal\nem algum momento de sua vida.","C":"Orientar a paciente que o manejo da Polipose geralmente é feito por meio de acompanhamento\nclinico, com colonoscopia a cada 5 anos até os 80\nanos, deixando para comentar, quando preciso,\nsobre a possível necessidade de cirurgia.","D":"Orientar que essa patologia é caracterizada pela existência de alguns pólipos na região do reto,\nque podem ser acompanhados e ressecados por\ncolonoscopia, já que a paciente possui aversão a\ncirurgias.","E":"Orientar que essa patologia ocorre por uma mutação no gene BRCA1 e, portanto, deve ser\nindicada também adenomastectomia profilática pelo alto risco de câncer de mama."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-322185","number":"322185","sourceNumber":"322185","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Na fase mais inicial da apendicite aguda, qual é a tríade sintomática mais característica\nentre as seguintes?","options":{"A":"Dor em fossa ilíaca direita, febre alta e prostração.","B":"Dor epigástrica intensa, febre moderada e vômitos.","C":"Dor abdominal difusa, febre alta e anorexia.","D":"Dor periumbilical, febre alta e vômitos.","E":"Dor periumbilical, febre moderada e anorexia."},"answer":"E","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-305269","number":"305269","sourceNumber":"305269","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Assinale a alternativa que relaciona corretamente a síndrome hereditária ao aumento\ndo risco de câncer colorretal.","options":{"A":"A síndrome de Peutz-Jeghers é uma síndrome autossômica recessiva, caraterizada por pólipos\nhamartomatosos intestinais e hiperpigmentação da mucosa labial.","B":"A síndrome de Turcot é caracterizada, principalmente, por pólipos colorretais e adenomas\ntireoideanos.","C":"A síndrome de Lynch é caracterizada por pequeno número de pólipos colorretais e aumento do\nrisco também de câncer de endométrio e ovário.","D":"A síndrome de Gardner é caracterizada pela presença de centenas a milhares de pólipos\ncolorretais associados, principalmente, ao aumento do risco de câncer de colo uterino.","E":"A Polipose Adenomatosa Familiar (PAF) está fortemente associada à mutação do gene MLH1."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-298842","number":"298842","sourceNumber":"298842","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente de 23 anos de idade foi encaminhado à emergência com história de dor\nabdominal que migrou para a fossa ilíaca direita há dois dias. Ele queixa-se de náuseas, vômitos e\ndificuldade para se alimentar, nega febre e 1 episódio de fezes amolecidas no período. Ao exame\nfísico, apresenta-se afebril, FC = 82 bpm, FR = 18 irpm e SatO2 = 98%. Ao exame abdominal,\napresenta dor à palpação de todo abdome e dor à descompressão brusca de fossa ilíaca direita. Os\nexames laboratoriais apresenta leucocitose, sem desvio. Acerca desse caso clínico e com base nos\nconhecimentos médicos correlatos, julgue o item a seguir. A escala de Alvarado do paciente é de 8\npontos, o que traduz uma alta suspeição diagnóstica de apendicite aguda. Submeter o paciente à\napendicectomia sem a necessidade de exames de imagem seria uma condução correta do caso.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-298843","number":"298843","sourceNumber":"298843","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente de 23 anos de idade foi encaminhado à emergência com história de dor\nabdominal que migrou para a fossa ilíaca direita há dois dias. Ele queixa-se de náuseas, vômitos e\ndificuldade para se alimentar, nega febre e 1 episódio de fezes amolecidas no período. Ao exame\nfísico, apresenta-se afebril, FC = 82 bpm, FR = 18 irpm e SatO2 = 98%. Ao exame abdominal,\napresenta dor à palpação de todo abdome e dor à descompressão brusca de fossa ilíaca direita. Os\nexames laboratoriais apresenta leucocitose, sem desvio. Acerca desse caso clínico e com base nos\nconhecimentos médicos correlatos, julgue o item a seguir. O sinal que descreve a dor no quadrante\ninferior direito à palpação do quadrante inferior esquerdo é chamado sinal do obturador.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-298844","number":"298844","sourceNumber":"298844","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente de 23 anos de idade foi encaminhado à emergência com história de dor\nabdominal que migrou para a fossa ilíaca direita há dois dias. Ele queixa-se de náuseas, vômitos e\ndificuldade para se alimentar, nega febre e 1 episódio de fezes amolecidas no período. Ao exame\nfísico, apresenta-se afebril, FC = 82 bpm, FR = 18 irpm e SatO2 = 98%. Ao exame abdominal,\napresenta dor à palpação de todo abdome e dor à descompressão brusca de fossa ilíaca direita. Os\nexames laboratoriais apresenta leucocitose, sem desvio. Acerca desse caso clínico e com base nos\nconhecimentos médicos correlatos, julgue o item a seguir. Em caso de apendicite de fase inicial\n(fase I ou II), indica-se apenas antibiótico para profilaxia, não havendo obrigatoriedade da\nantibioticoterapia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-298845","number":"298845","sourceNumber":"298845","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente de 23 anos de idade foi encaminhado à emergência com história de dor\nabdominal que migrou para a fossa ilíaca direita há dois dias. Ele queixa-se de náuseas, vômitos e\ndificuldade para se alimentar, nega febre e 1 episódio de fezes amolecidas no período. Ao exame\nfísico, apresenta-se afebril, FC = 82 bpm, FR = 18 irpm e SatO2 = 98%. Ao exame abdominal,\napresenta dor à palpação de todo abdome e dor à descompressão brusca de fossa ilíaca direita. Os\nexames laboratoriais apresenta leucocitose, sem desvio. Acerca desse caso clínico e com base nos\nconhecimentos médicos correlatos, julgue o item a seguir. Em pacientes com apendicite não\nperfurada aguda, a coleta de cultura transoperatória é obrigatória, uma vez que é positiva na\nmaioria dos casos e permite guiar o uso de antibióticos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-298846","number":"298846","sourceNumber":"298846","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente de 23 anos de idade foi encaminhado à emergência com história de dor\nabdominal que migrou para a fossa ilíaca direita há dois dias. Ele queixa-se de náuseas, vômitos e\ndificuldade para se alimentar, nega febre e 1 episódio de fezes amolecidas no período. Ao exame\nfísico, apresenta-se afebril, FC = 82 bpm, FR = 18 irpm e SatO2 = 98%. Ao exame abdominal,\napresenta dor à palpação de todo abdome e dor à descompressão brusca de fossa ilíaca direita. Os\nexames laboratoriais apresenta leucocitose, sem desvio. Acerca desse caso clínico e com base nos\nconhecimentos médicos correlatos, julgue o item a seguir. Tumores carcinoides e mucinosos são os\ntumores mais comuns do apêndice e devem ser tratados com apendicectomia ou colectomia direita,\na depender do caso.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-305281","number":"305281","sourceNumber":"305281","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente com dor e distensão abdominal associadas a vômitos deu entrada no\npronto atendimento. A suspeita é de uma obstrução do intestino delgado. Qual das seguintes\nalternativas representa a causa mais comum, em geral, desse tipo de obstrução?","options":{"A":"Doença de Crohn.","B":"Neoplasia.","C":"Retocolite ulcerativa.","D":"Aderências.","E":"Hérnia interna."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-298851","number":"298851","sourceNumber":"298851","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente com 62 anos de idade apresenta alteração de hábito intestinal há um ano\ne perda ponderal de 15 kg em 2 meses. Nega\nter realizado exames de rotina. No momento,\napresenta diarreia intensa há 24 horas, com vários episódios de evacuações líquidas, associado a\ndor abdominal difusa. Ao exame físico, está desidratado, com FC = 115 bpm, FR = 19 irpm, SatO2\n\n= 97% e temperatura axilar = 37ºC. Considerando esse caso clínico e os conhecimentos médicos\ncorrelatos, julgue os itens a seguir. O quadro clínico do paciente é incompatível com obstrução\nintestinal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-298852","number":"298852","sourceNumber":"298852","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente com 62 anos de idade apresenta alteração de hábito intestinal há um ano\ne perda ponderal de 15 kg em 2 meses. Nega\nter realizado exames de rotina. No momento,\napresenta diarreia intensa há 24 horas, com vários episódios de evacuações líquidas, associado a\ndor abdominal difusa. Ao exame físico, está desidratado, com FC = 115 bpm, FR = 19 irpm, SatO2\n\n= 97% e temperatura axilar = 37ºC. Considerando esse caso clínico e os conhecimentos médicos\ncorrelatos, julgue os itens a seguir. A tomografia computadorizada é o exame para diagnóstico\ndefinitivo do câncer colorretal enquanto a colonoscopia é utilizada para estadiamento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-305284","number":"305284","sourceNumber":"305284","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente com dor abdominal é admitido no pronto atendimento e é encaminhado\npara avaliação médica. Assinale a alternativa\ncorreta quanto ao exame desse paciente.","options":{"A":"Dor no ombro esquerdo quando em decúbito dorsal após pressão colocada no abdome superior\nesquerdo é denominada sinal de Camett.","B":"Pacientes com irritação peritoneal tipicamente mudam continuamente de posição no leito\nenquanto tentam achar uma posição que reduza seu desconforto.","C":"O médico deve se posicionar à esquerda do paciente e iniciar o exame físico pela palpação do\nabdome.","D":"O quadro de íleo paralítico caracteriza-se por ruídos abdominais \"\"metálicos\"\" em tom alto, que\ntendem a ocorrer em salvas e estão associados à dor e distensão.","E":"A percussão firme da crista ilíaca ou do flanco com uma perna estendida pode ajudar a\nidentificar casos de peritonite."},"answer":"E","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-298853","number":"298853","sourceNumber":"298853","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente com 62 anos de idade apresenta alteração de hábito intestinal há um ano\ne perda ponderal de 15 kg em 2 meses. Nega\nter realizado exames de rotina. No momento,\napresenta diarreia intensa há 24 horas, com vários episódios de evacuações líquidas, associado a\ndor abdominal difusa. Ao exame físico, está desidratado, com FC = 115 bpm, FR = 19 irpm, SatO2\n\n= 97% e temperatura axilar = 37ºC. Considerando esse caso clínico e os conhecimentos médicos\ncorrelatos, julgue os itens a seguir. Caso seja confirmado o diagnóstico de câncer colorretal, pode\nser indicada a cirurgia de Hartmann, que consiste na hemicolectomia esquerda e na reconstrução\ncom anastomose primária em dois planos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-298854","number":"298854","sourceNumber":"298854","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente com 62 anos de idade apresenta alteração de hábito intestinal há um ano\ne perda ponderal de 15 kg em 2 meses. Nega\nter realizado exames de rotina. No momento,\napresenta diarreia intensa há 24 horas, com vários episódios de evacuações líquidas, associado a\ndor abdominal difusa. Ao exame físico, está desidratado, com FC = 115 bpm, FR = 19 irpm, SatO2\n\n= 97% e temperatura axilar = 37ºC. Considerando esse caso clínico e os conhecimentos médicos\ncorrelatos, julgue os itens a seguir. O paciente em tela deve passar por avaliação nutricional\n\npré-operatória, pois, neste caso, diminui o risco de complicações pós-operatórias.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-274350","number":"274350","sourceNumber":"274350","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente jovem, com hiporexia, vômitos e dor súbita de grande intensidade em região\nde fossa ilíaca direita há 24 horas.\nApresenta, ao exame físico, dor em fossa ilíaca direita à\ncompressão do abdome inferior esquerdo. Assinale a alternativa que corresponde ao nome desse\nsinal no exame físico e ao provável diagnóstico do paciente.","options":{"A":"Sinal de Blumberg ? apendicite aguda.","B":"Sinal de Grey Turner ? pancreatite aguda.","C":"Sinal de Rovsing ? apendicite aguda.","D":"Sinal de Murphy ? colecistite aguda.","E":"Sinal de McBurney ? apendicite aguda."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-261218","number":"261218","sourceNumber":"261218","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente de 45 anos de idade foi encaminhado para avaliação de disfagia há cerca\nde seis meses, com sensação de \"parada da\ndescida do alimento\" no meio do tórax. O paciente\nrelata histórico de dispneia com piora progressiva e passado de tratamento irregular para febre\nreumática. Ao exame, observaram-se ritmo cardíaco regular em dois tempos, com sopro diastólico\naudível em ápice; FC = 86 bpm; FR = 20 ipm; e SatO2 = 95%. O esofagograma atual mostra\ncompressão extrínseca do esôfago. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. A presença de endocardite infecciosa com cultura positiva para\nS.\nbovis exige a investigação de neoplasia colônica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-274353","number":"274353","sourceNumber":"274353","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Referente a vascularização do intestino grosso, é correto afirmar que","options":{"A":"o arco de Riolan comunica a irrigação da artéria mesentérica superior com a inferior.","B":"a artéria retal média é um ramo da artéria mesentérica inferior.","C":"a artéria mesentérica superior origina ramos que irrigam principalmente o cólon descendente e\nsigmoide.","D":"a artéria retal inferior, na maioria das vezes, tem origem direta da artéria mesentérica\ninferior.","E":"a artéria cólica média geralmente se origina da artéria mesentérica inferior."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-284325","number":"284325","sourceNumber":"284325","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Uma paciente de 32 anos de idade, sem antecedentes mórbidos, procurou o\npronto-socorro com queixa de dor e desconforto abdominal iniciados há quatro dias,\nacompanhados de febre e parada de eliminação de fezes. Ao exame, encontra-se em regular\nestado geral, desidratada ++/4+, com pulso de 108 bpm, com PA de 120 x 70 mmHg e com\n\nabdome pouco distendido, doloroso em andar inferior de abdome, sem sinais de irritação peritoneal.\nCom base nesse caso hipotético, julgue o\nitem a seguir. Trata-se de abdome agudo, sendo\nnecessária uma intervenção clínica ou cirúrgica para sua resolução.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-284326","number":"284326","sourceNumber":"284326","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Uma paciente de 32 anos de idade, sem antecedentes mórbidos, procurou o\npronto-socorro com queixa de dor e desconforto abdominal iniciados há quatro dias,\nacompanhados de febre e parada de eliminação de fezes. Ao exame, encontra-se em regular\nestado geral, desidratada ++/4+, com pulso de 108 bpm, com PA de 120 x 70 mmHg e com\n\nabdome pouco distendido, doloroso em andar inferior de abdome, sem sinais de irritação peritoneal.\nCom base nesse caso hipotético, julgue o\nitem a seguir. É possível descartar o diagnóstico de\napendicite aguda, devido à ausência de sinais de irritação peritoneal e de dor não localizada em\nfossa ilíaca direita.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-284329","number":"284329","sourceNumber":"284329","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Uma paciente de 32 anos de idade, sem antecedentes mórbidos, procurou o\npronto-socorro com queixa de dor e desconforto abdominal iniciados há quatro dias,\nacompanhados de febre e parada de eliminação de fezes. Ao exame, encontra-se em regular\nestado geral, desidratada ++/4+, com pulso de 108 bpm, com PA de 120 x 70 mmHg e com\n\nabdome pouco distendido, doloroso em andar inferior de abdome, sem sinais de irritação peritoneal.\nCom base nesse caso hipotético, julgue o\nitem a seguir. Caso não se obtenha um diagnóstico com\nas medidas iniciais, a tomografia de abdome deverá ser usada para a definição.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-284330","number":"284330","sourceNumber":"284330","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Uma paciente de 32 anos de idade, sem antecedentes mórbidos, procurou o\npronto-socorro com queixa de dor e desconforto abdominal iniciados há quatro dias,\nacompanhados de febre e parada de eliminação de fezes. Ao exame, encontra-se em regular\nestado geral, desidratada ++/4+, com pulso de 108 bpm, com PA de 120 x 70 mmHg e com\n\nabdome pouco distendido, doloroso em andar inferior de abdome, sem sinais de irritação peritoneal.\nCom base nesse caso hipotético, julgue o\nitem a seguir. A videolaparoscopia poderá ser\nempregada como diagnóstico e como tratamento no decorrer da investigação e do tratamento da\ndoente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-284331","number":"284331","sourceNumber":"284331","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Uma paciente de 32 anos de idade, sem antecedentes mórbidos, procurou o\npronto-socorro com queixa de dor e desconforto abdominal iniciados há quatro dias,\nacompanhados de febre e parada de eliminação de fezes. Ao exame, encontra-se em regular\nestado geral, desidratada ++/4+, com pulso de 108 bpm, com PA de 120 x 70 mmHg e com\n\nabdome pouco distendido, doloroso em andar inferior de abdome, sem sinais de irritação peritoneal.\nCom base nesse caso hipotético, julgue o\nitem a seguir. A laparotomia, caso indicada, deverá ser\nfeita através de uma incisão longitudinal para que possam ser abordadas todas as possíveis\n\ncausas e complicações.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-239254","number":"239254","sourceNumber":"239254","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente de 52 anos de idade, hipertenso e diabético, vai ao consultório do\ncirurgião com queixa de emagrecimento e\nsangramento vivo pelo ânus há seis meses. Nega\nalterações de diurese ou hábito intestinal. Ao exame físico, o abdome estava pouco distendido, sem\nmassas palpáveis. Realizou-se toque retal, observando-se esfíncter normotônico, sem lesões\npalpáveis, sem hemorroidas, com sangue vivo em dedo de luva. O paciente apresenta exames\nlaboratoriais realizados na UBS que identificam Hb = 9,3, leucócitos = 11.000, plaquetas = 340.000,\nNa = 138, K = 4,2, U = 77 e Cr = 1,94. Quanto ao caso clínico apresentado e tendo em vista os\nconhecimentos médicos correlatos, julgue o item a seguir. A colonoscopia com biópsia será de\ngrande valia na investigação diagnóstica desse paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-239255","number":"239255","sourceNumber":"239255","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente de 52 anos de idade, hipertenso e diabético, vai ao consultório do\ncirurgião com queixa de emagrecimento e\nsangramento vivo pelo ânus há seis meses. Nega\nalterações de diurese ou hábito intestinal. Ao exame físico, o abdome estava pouco distendido, sem\nmassas palpáveis. Realizou-se toque retal, observando-se esfíncter normotônico, sem lesões\npalpáveis, sem hemorroidas, com sangue vivo em dedo de luva. O paciente apresenta exames\nlaboratoriais realizados na UBS que identificam Hb = 9,3, leucócitos = 11.000, plaquetas = 340.000,\nNa = 138, K = 4,2, U = 77 e Cr = 1,94. Quanto ao caso clínico apresentado e tendo em vista os\nconhecimentos médicos correlatos, julgue o item a seguir. A ausência de lesões identificadas pelo\ntoque retal diminui a probabilidade de que a queixa do paciente se deva a uma neoplasia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-239260","number":"239260","sourceNumber":"239260","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente de 14 anos de idade, sem comorbidades, dá entrada na sala de\nemergência com rebaixamento do nível de\nconsciência. A monitorização revelou FC = 120 bpm, PA\n\n= 78 mmHg x 50 mmHg, FR = 46 irpm, SpO2 = 93%, glicemia capilar = 102 mg/dL. A mãe do\npaciente conta que o adolescente apresentava\ndor abdominal há cinco dias, inicialmente ao redor\ndo umbigo, associada a vômitos, inapetência e picos febris não aferidos. Ao exame, está sonolento,\nmas responsivo aos chamados, com abdome tenso e descompressão brusca dolorosa. Relata ter\ncomido um hambúrguer com maionese um dia antes do início dos sintomas e os atribuiu a tal fato.\nCom base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. O\npaciente está em sepse e deve receber expansão volêmica e antibióticos o mais brevemente\npossível.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-239261","number":"239261","sourceNumber":"239261","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente de 14 anos de idade, sem comorbidades, dá entrada na sala de\nemergência com rebaixamento do nível de\nconsciência. A monitorização revelou FC = 120 bpm, PA\n\n= 78 mmHg x 50 mmHg, FR = 46 irpm, SpO2 = 93%, glicemia capilar = 102 mg/dL. A mãe do\npaciente conta que o adolescente apresentava\ndor abdominal há cinco dias, inicialmente ao redor\ndo umbigo, associada a vômitos, inapetência e picos febris não aferidos. Ao exame, está sonolento,\nmas responsivo aos chamados, com abdome tenso e descompressão brusca dolorosa. Relata ter\ncomido um hambúrguer com maionese um dia antes do início dos sintomas e os atribuiu a tal fato.\nCom base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir.\n\nDiverticulite aguda é uma hipótese a se considerar, por ser muito prevalente nessa faixa etária.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-239262","number":"239262","sourceNumber":"239262","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente de 14 anos de idade, sem comorbidades, dá entrada na sala de\nemergência com rebaixamento do nível de\nconsciência. A monitorização revelou FC = 120 bpm, PA\n\n= 78 mmHg x 50 mmHg, FR = 46 irpm, SpO2 = 93%, glicemia capilar = 102 mg/dL. A mãe do\npaciente conta que o adolescente apresentava\ndor abdominal há cinco dias, inicialmente ao redor\ndo umbigo, associada a vômitos, inapetência e picos febris não aferidos. Ao exame, está sonolento,\nmas responsivo aos chamados, com abdome tenso e descompressão brusca dolorosa. Relata ter\ncomido um hambúrguer com maionese um dia antes do início dos sintomas e os atribuiu a tal fato.\nCom base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. A dor\nprovocada pela compressão e descompressão brusca do ponto de McBurney (fossa ilíaca\nesquerda) configura o sinal semiológico de Blumberg.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-211991","number":"211991","sourceNumber":"211991","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Considere uma paciente com antecedente de isquemia mesentérica, com colectomia\ntotal, em pós-operatório com boa evolução em\nuso de nutrição parenteral. Durante a explicação do\nmédico para a família a respeito da síndrome de má absorção, ele informa os familiares de que,\nalém da digestão e da absorção de nutrientes, o intestino tem outras funções. Com base nesse\ncaso clínico e nos conhecimentos médicos correlatos, é correto afirmar que o intestino tem as\nfunções de:","options":{"A":"Síntese de vitaminas; absorção de carboidratos; metabolismo da água; e controle de pH\ncorporal.","B":"Defesa do sistema cardiovascular; controle hídrico; e regulação de proteínas e aminas.","C":"Barreira e defesa imune; absorção e secreção de líquidos e eletrólitos; síntese e secreção de\nvárias proteínas; e produção de diversas aminas bioativas e peptídeos.","D":"Sistema tampão no organismo, com controle hídrico, produção de vitaminas e absorção de\naminoácidos essenciais.","E":"Defesa imune; produção de aminas e carboidratos; correção de distúrbios hidroeletrolíticos; e\ncontrole hormonal."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-177673","number":"177673","sourceNumber":"177673","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo masculino, 72 anos de idade, apresenta dor recorrente em fossa\nilíaca esquerda e flanco esquerdo. Procura a\nemergência devido a dor abdominal no quadrante\ninferior esquerdo há 2 dias, temperatura axilar de 38 °C. História prévia de constipação crônica e\nsedentarismo. Nega cirurgias prévias e demais alterações. Traz colonoscopia realizada há 4 anos\ncom diagnóstico de diverticulose em cólon esquerdo. Com base no caso clínico apresentado, e nos\nconhecimentos médicos acerca da doença diverticular, julgue o item a seguir. A doença diverticular\né a causa mais comum de sangramento intestinal baixo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-177591","number":"177591","sourceNumber":"177591","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"J.S.A., de 55 anos de idade, negra, viúva, com três filhos, hígida, com alimentação\nsaudável, assídua praticante de exercício\nfísico, vai à consulta para a realização de exames de\nrotina. Refere menopausa há 15 anos. Ao exame físico completo, não se encontra nenhuma\nalteração, exceto palidez de mucosas. Apresenta hemograma realizado em pronto atendimento por\nqueixas gripais, há 2 semanas, com anemia microcítica e índice de anisocitose aumentado. Com\nrelação à avaliação desse quadro, julgue o item a seguir. A retossigmoidoscopia é indicada para\nesse paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-179179","number":"179179","sourceNumber":"179179","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"As causas de obstrução do intestino delgado mudaram drasticamente desde 1900. Na\nvirada do século XX, hérnias eram responsáveis por mais de 50% das obstruções intestinais\nmecânicas. Com o reparo eletivo rotineiro das hérnias, esta causa passou a ser a terceira mais\ncomum de obstrução do intestino delgado nos países industrializados. As aderências secundárias à\ncirurgia prévia agora são a causa mais comum de obstrução do intestino delgado. Courtney M.\nTownsend (coord.), Sabiston. Tratado de cirurgia: a base biológica da prática cirúrgica moderna.\n\n19.ª ed. v. 2. Rio de Janeiro: Elsevier, c2015, p. 2173 (e-book). A respeito da temática abordada no\ntexto acima, assinale a alternativa correta.","options":{"A":"A maioria dos tumores malignos que causam obstrução intestinal são provenientes de lesões a\ndistância, como a mama, o pulmão e o melanoma.","B":"No início de uma obstrução, o aumento do peristaltismo ocorre somente acima do ponto da\nobstrução, como tentativa de propelir os conteúdos luminais além do ponto obstruído.","C":"A obstrução do intestino delgado pode ser secundária a um abscesso intra-abdominal, como\nresultado de um íleo local adjacente ao abscesso.","D":"A intuissucepção não é causa de obstrução intestinal no adulto.","E":"Hipocloremia, hipopotassemia e acidose metabólica constituem efeitos metabólicos secundários\nà perda de líquidos para o terceiro espaço\ncausada por uma obstrução alta."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-154343","number":"154343","sourceNumber":"154343","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"L. B., 65 anos de idade, dá entrada no pronto-socorro com quadro de abdome agudo\nobstrutivo. Relata quadro de colecistite aguda há três semanas e nega hérnia ou cirurgia prévia.\nNesse caso, considerando-se a possibilidade de íleo biliar, o diagnóstico radiológico clássico é\ndenominado tríade de Rigler, que compreende a (o):","options":{"A":"distensão do delgado, a aerobilia e calcificações pancreáticas.","B":"distensão do delgado, a aerobilia e a presença de imagem em ampola retal em miolo de pão.","C":"distensão do delgado, a aerobilia e a presença de imagem com calcificação no quadrante inferior\ndireito do abdome.","D":"padrão em grão de café, a aerobilia e a presença de imagem em U invertido.","E":"distensão intestinal, a ausência de ar no reto e a perda da redundância das flexuras do cólon."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-154319","number":"154319","sourceNumber":"154319","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente, 32 anos de idade, apresenta quadro de diarreia intensa há três dias, sem\nmelhora com hidratação intensa prescrita em consulta médica no serviço de atendimento de\nemergência, próximo à respectiva casa. Refere uso de antibiótico há 30 dias em internação\npregressa, porém relata também apresentar outros episódios de diarreia em ocasião distinta,\nquanto havia sido despedida do emprego anterior. Como antecedente de tratamento em\nandamento, atualmente faz uso de ansiolítico especifico. Mediante esse quadro, o médico levanta\nas hipóteses de doença intestinal inflamatória e de colite pseudomembranosa. Com relação a esse\ncaso clínico, assinale a alternativa correta:","options":{"A":"Se constatada a doença pseudomembranosa, a hipótese de doença intestinal inflamatória\ndeverá ser momentaneamente descartada, em razão\ndo critério de Roma IIIA.","B":"A presença de toxina A ou B confirma o diagnóstico de doença intestinal inflamatória.","C":"Os antidiarreicos estão proscritos na doença intestinal inflamatória.","D":"Pseudomembranosa são encontradas em 70% das endoscopias de casos de colite\npseudomembranosa.","E":"O uso de ansiolíticos permite a fisiopatogenia da colite pseudomembranosa."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-154349","number":"154349","sourceNumber":"154349","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente, 60 anos de idade, em investigação de anemia por perda de origem\nindeterminada, comparece para mostrar resultados\nde exames de endoscopia digestiva alta e\ncolonoscopia. Queixa-se ainda de alteração do hábito intestinal, intercalando entre diarreia e\nconstipação, de distensão abdominal e cólicas, hematoquezia e de tenesmo anal. Em razão desse\nquadro, retorna ao consultório em busca de orientação médica quanto ao risco de cancer colorretal.\nConsiderando esse caso clinico, é correto afirmar que o fator de risco reconhecido para o\ndesenvolvimento de Câncer Colorretal (CCR) esporádico é a (o):","options":{"A":"Idade avançada.","B":"Polipose Adenomatosa Familiar (PAF).","C":"Câncer Colorretal Hereditário Não Associado a Polipose (HNPCC).","D":"Polipose juvenil.","E":"Síndrome de Peutz-Jeghers."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-366231","number":"366231","sourceNumber":"366231","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Uma mulher de 42 anos de idade apresenta queixa de \"\"anemia de longa data\"\". À\nrevisão de sistemas, relata episódios\nrecorrentes de epistaxe espontâneas desde a infância, com\nmúltiplas idas ao Pronto Atendimento, especialmente em dias de clima seco. A paciente informa ter\ntratado a anemia anteriormente com diferentes reposições de sulfato ferroso, mas sem alcançar a\ncura. Destaca que considera isso normal, pois seu pai, irmãos e sobrinha enfrentam quadros\nsemelhantes. Quanto aos antecedentes, não apresenta comorbidades prévias. No exame físico,\nobserva-se palidez cutaneomucosa e a presença de várias telangiectasias cutâneas, algumas\nlocalizadas nas palmas das mãos e plantas dos pés, além de afetar a mucosa oral conforme\nimagem acima. Considerando o quadro clínico apresentado, bem como os assuntos correlatos,\nJulgue o item a seguir. A principal hipótese a ser aventada para quadro clínico exposto é Síndrome\nde Osler-Weber-Rendu.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-2/366231.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-366254","number":"366254","sourceNumber":"366254","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Considerando o contexto de abdome agudo e as imagens apresentadas e julgue o item\nseguinte. A conduta imediata para o quadro clínico da Figura I é cirúrgica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-2/366254.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-366253","number":"366253","sourceNumber":"366253","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Considerando o contexto de abdome agudo e as imagens apresentadas e julgue o item\nseguinte. A imagem da Figura II é compatível com abdome agudo obstrutivo na qual se vê \"o sinal\ndo grão de café\".","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-2/366253.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-334865","number":"334865","sourceNumber":"334865","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A apendicite aguda (AA) está entre as causas mais comuns de dor abdominal baixa,\nque levam os pacientes ao pronto-socorro, e o\ndiagnóstico mais comum feito em pacientes jovens\ninternados com abdome agudo. Com base nas diretrizes atuais acerca da AA, assinale a alternativa\ncorreta.","options":{"A":"A taxa de perfuração varia de 16% a 40%, ocorrendo com maior frequência nas faixas etárias\nmais jovens.","B":"A morbimortalidade é semelhante na AA perfurada e na não perfurada.","C":"Escores clínicos sozinhos são suficientemente sensíveis para confirmar o diagnóstico.","D":"O uso de escores clínicos não altera a indicação de exames de imagem em pacientes com\nsuspeita diagnóstica.","E":"O tratamento somente com antibióticos é uma alternativa segura para pacientes selecionados\ncom AA não complicada e com ausência de\napendicolito."},"answer":"E","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-334870","number":"334870","sourceNumber":"334870","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Uma paciente de 72 anos de idade chega ao pronto-socorro com história de distensão\nabdominal há dois dias, parada de eliminação de flatus e de fezes há um dia. Nega náuseas ou\nvômitos. Com base nesses dados clínicos e na radiografia apresentada, o diagnóstico mais\nprovável é","options":{"A":"síndrome de Ogilvie.","B":"volvo de sigmoide.","C":"volvo de ceco.","D":"obstrução intestinal baixa.","E":"diverticulite aguda."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-2/334870.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-343398","number":"343398","sourceNumber":"343398","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Acerca das hemorragias digestivas, é INCORRETO afirmar:","options":{"A":"De acordo com a intensidade de sangue perdido, a hemorragia digestiva baixa pode ser\nclassificada em sangramento líquido, acelerado e oculto.","B":"As Úlceras Pépticas são as causas mais frequentes de hemorragia digestiva alta, considerando\nlesões gástricas e duodenais.","C":"Nos pacientes com hemorragia digestiva alta persistente com causa não esclarecida ou em\ncasos com evidências de sangramento\nincontrolável, é realizada a Arteriografia do tronco celíaco e\nda artéria mesentérica superior.","D":"A doença diverticular é a principal causa de hemorragia digestiva baixa devido à sua alta\nprevalência, mesmo com apenas 3% dos pacientes complicando para o sangramento."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-343430","number":"343430","sourceNumber":"343430","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"O sinal de Rovsing pode ser usado para o diagnóstico clínico de doenças que associam\ncom dores abdominais, sendo encontrado\nfrequentemente em casos de:","options":{"A":"Colelitíase.","B":"Apendicite aguda.","C":"Colecistite aguda.","D":"Pancreatite aguda."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-343437","number":"343437","sourceNumber":"343437","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"O Abdome Agudo se caracteriza por dor lenta, insidiosa e progressiva no início,\nnormalmente com intervalo longo entre o\ncomeço dos sintomas e a ida à Emergência. Na\npropedêutica abdominal, a palpação pode revelar defesa localizada ou generalizada, por meio da\ncontração voluntária da musculatura abdominal. É um mecanismo de defesa, tendo em vista o\ncomprometimento peritoneal. As causas mais comuns são apendicite, colecistite, pancreatite e\ndiverticulite agudas. É chamado de:","options":{"A":"Abdome Agudo Hemorrágico.","B":"Abdome Agudo Inflamatório.","C":"Abdome Agudo Perfurativo.","D":"Abdome Agudo Obstrutivo."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-343438","number":"343438","sourceNumber":"343438","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A Hemorragia Digestiva Alta (HDA) é definida como sangramento do trato\ngastrointestinal que ocorre acima do ligamento de\nTreitz ? que se localiza entre o Duodeno e o\nJejuno. Acerca da HDA, é CORRETO afirmar:","options":{"A":"A causa mais comum da hemorragia digestiva alta é a úlcera intestinal, a qual ocorre entre 50%\na 60% dos casos.","B":"As hemorragias classificadas como crônicas são, em sua maioria, sintomáticas e a perda crônica\nde sangue oculto se manifesta com anemia\nbreve.","C":"O manejo do sangramento agudo inclui estabilização hemodinâmica e realização de endoscopia\napós as primeiras 24 horas.","D":"Inquirir sobre história de dispepsia ou uso de anti-inflamatórios não esteroides e ácido\nacetilsalicílico ajuda na investigação\netiológica, especialmente na hipótese de úlcera péptica ativa."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-343440","number":"343440","sourceNumber":"343440","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Acerca dos sintomas da Síndrome de Lynch, é INCORRETO afirmar:","options":{"A":"Presença de tumores sincrônicos no cólon.","B":"Alteração do funcionamento do trato intestinal (diarreia e prisão de ventre alternados).","C":"Sangue nas fezes.","D":"Dor ou desconforto abdominal."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-343443","number":"343443","sourceNumber":"343443","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"ICSB, sexo feminino, 91 anos, com história de DM, HAS e doença coronariana, foi\ninternada há 2 semanas após complicações de uma cirurgia de prótese total de quadril direito.\nRelata cólica de baixa intensidade e que há 5 dias parou de evacuar. Ao exame físico apresenta\nabdome distendido, hipertimpanismo à percussão difusa, dor à palpação profunda difusa e\nperistalse reduzida. A radiografia abdominal mostrou distensão de todo o cólon até o reto.\n\nConsiderando os dados apresentados, a hipótese diagnóstica mais provável para o caso é:","options":{"A":"Neoplasia de cólon.","B":"Volvo de sigmoide.","C":"Pseudo-obstrução intestinal.","D":"Infarto entero-mesentérico."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-343460","number":"343460","sourceNumber":"343460","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A giardíase e a amebíase são doenças causadas por protozoários e que possuem a\nseguinte característica em comum:","options":{"A":"São doenças que podem ser prevenidas através de vacinação.","B":"São doenças transmitidas pela via fecal-oral.","C":"São doenças de notificação compulsória nacional.","D":"São doenças incuráveis e de difícil prevenção."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-266413","number":"266413","sourceNumber":"266413","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Uma paciente do sexo feminino, com 51 anos de idade, procurou uma Unidade Básica\nde Saúde (UBS) com queixas de hematoquezia,\nastenia e dor abdominal leve. Negou alterações de\nritmo intestinal, alteração na característica das fezes e perda de peso. Relatou que tinha sido\nsubmetida a cirurgia para tratamento de hemorroidas havia 5 anos. No exame físico da paciente, o\nmédico constatou, de relevante, somente mucosas moderadamente hipocoradas. Considerando\nesse caso clínico hipotético, julgue o item a seguir. No momento, bastam o tratamento da anemia e\no acompanhamento dos sintomas.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-268887","number":"268887","sourceNumber":"268887","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Uma paciente de 21 anos de idade queixa-se de dor em quadrante inferior direito há 24\nhoras, associada a febrícula, a náuseas sem vômitos e a inapetência. Nega comorbidades e está\nem uso de anticoncepcional combinado via oral corretamente. Ao exame físico, apresenta-se em\nbom estado geral, normocorada, anictérica e com mucosas úmidas e hidratadas. Quanto aos sinais\nvitais, constatam-se PA = 120 mmHg x 80 mmHg, FC = 98 bpm, FC = 17 irpm e SatO2 = 99%. No\nabdome, refere-se a dor abdominal em baixo ventre, que se encontra distendido e com sinal de\nBlumberg +. Ao exame ginecológico, a paciente nega dor à mobilização do colo uterino. Com\nrelação a esse caso clínico e à apendicite aguda no sexo feminino, assinale a alternativa correta.","options":{"A":"A dor inicia-se de maneira somática e converte-se em visceral.","B":"A hipótese diagnóstica de apendicite aguda é descartada se existir dor na mobilização do colo\ndo útero.","C":"O sinal de Blumberg + significa presença de dor no quadrante inferior direito à palpação do\nquadrante inferior esquerdo.","D":"A apendicectomia videolaparoscópica é a melhor opção em pacientes hemodinamicamente\nestáveis.","E":"A escolha da tomografia como primeiro exame de imagem é aceitável em pacientes femininas\nnão grávidas."},"answer":"E","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-266415","number":"266415","sourceNumber":"266415","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Uma paciente do sexo feminino, com 51 anos de idade, procurou uma unidade básica\nde saúde (UBS) com queixas de hematoquezia,\nastenia e dor abdominal leve. Negou alterações de\nritmo intestinal, alteração na característica das fezes e perda de peso. Relatou que tinha sido\nsubmetida a cirurgia para tratamento de hemorroidas havia 5 anos. No exame físico da paciente, o\nmédico constatou, de relevante, somente mucosas moderadamente hipocoradas. Considerando\nesse caso clínico hipotético, julgue o item a seguir. A paciente não deve preocupar-se com a\nhematoquezia, pois tem antecedentes de doença hemorroidária, e essa deve ser a causa do\nsangramento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-268889","number":"268889","sourceNumber":"268889","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente tabagista e etilista procura atendimento em pronto-socorro em razão de\ndor abdominal súbita e com piora nas últimas 24\nhoras. Apresenta abdome em tábua,\ndesaparecimento da macicez hepática e os seguintes sinais vitais: PA = 100 mmHg x 60 mHg, FC =\n120 bpm, FR = 19 irpm e SatO2 = 99%. Considerando esse caso clínico, a respeito de abdome\nagudo, assinale a alternativa correta.","options":{"A":"O exame de escolha, indicado nesse momento, é a tomografia computadorizada com contraste.","B":"Devem ser receitados inibidores da bomba de prótons e deve-se observar a evolução do\ntratamento.","C":"O tratamento de Helicobacter pylori, no caso de úlceras gástricas, não é necessário.","D":"As úlceras gástricas do tipo I e IV não estão associadas a níveis elevados de ácidos e não\nnecessitam de vagotomia.","E":"Os raios X de abdome agudo não ajudariam no diagnóstico de pneumoperitônio."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-291479","number":"291479","sourceNumber":"291479","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um homem com 58 anos de idade foi atendido em ambulatório de hospital secundário.\nRelatava sangramento e muco nas fezes, referia também alteração do hábito intestinal, com o\naumento do número de evacuações há 5 meses. O exame físico geral não apresentava\nparticularidades e o toque retal evidenciou tumoração na parede posterior do reto,\naproximadamente 7 cm acima da borda anal. Com base nos dados apresentados, a alternativa\ncorreta sobre o exame necessário para definir a conduta a ser seguida é:","options":{"A":"Ultrassonografia endorretal.","B":"Ressonância nuclear magnética endorretal.","C":"Enema baritado com duplo contraste.","D":"Colonoscopia com biópsia."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-291480","number":"291480","sourceNumber":"291480","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um homem com 42 anos de idade foi operado em hospital secundário com quadro de\napendicite aguda com necrose e abscesso em apêndice retrocecal (Fase III), sendo realizada\napendicectomia e drenagem do abscesso por incisão mediana infraumbilical. No terceiro dia de\npós-operatório começou a apresentar picos diários de aumento da temperatura axilar (38,5 ºC)\napesar dos antibióticos prescritos (ceftriaxona e metronidazol). A incisão encontrava-se com bom\naspecto, foram encontrados 15 200 leucócitos/mm³ (referência: 3 500 a 10 500) e alteração na\ncontagem diferencial dos leucócitos, com 5% de bastonetes no sangue periférico (referência: 0 a\n2%). A proteína C reativa era de 15 mg/L (referência: menor que 3). Relatava dor ao tentar fletir a\ncoxa direita e o examinador exercia discreta pressão contrária ao movimento, a ausculta pulmonar\nera normal e os ruídos hidroaéreos estavam presentes. Com base nos dados apresentados, qual é\na alternativa correta sobre a conduta?","options":{"A":"Solicitar radiografia do abdome em pé e deitado.","B":"Substituir os antibióticos prescritos.","C":"Manter os antibióticos prescritos e avaliar novos exames após 24 horas.","D":"Solicitar tomografia computadorizada do abdome."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-273338","number":"273338","sourceNumber":"273338","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Em relação à síndrome de Ogilvie, assinale a alternativa CORRETA:","options":{"A":"A constipação é o achado mais comumente observado.","B":"A radiografia simples do abdome é o método mais útil ao diagnóstico.","C":"A colonoscopia descompressiva deve ser realizada antes de qualquer outra alternativa\nterapêutica.","D":"O tratamento conservador raramente resolve a síndrome de Ogilvie."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-291488","number":"291488","sourceNumber":"291488","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente 65 anos, masculino, apresentando alteração do hábito intestinal. Como\nhistória familiar, apresenta pai falecido de\ncâncer de próstata aos 70 anos, mãe falecida de câncer\nde colo de útero aos 80 anos, avô paterno e primo por parte de mãe falecidos por câncer de cólon\ncom 60 e 50 anos respectivamente. Realizou colonoscopia que evidenciou lesão estenosante na\njunção reto-sigmoidiana, 3 pólipos em reto e 5 pólipos em sigmoide. O resultado histopatológico da\nlesão estenosante foi adenocarcinoma de cólon moderadamente diferenciado. Quanto aos pólipos,\ntodos eram de natureza adenomatosa, sendo 5 tubulares e 2 túbulos-vilosos (ambos no reto). Em\nqual das situações abaixo, levando em conta a história familiar e o diagnóstico, esse paciente\nmelhor se enquadra?","options":{"A":"Câncer colorretal hereditário não polipoide (Síndrome de Lynch).","B":"Síndrome de Polipose Recessiva.","C":"Polipose adenomatosa familiar.","D":"Câncer colorretal esporádico."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-263370","number":"263370","sourceNumber":"263370","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente com 70 anos de idade, com sequela de acidente vascular encefálico,\nacamado, apresenta quadro de distensão abdominal,\ndor tipo cólica intensa e parada de eliminação\nde gases e fezes há cerca de 24 horas. Nega vômitos ou febre. A acompanhante informou que o\npaciente já apresentava constipação crônica, sendo muitas vezes necessário clister glicerinado\npara retirada de fecaloma. Entretanto, desta vez, relata que realizou o clister, sem saída de fezes\ne\ncom piora do quadro abdominal. O exame do abdome estava prejudicado pela pouca interação do\npaciente, mas ele manifestava dor à palpação difusa. O toque retal mostrou ampola retal vazia.\n\nRealizaram-se as radiografias de rotina para abdome agudo, o que evidenciou, além de imagem de\nfecaloma, intensa dilatação de todo o cólon (mais dilatado no ceco ? 11 cm de diâmetro), ausência\nde gás no reto e ausência de dilatação de intestino delgado. A conduta médica indicada para esse\npaciente é:","options":{"A":"Laparotomia exploradora.","B":"Colonoscopia descompressiva.","C":"Esvaziamento colônico manual.","D":"Laxantes via sonda nasogástrica."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-266440","number":"266440","sourceNumber":"266440","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um jovem de 20 anos de idade procurou atendimento médico com queixa de diarreia\n(10 episódios por dia), persistente havia seis\nmeses, com perda de muco e sangue. O paciente\nafirmou que havia perdido 10Kg de peso nesse período. Por meio de uma colonoscopia, chegou-se\nao diagnóstico de retocolite ulcerativa idiopática (RCUI). Com relação ao caso clínico hipotético\nprecedente e a aspectos relacionados à patologia mencionada, julgue o item subsequente. No caso\nem apreço, o diagnóstico confirmatório depende, necessariamente, de um teste PPD (tuberculose)\ncom resultado positivo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-266441","number":"266441","sourceNumber":"266441","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um jovem de 20 anos de idade procurou atendimento médico com queixa de diarreia\n(10 episódios por dia), persistente havia seis\nmeses, com perda de muco e sangue. O paciente\nafirmou que havia perdido 10 kg de peso nesse período. Por meio de uma colonoscopia, chegou-se\nao diagnóstico de Retocolite Ulcerativa Idiopática (RCUI). Com relação ao caso clínico hipotético\nprecedente e a aspectos relacionados à patologia mencionada, julgue o item subsequente. Na fase\nde moderada atividade da RCUI, o tratamento é feito com o uso de mesalazina oral e corticoides.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-291500","number":"291500","sourceNumber":"291500","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo masculino, 65 anos, foi atendido no serviço de urgência de um\nhospital com queixa de dor em flanco e fossa\nilíaca esquerdos, com início há cerca de 48 horas e\npiora nas últimas 12 horas. Neste período, apresentou episódio febril de 38 ºC, aferido em seu\ndomicílio. Relatou apresentar divertículos do cólon há cerca de 12 anos, e que foi submetido a uma\ngastrectomia parcial há 1 ano por adenocarcinoma gástrico em antro, estágio IB. Apresentou\nrelatório médico relativo a esse procedimento, no qual constava endoscopia digestiva alta com\nbiópsia confirmando o diagnóstico histológico, tomografia computadorizada de abdome e tórax, que\nrevelava doença diverticular em sigmoide, e colonoscopia confirmando doença diverticular em\nsigmoide. Ao exame físico, o paciente estava em bom estado geral, frequência cardíaca de 95 bpm,\npressão arterial de 130x80 mmHg e temperatura axilar de 38,1 ºC. O abdome estava flácido, mas\ndoloroso à palpação profunda de flanco e fossa ilíaca esquerdos e hipogástrio. Hemograma revelou\nleucocitose de 16 000/mm³ (referência: 9 000-11 000/mm³) com 10% de bastões (referência: 0 ?\n\n5%). O paciente relatou estar preocupado pela possibilidade de ser um \"retorno do câncer\". O\nexame complementar e explicação para confirmação do diagnóstico nesse momento é","options":{"A":"Colonoscopia, que poderá diagnosticar diverticulite aguda ou neoplasia maligna do cólon.","B":"Tomografia por emissão de pósitrons acoplada à tomografia computadorizada (PET-TC), que\npoderá identificar recidiva da neoplasia maligna.","C":"Tomografia computadorizada de abdome com contraste venoso, que poderá identificar e\nmensurar complicações da diverticulite aguda do cólon.","D":"Radiografia de abdome em decúbito dorsal e posição ortostática e radiografia de tórax em\nincidência ântero-posterior, que poderão diagnosticar diverticulite aguda do cólon."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-274642","number":"274642","sourceNumber":"274642","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"O diagnóstico de apendicite aguda é eminentemente clínico. Considerando a correlação\nda fisiopatologia e das fases da apendicite aguda,\na alternativa que se refere à fase flegmonosa é:","options":{"A":"Edema, obstrução linfática, ulceração da mucosa.","B":"Obstrução venosa e arterial, perfuração.","C":"Estase, proliferação bacteriana.","D":"Secreção persistente, aumento de presença luminal."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-291514","number":"291514","sourceNumber":"291514","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente de 60 anos de idade, masculino, procura hospital pronto-socorro com história\nde parada de eliminação de flatos e fezes há\ncerca de 1 semana. Nega vômitos. Ao exame físico,\npaciente em regular estado geral, desidratado, dispneico, taquicárdico. Abdome globoso,\nhipertimpânico, doloroso à palpação difusa, com sinais de irritação peritoneal. Toque retal com\nampola retal vazia, sem fezes, sem muco, sem sangue em \"dedo-de-luva\". Solicitadas radiografias\nde tórax e abdome, demonstrando distensão volumosa de cólon e ceco (maior que 12 cm), com\nníveis hidroaéreos, sem distensão de intestino delgado. Baseado nessas informações, qual a\nconduta?","options":{"A":"Sonda nasogástrica.","B":"Observação.","C":"Laparotomia exploradora.","D":"Clister glicerinado."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-274663","number":"274663","sourceNumber":"274663","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Considerando o tema doença inflamatória intestinal no período fértil e a possibilidade\nde complicações na gestação e no parto, é CORRETO\nafirmar:","options":{"A":"A Doença de Crohn pode causar cicatriz perineal, o que torna o parto difícil.","B":"O tratamento geralmente é feito com corticosteroides que podem interferir na absorção de folato.","C":"Devido ao uso dos corticosteroides, deve-se atrasar a amamentação após 1 hora da tomada da\nmedicação.","D":"A intervenção cirúrgica é indicada para complicações médias ou graves decorrentes da doença."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-291542","number":"291542","sourceNumber":"291542","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Uma mulher de 22 anos de idade foi encaminhada ao serviço de oftalmologia devido a\nepisódio de olho vermelho, em que o médico oftalmologista diagnosticou uma uveíte anterior\naguda. Questionando a paciente, o médico identificou história de aftas orais recorrentes e\ndolorosas há pelo menos 1 ano para as quais não foi realizada nenhuma investigação, fazendo uso\napenas de corticoides tópicos, com alívio fugaz. Relata, ainda, que apresenta dor abdominal e\ndiarreia, mais ou menos, no mesmo período. Refere que as evacuações são frequentes, cerca de 5\na 6 vezes por dia, em pequeno volume e com sangue e muco visíveis em algumas ocasiões.\n\nVisando ao esclarecimento diagnóstico, o procedimento a ser adotado e o achado esperado,\ndevem ser:","options":{"A":"Teste de Patergia; pústula visualizável no local de punção após 7 dias.","B":"Parasitológico das fezes pelo MIF (mercúrio, iodo e formol); cistos e trofozoítos.","C":"Pesquisa de autoanticorpos (FAN); positivo com padrão nuclear pontilhado fino denso.","D":"Colonoscopia com biopsia; histopatológico com granuloma não caseoso."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-263435","number":"263435","sourceNumber":"263435","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Uma paciente com 35 anos de idade procura atendimento hospitalar devido a episódio\núnico de sangramento anal vermelho vivo, indolor, em pequena quantidade durante evacuação.\n\nNega qualquer história prévia de traumatismo local. Em seu exame físico, constatou-se que a\npaciente está em bom estado geral,\nnormocorada, PA = 120 x 60 mmHg, FC = 76 bpm e com pulso\nradial amplo, regular. Abdome plano e depressível, indolor à palpação, sem massas palpáveis e\nsem sinais de irritação peritoneal. A anuscopia não demonstrou doença hemorroidária externa e/ou\nfissuras anais e/ou fístulas perianais. O toque retal não identificou lesões palpáveis, até cerca\nde ±\n6 cm da margem anal, porém, evidenciou discreta quantidade de sangue em dedo-de-luva. O\nmédico assistente solicitou hemograma, cujo resultado foi normal. A paciente foi liberada com\nencaminhamento ambulatorial e com solicitação de exame de colonoscopia. O resultado da\ncolonoscopia mostrou alguns pólipos colônicos, não pediculados, e lesão de borda elevada com\nulceração central, séssil, ± 1,5 cm de diâmetro, em cólon sigmoide, distando ± 35 cm da margem\nanal - a qual foi biopsiada. Nesse caso clínico, a hipótese diagnóstica mais provável para essa\npaciente é de","options":{"A":"polipose adenomatosa familiar.","B":"síndrome de Peutz-Jeghers.","C":"neoplasia colônica.","D":"doença de Crohn."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-227363","number":"227363","sourceNumber":"227363","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Mulher de trinta e cinco anos de idade compareceu ao pronto-socorro com quadro de\ndor abdominal difusa havia 12 horas, associada\na distensão abdominal, vários episódios de vômito\ne parada de eliminação de flatus. A paciente informou que havia evacuado no dia anterior à\nconsulta, que seus ciclos menstruais estavam regulares e que sua última menstruação havia\nocorrido 20 dias antes da consulta. G3P2C2A1. Ao exame físico, apresentou-se desidratada, com\nsinais vitais normais; além disso, o exame revelou ruídos hidroaéreos diminuídos e abdome pouco\ndistendido, doloroso à palpação difusamente, sem sinais de irritação peritoneal. A respeito desse\ncaso clínico e dos múltiplos aspectos a ele relacionados, julgue o item a seguir. Em casos de\nobstrução intestinal, o acesso videolaparoscópico é contraindicado devido ao risco de lesão\niatrogênica.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-227364","number":"227364","sourceNumber":"227364","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Mulher de trinta e cinco anos de idade compareceu ao pronto-socorro com quadro de\ndor abdominal difusa havia 12 horas, associada\na distensão abdominal, vários episódios de vômito\ne parada de eliminação de flatus. A paciente informou que havia evacuado no dia anterior à\nconsulta, que seus ciclos menstruais estavam regulares e que sua última menstruação havia\nocorrido 20 dias antes da consulta. G3P2C2A1. Ao exame físico, apresentou-se desidratada, com\nsinais vitais normais; além disso, o exame revelou ruídos hidroaéreos diminuídos e abdome pouco\ndistendido, doloroso à palpação difusamente, sem sinais de irritação peritoneal. A respeito desse\ncaso clínico e dos múltiplos aspectos a ele relacionados, julgue o item a seguir. O primeiro exame\nde imagem a ser solicitado é a radiografia de abdome.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-227365","number":"227365","sourceNumber":"227365","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Mulher de trinta e cinco anos de idade compareceu ao pronto-socorro com quadro de\ndor abdominal difusa havia 12 horas, associada\na distensão abdominal, vários episódios de vômito\ne parada de eliminação de flatus. A paciente informou que havia evacuado no dia anterior à\nconsulta, que seus ciclos menstruais estavam regulares e que sua última menstruação havia\nocorrido 20 dias antes da consulta. G3P2C2A1. Ao exame físico, apresentou-se desidratada, com\nsinais vitais normais; além disso, o exame revelou ruídos hidroaéreos diminuídos e abdome pouco\ndistendido, doloroso à palpação difusamente, sem sinais de irritação peritoneal. A respeito desse\ncaso clínico e dos múltiplos aspectos a ele relacionados, julgue o item a seguir. Com base na\nhistória clínica da paciente e nesse exame físico, a principal hipótese diagnóstica é de obstrução\nintestinal por bridas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-227366","number":"227366","sourceNumber":"227366","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Mulher de trinta e cinco anos de idade compareceu ao pronto-socorro com quadro de\ndor abdominal difusa havia 12 horas, associada\na distensão abdominal, vários episódios de vômito\ne parada de eliminação de flatus. A paciente informou que havia evacuado no dia anterior à\nconsulta, que seus ciclos menstruais estavam regulares e que sua última menstruação havia\nocorrido 20 dias antes da consulta. G3P2C2A1. Ao exame físico, apresentou-se desidratada, com\nsinais vitais normais; além disso, o exame revelou ruídos hidroaéreos diminuídos e abdome pouco\ndistendido, doloroso à palpação difusamente, sem sinais de irritação peritoneal. A respeito desse\ncaso clínico e dos múltiplos aspectos a ele relacionados, julgue o item a seguir. Em razão dos\nvários episódios de vômito, a paciente pode apresentar acidose metabólica.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-244463","number":"244463","sourceNumber":"244463","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Acerca de pólipos colônicos, assinale a alternativa correta.","options":{"A":"Pólipos hamartomatosos são característicos da síndrome de Gardner e podem ser causa de\nsangramento.","B":"Polipose adenomatose familiar é uma doença autossômica dominante, e um possível tratamento\nindicado é colectomia e vigilância endoscópica do restante do trato gastrointestinal.","C":"Na polipose juvenil familiar, tipicamente, os pólipos adenomatoides estão presentes no cólon e\nno reto e podem ocasionar sangramento.","D":"Os pólipos inflamatórios são raros e têm alto potencial de malignidade.","E":"Os cânceres de cólon esquerdo são habitualmente lesões exofíticas que estão associadas com\nperda de sangue oculto, e resultam em anemia por deficit de ferro."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-244466","number":"244466","sourceNumber":"244466","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"No que concerne à síndrome inflamatória intestinal, assinale a alternativa correta.","options":{"A":"A doença de Crohn pode manifestar-se como quadro de abdome agudo, apresentando\nperfurações intestinais, e simular quadros de\napendicite ou de diverticulite.","B":"A doença de Crohn está associada a sintomas extraintestinais, entre eles, eritema nodoso e\ncolangite esclerosante primária.","C":"A doença de Crohn e a retocolite ulcerativa são sempre bem distinguíveis, e ambas devem ser\nacompanhadas pelo risco de neoplasias intestinais.","D":"A retocolite ulcerativa caracteriza-se por inflamação transmural do cólon e do sigmoide.","E":"Diferentemente da doença de Crohn, a perítonite não está entre as principais causas de\nobstrução intestinal."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-227398","number":"227398","sourceNumber":"227398","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente de quarenta e cinco anos de idade queixa-se de diarreia persistente há 6\nmeses, com 5 a 10 episódios de fezes\nlíquidas por dia, sem produtos patológicos, associada à dor\nabdominal e flatulência, mas sem febre e sem perda de peso. Tendo esse caso clínico como\nreferência, julgue os itens subsecutivos. No tratamento da diarreia crônica, a dieta prescrita deve\nser pobre em resíduos, com restrição de leite e derivados e com incremento de hidratação oral.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-227401","number":"227401","sourceNumber":"227401","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente de quarenta e cinco anos de idade queixa-se de diarreia persistente há 6\nmeses, com 5 a 10 episódios de fezes\nlíquidas por dia, sem produtos patológicos, associada a dor\nabdominal e flatulência, mas sem febre e sem perda de peso. Tendo esse caso clínico como\nreferência, julgue os itens subsecutivos. Nos casos de diarreia crônica, a pesquisa de doença\ncelíaca mediante pesquisa de antigliadina com resultado positivo confirma o diagnóstico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-227402","number":"227402","sourceNumber":"227402","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente de quarenta e cinco anos de idade queixa-se de diarreia persistente há 6\nmeses, com 5 a 10 episódios de fezes\nlíquidas por dia, sem produtos patológicos, associada a dor\nabdominal e flatulência, mas sem febre e sem perda de peso. Tendo esse caso clínico como\nreferência, julgue os itens subsecutivos. Nos casos de diarreia crônica com suspeita de doença\ninflamatória intestinal, o anticorpo anti Saccharomyces cerevisiae (ASCA) tem alta sensibilidade\npara retocolite ulcerativa.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-230580","number":"230580","sourceNumber":"230580","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente de 65 anos, internado em unidade de terapia intensiva para tratamento de\npneumonia viral e síndrome respiratória aguda grave. Em ventilação mecânica invasiva e dieta por\nsonda nasoenteral. Apresentou distensão abdominal, quando foram realizadas algumas lavagens\ncom solução glicerinada sem retorno satisfatório. Trata-se, POSSIVELMENTE, de:","options":{"A":"síndrome de Olgivie.","B":"colite pseudomembranosa.","C":"colite isquêmica.","D":"isquemia mesentérica."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-230587","number":"230587","sourceNumber":"230587","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Sobre o câncer colorretal e seu estadiamento, assinale a CORRETA:","options":{"A":"apenas Rx de tórax é necessário, uma vez que o tratamento é sempre cirúrgico.","B":"é necessário apenas ultrassonografia de abdome total.","C":"realização de CT de crânio para todos se faz necessário.","D":"realização de tomografia de abdome, pelve e tórax são necessárias para evidenciar a presença\nde lesões secundárias."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-230593","number":"230593","sourceNumber":"230593","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"O intestino delgado é responsável por uma importante parte da digestão alimentar. É\ncomposto por duodeno, jejuno e íleo. No intra-operatório, algumas características são mais\nevidentes em cada segmento. O achado anatômico MAIS característico de jejuno é:","options":{"A":"presenças de apêndices epiplóicos.","B":"mesentério com várias arcadas vasculares e vasos retos curtos.","C":"mesentério com poucas arcadas vasculares com vasos retos longos.","D":"mesentério com única arcada vascular e vasos retos longos."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-212036","number":"212036","sourceNumber":"212036","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo feminino, 27 anos de idade, foi atendida no pronto-socorro da clínica\nmédica com cólica na região epigástrica, iniciada havia 4 horas, com a presença de hiporexia e\nnáuseas. Posteriormente, a dor tornou-se contínua e mais forte, migrou para a fossa ilíaca direita,\nquando a paciente apresentou dois episódios de vômitos. Considerando o caso clínico descrito\nanteriormente e os múltiplos aspectos a ele relacionados, julgue o item a seguir. O diagnóstico\ninicial de prenhez ectópica não deve ser descartado.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-212041","number":"212041","sourceNumber":"212041","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo feminino, 27 anos de idade, foi atendida no pronto-socorro da clínica\nmédica com cólica na região epigástrica, iniciada havia 4 horas, com a presença de hiporexia e\nnáuseas. Posteriormente, a dor tornou-se contínua e mais forte, migrou para a fossa ilíaca direita,\nquando a paciente apresentou dois episódios de vômitos. Considerando o caso clínico descrito\nanteriormente e os múltiplos aspectos a ele relacionados, julgue o item a seguir. Um exame de\nleucograma com resultado de leucocitose acentuada e desvio à esquerda é patognomônico de\napendicite aguda.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-203034","number":"203034","sourceNumber":"203034","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente de 21 anos de idade apresenta histórico de dor em fossa ilíaca direita e\nhipogástrio há 24 horas, febre não aferida e hiporexia. Ao exame físico, apresenta dor à palpação\nprofunda em fossa ilíaca direita e hipogástrio, sem dor à descompressão. Sem queixas\nginecológicas, possui vida sexual ativa. Com relação a esse caso clínico, assinale a alternativa\ncorreta.","options":{"A":"Não é necessária avaliação da ginecologia.","B":"A paciente pode ser mantida em observação domiciliar, com retorno caso haja piora dos\nsintomas.","C":"Não são necessários exames de imagem para esse caso.","D":"O tratamento dessa paciente será cirúrgico.","E":"A videolaparoscopia pode ser usada tanto para diagnóstico quanto para eventual tratamento."},"answer":"E","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-212045","number":"212045","sourceNumber":"212045","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo feminino, 27 anos de idade, foi atendida no pronto-socorro da clínica\nmédica com cólica na região epigástrica, iniciada havia 4 horas, com a presença de hiporexia e\nnáuseas. Posteriormente, a dor tornou-se contínua e mais forte, migrou para a fossa ilíaca direita,\nquando a paciente apresentou dois episódios de vômitos. Considerando o caso clínico descrito\nanteriormente e os múltiplos aspectos a ele relacionados, julgue o item a seguir. A paciente deve\nser submetida a um exame ginecológico para o esclarecimento do diagnóstico.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-212052","number":"212052","sourceNumber":"212052","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo feminino, 27 anos de idade, foi atendida no pronto-socorro da clínica\nmédica com cólica na região epigástrica, iniciada havia 4 horas, com a presença de hiporexia e\nnáuseas. Posteriormente, a dor tornou-se contínua e mais forte, migrou para a fossa ilíaca direita,\nquando a paciente apresentou dois episódios de vômitos. Considerando o caso clínico descrito\nanteriormente e os múltiplos aspectos a ele relacionados, julgue o item a seguir. A presença de\napendicolito e o borramento da gordura periapendicular são sinais tomográficos significativos para\numa indicação cirúrgica em casos como o da paciente em questão.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-206143","number":"206143","sourceNumber":"206143","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A colonoscopia é utilizada para o diagnóstico da doença de câncer de cólon por permitir\no exame de todo o intestino grosso e biópsia de\npólipos que possam estar localizados fora da área\nde ressecção da lesão. Sendo INCORRETO o seguinte:","options":{"A":"Nos casos confirmados da doença de câncer de cólon, a infiltração e extensão do tumor de reto\ndevem ser avaliadas quando possível pela ultrassonografia endorretal, que tem acurácia\ncomparável à tomografia computadorizada pélvica, ou pela\n\nressonância magnética.","B":"Pelo risco de tumores sincrônicos do cólon, a colonoscopia deve ser realizada sempre que\npossível antes do tratamento destes\n\ndoentes.","C":"O exame de tomografia por emissão de pósitrons (PET-CT) é inútil na investigação de doença\nmetastática à distância em doentes\n\nde alto risco com tumor potencialmente ressecável.","D":"A indicação de PET-CT deve ser feita para detecção de metástase de câncer colorretal,\nexclusivamente hepática e potencialmente ressecável."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-212023","number":"212023","sourceNumber":"212023","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo feminino, 27 anos de idade, foi atendida no pronto-socorro da clínica\nmédica com cólica na região epigástrica, iniciada havia 4 horas, com a presença de hiporexia e\nnáuseas. Posteriormente, a dor tornou-se contínua e mais forte, migrou para a fossa ilíaca direita,\nquando a paciente apresentou dois episódios de vômitos. Considerando o caso clínico descrito\nanteriormente e os múltiplos aspectos a ele relacionados, julgue o item a seguir. A ausência dos\nsinais do psoas, do obturador e de Rovsing no exame físico afasta o diagnóstico de prenhez\nectópica rota.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-212029","number":"212029","sourceNumber":"212029","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo feminino, 27 anos de idade, foi atendida no pronto-socorro da clínica\nmédica com cólica na região epigástrica, iniciada havia 4 horas, com a presença de hiporexia e\nnáuseas. Posteriormente, a dor tornou-se contínua e mais forte, migrou para a fossa ilíaca direita,\nquando a paciente apresentou dois episódios de vômitos. Considerando o caso clínico descrito\nanteriormente e os múltiplos aspectos a ele relacionados, julgue o item a seguir. Neoplasia de\napêndice cecal é o diagnóstico mais provável para essa paciente.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-203096","number":"203096","sourceNumber":"203096","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Considere um paciente de 60 anos de idade com histórico de hematoquezia e perda de\npeso há seis meses, sem procurar\natendimento médico. Há dois dias, apresenta parada de\neliminação de flatos e fezes e distensão abdominal. Tem antecedentes de tabagismo, hipertensão\narterial sistêmica controlada e apendicectomia há 10 anos. Realizou rotina radiológica para abdome\nagudo com laudo de distensão de todo o cólon, sem gás no reto e sem distensão de alças de\ndelgado. Quanto a esse caso clínico, é correto afirmar que a hipótese diagnóstica mais provável e o\nrespectivo tratamento de escolha são:","options":{"A":"Obstrução intestinal por bridas e laparotomia exploradora.","B":"Obstrução intestinal por bridas e tratamento clínico.","C":"Obstrução intestinal por câncer colorretal e laparotomia exploradora.","D":"Obstrução intestinal por câncer colorretal e tratamento clínico.","E":"Diverticulite aguda e antibioticoterapia."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-206172","number":"206172","sourceNumber":"206172","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A colonoscopia é o método preferencial de diagnóstico por permitir o exame de todo o\nintestino grosso e a remoção ou biópsia de pólipos que possam estar localizados fora da área de\nressecção da lesão principal, oferecendo vantagem sobre a colonografia por tomografia. O\ndiagnóstico de câncer de cólon é estabelecido pelo exame histopatológico de espécime tumoral\nobtido através da colonoscopia ou do exame de peça cirúrgica. Estando INADEQUADO o seguinte:","options":{"A":"O diagnóstico da doença por exame radiológico contrastado do cólon (enema opaco) deve ser\npreferido mesmo com acesso à colonoscopia ou quando existir contraindicação médica para esse\nexame.","B":"A investigação de possíveis metástases intra-abdominais e pélvicas deve ser feita\nalternativamente por meio de exame\nultrassonográfico, tomografia computadorizada ou ressonância\nmagnética, a critério médico.","C":"A investigação de metástases pulmonares deve ser efetuada por meio de radiografia simples de\ntórax ou tomografia computadorizada, também a critério médico.","D":"Na suspeita de câncer retal pela história clínica é mandatória a realização de um exame\nproctológico (toqueretal)."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-206166","number":"206166","sourceNumber":"206166","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A quimioterapia paliativa está indicada para doentes com câncer colorretal recidivado\ninoperável ou com doença no estágio IV ao diagnóstico, a critério médico. Está INADEQUADO o\nque se afirma na alternativa:","options":{"A":"Em doentes com metástases hepáticas ressecáveis (número limitado de lesões, localização intra\nhepática, ausência de envolvimento vascular, ausência ou mínima doença metastática\n\nextra-hepática, reserva funcional hepática adequada), a ressecção completa da doença hepática\npode resultar em taxas de sobrevida em 5 anos\nde 25% a 40%.","B":"Empregam-se esquemas terapêuticos baseados em fluoropirimidina, associada ou não a\noxaliplatina, irinotecano, mitomicina C, bevacizumabe, cetuximabe ou panitumumabe,\nobservando-se independente das características clínicas do doente.","C":"Doentes com metástases hepáticas irressecáveis e ausência ou mínima doença metastática\nextra-hepática podem se beneficiar de quimioterapia paliativa sistêmica baseada em\nfluoropirimidina, contendo ou não oxaliplatina ou irinotecano, com objetivo de reduzir o volume\ntumoral e permitir a ressecção cirúrgica.","D":"O uso de esquema terapêutico contendo cetuximabe ou bevacizumabe promoveu taxa de\nressecabilidade maior que controles históricos (ou seja, não randomizados e comparativos), porém\no significado clínico em termos de benefícios clínicos duradouros ou ganho de sobrevida são\ndesconhecidos."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-206131","number":"206131","sourceNumber":"206131","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Sobre os tumores carcinoides gastrointestinais assinale a alternativa INCORRETA:","options":{"A":"Surgem das células enterocromafins encontradas nas criptas de Lieberkühn.","B":"A síndrome carcinoide maligna ocorre em mais de 50% dos pacientes portadores de tumor\ncarcinoide.","C":"Após o apêndice, o intestino delgado é a região mais afetada.","D":"São compostas por células multipotenciais com capacidade de secretar numerosos agentes\nhumorais."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-177232","number":"177232","sourceNumber":"177232","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo feminino, com 15 anos de idade, acompanhada dos pais, procurou a\nemergência em função de dor abdominal com início há 12 horas. Relata que náuseas e dor\nperiumbilical se iniciaram antes da dor em fossa ilíaca direita. O abdome está doloroso, apresenta\nruído hidroaéreo diminuído e sinal de Blumberg e sinal de Rovsing positivos. Nega história de\ndiarreia, cirurgias prévias e menarca. Considerando o mencionado caso clínico e os conhecimentos\nmédicos referentes a ele, assinale a alternativa correta.","options":{"A":"Choque séptico, peritonite e abscessos intraperitoneais não fazem parte das complicações da\napendicite.","B":"Doença de Crohn, pielonefrite, pancreatite, pneumonia, cetoacidose diabética e linfadenite\nmesentérica não fazem parte dos diagnósticos diferenciais de apendicite.","C":"Os pacientes idosos têm maior benefício com a apendicectomia videolaparoscópica do que os\npacientes jovens. A intervenção cirúrgica precoce melhora os resultados.","D":"A apendicite é uma doença cirúrgica não obstétrica incomum durante a gravidez.","E":"Na ecografia de abdome, são evidências de apendicite aguda: fluxo sanguíneo inalterado no\napêndice, parede do apêndice fina e gordura apendicular adjacente hipoecogênica."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-183862","number":"183862","sourceNumber":"183862","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"No que se refere às enfermidades gastrointestinais, julgue o item que se segue.\nComplicações intestinais comuns da doença de\nCrohn, tais como obstrução, abscessos, fístulas e\nlesões anorretais, são consideradas parte do quadro clínico característico da enfermidade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-177261","number":"177261","sourceNumber":"177261","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo masculino, de 60 anos de idade, previamente hígido, procura um\npronto-socorro com dor abdominal, náuseas,\nvômitos e inapetência. Nega febre. Refere distensão\nabdominal e ausência de evacuações há 3 dias. Relata que vem apresentando períodos de diarreia\ne de constipação intercalados. Na emergência, realizou tomografia de abdômen, que evidenciou\ntumor em cólon sigmoide e distensão de cólon e das alças intestinais, além de lesão nodular em\nlobo direito do fígado. Em relação ao caso clínico apresentado e considerando-se os\nconhecimentos médicos relativos aos tumores colorretais, é correto afirmar que","options":{"A":"a ocorrência de sangramento é mais comum no cólon esquerdo.","B":"tais tumores são mais comuns no lado esquerdo, principalmente no sigmoide e no reto.","C":"a disseminação da doença ocorre principalmente pela via linfática.","D":"a obstrução intestinal é mais comum nos tumores de cólon direito.","E":"a maioria dos tumores se origina dos pólipos vilosos."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-177238","number":"177238","sourceNumber":"177238","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo masculino, de 25 anos de idade, procura um pronto-socorro com\nqueixa de dor abdominal periumbilical há 2\ndias, associada a náuseas e inapetência. Refere ter tido\num episódio de febre. Nega disúria. Relata que realizou eliminações fisiológicas presentes e\nnormais. Ao exame físico, apresenta dor abdominal em fossa ilíaca direita e defesa abdominal.\n\nConsiderando o caso clínico apresentado e os conhecimentos médicos relacionados a ele, é\ncorreto afirmar que a principal hipótese diagnóstica para o referido paciente é","options":{"A":"apendicite aguda.","B":"gastrite.","C":"pancreatite aguda.","D":"colecistite aguda.","E":"hérnia umbilical encarcerada."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-177243","number":"177243","sourceNumber":"177243","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A diverticulite é a complicação mais frequente nos pacientes que possuem\ndiverticulose. Geralmente, é uma enfermidade que está\nacompanhada de febre, leucocitose e,\nalgumas vezes, de massa palpável no abdome. A respeito da diverticulite, assinale a alternativa\nCORRETA.","options":{"A":"A ultrassonografia não é recomendada para realizar drenagem guiada de grandes abscessos\nintra-abdominais.","B":"A topografia mais comum da citada patologia é o cólon ascendente, associado ao espessamento\nmuscular da parede intestinal,\ncaracterístico da doença.","C":"As fístulas vaginal, vesical e de intestino delgado não são complicações comuns da\ndiverticulite.","D":"Pela classificação de Hinchey estágio I, os pacientes não apresentam boa resposta ao uso de\nantibióticos e necessitam de intervenção cirúrgica imediata.","E":"A doença diverticular é a causa mais comum de sangramento intestinal baixo."},"answer":"E","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-175138","number":"175138","sourceNumber":"175138","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A variação de posição mais comum do Apêndice Vermiforme é:","options":{"A":"Descendente na pelve menor.","B":"Retrocecal.","C":"Pré-ileal.","D":"Retroileal."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-154473","number":"154473","sourceNumber":"154473","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente de 50 anos de idade com queixa de astenia, apresentando como única\nalteração laboratorial anemia hipocrômica\nmicrocítica (Hb 8,0 g/dl). Durante propedêutica\ninvestigativa, foi submetido à tomografia computadorizada de abdome, sendo evidenciada massa\nem topografia de cólon ascendente, medindo 5 cm em seu maior diâmetro, sem metástases\ndetectadas. Qual deve ser o exame realizado neste momento para orientação da conduta e sua\nrespectiva justificativa?","options":{"A":"PET-Scan (Tomografia com Emissão de Pósitrons), avaliar se a lesão encontrada é ressecável\nou irressecável.","B":"Ecografia com Doppler das artérias mesentéricas, avaliando irrigação tumoral e grau de invasão.","C":"Colonoscopia virtual, avaliando as dimensões precisas do tumor, incluindo profundidade de\ninvasão da parede intestinal.","D":"Ressonância magnética de abdome, avaliar em detalhes a irrigação tumoral, bem como real\nextensão do tumor.","E":"Colonoscopia, para confirmar o achado da tomografia e descartar presença de lesões\nsincrônicas."},"answer":"E","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-168469","number":"168469","sourceNumber":"168469","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Uma mulher com 72 anos de idade foi atendida na sala de emergência de um hospital\npor apresentar quadro de dor abdominal com 24\nhoras de evolução. Ao exame físico, a paciente\nestava em bom estado geral, afebril com frequência cardíaca = 88 bpm e pressão arterial = 150 x\n95 mmHg, e seu abdome apresentava-se doloroso à palpação em fossa ilíaca esquerda, sem sinais\nde irritação peritoneal. Foi realizada uma tomografia de abdome, que evidenciou quadro de\ndiverticulite aguda com imagem sugestiva de abscesso de 1,5 cm de diâmetro junto à parede do\nsigmoide e ausência de pneumoperitônio. Diante desse quadro, a conduta adequada é:","options":{"A":"Exploração cirúrgica e antibioticoterapia.","B":"Jejum, hidratação e antibioticoterapia.","C":"Drenagem percutânea do abscesso.","D":"Jejum, colonoscopia e biópsia."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-159571","number":"159571","sourceNumber":"159571","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo feminino, de cinquenta e três anos de idade, com quadro de anemia\ncrônica por deficiência de ferro, compareceu a serviço médico, apresentando pesquisa de sangue\noculto nas fezes com resultado positivo e os resultados de três videoendoscopias digestivas altas e\nduas colonoscopias, que indicaram boas condições de preparo, sem evidências de fonte de\nsangramento visível. Os exames foram realizados em um centro de referência para hemorragia\ndigestiva. A paciente negou ocorrência anterior de sangramento digestivo visível. Considerando\nesse caso clínico, julgue o seguinte item. Em relação à abordagem clínica dessa paciente, o exame\nmais adequado para se estabeler o diagnóstico inicial seria a enteroscopia.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-168477","number":"168477","sourceNumber":"168477","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Uma mulher com 50 anos de idade procura atendimento médico na Unidade Básica de\nSaúde, com queixa de astenia progressiva há 3 meses. Ela nega quaisquer outros sintomas e\nafirma não fazer uso de qualquer medicação. Está na menopausa há 2 anos, sem apresentar\nsangramento transvaginal. Não há relato de comorbidades ou de histórico familiar de diabetes,\nhipertensão ou neoplasias. No exame físico da paciente, o único achado é palidez, com mucosas\nhipocoradas (++/4+). O hemograma solicitado mostrou: hemoglobina = 9 g/dL (valor de referência:\n12 a 14 g/dL), hematócrito = 27% (valor de referência: 36 a 42%), VCM = 65 fL (valor de referência:\n80 a 100 fL), HCM = 20 pg (valor de referência: 27 a 32 pg), RDW = 19% (valor de referência: 11,5\na 15%); leucograma e plaquetas normais. Com base nos achados, a conduta inicial para\ncomplementação da investigação diagnóstica dessa paciente é solicitar","options":{"A":"mielograma.","B":"dosagem de ácido fólico.","C":"dosagem de vitamina B12.","D":"pesquisa de sangue oculto nas fezes."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-168510","number":"168510","sourceNumber":"168510","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um homem com 28 anos de idade deu entrada em um pronto-socorro hospitalar,\nqueixando-se de dor no quadrante inferior\ndireito do abdome, com irradiação para região lombar\nipsilateral, tempo de evolução de 2 dias, acompanhada de febre (38,2 °C), disúria e diarreia. Ao\nexame físico, apresentava sinais de Blumberg e de Rovsing positivos. Foram solicitados alguns\nexames complementares, cujos resultados são: leucócitos = 15.000/mm³ (valor de referência: 4.000\na 11.000/mm³), com 22% de bastonetes (valor de referência: 0 a 4%); radiografia de abdome sem\nalterações significativas; ultrassonografia abdominal cujo laudo indicou apêndice cecal de 8 mm de\ndiâmetro e observação para considerar a hipótese de apendicite, de acordo com critérios clínicos. O\ncirurgião de plantão, suspeitando de apendicite aguda, indicou cirurgia com incisão em quadrante\ninferior direito. Durante o inventário cirúrgico, identificou-se um apêndice cecal de aspecto\nnormal,\nsem alterações macroscópicas e sem exsudações periapendiculares. Considerando essa situação,\na conduta cirúrgica adequada no período intraoperatório é","options":{"A":"realizar a inspeção da cavidade, esperar o paciente acordar e discutir com a família a realização\nda apendicectomia.","B":"não realizar apendicectomia, pois não há evidência de inflamação e os riscos não justificam a\nremoção do apêndice.","C":"realizar apendicectomia, caso a inspeção da cavidade seja negativa para outras patologias\nintra-abdominais.","D":"realizar apendicectomia, mesmo que seja encontrada outra patologia intra-abdominal."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-158078","number":"158078","sourceNumber":"158078","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente de 86 anos de idade está realizando investigação de quadro de anemia\nmicrocítica e hipocrômica com hemoglobina de\n6 mg/dl, ferro sérico diminuído e ferritina diminuída.\nRDW aumentado e reticulócitos normais. Já realizou múltiplos tratamentos com ferro IV, com\nmelhora parcial do quadro, mas com queda da hemoglobina sempre que suspende a medicação.\nEla refere alguma perda de peso nos últimos anos, mas o atribui ao fato de estar comendo menos\npor não se adaptar à nova prótese dentária. A endoscopia digestiva alta indicou apenas gastrite\natrófica. A colonoscopia foi normal. A pesquisa de sangue oculto nas fezes foi positiva. Exceto pela\npalidez cutânea, o exame físico está normal. A única medicação que a paciente utiliza é o AAS, há\nmuitos anos, sem saber exatamente o motivo. No que tange ao caso clínico exposto, assinale a\nalternativa CORRETA:","options":{"A":"O tratamento deve ser realizado com vitamina B12 intramuscular por toda a vida.","B":"O uso de cápsula endoscópica deve ser considerado.","C":"A presença de sangue oculto positivo em usuários de AAS é comum, não exigindo maiores\ninvestigações nesse caso.","D":"O diagnóstico final dessa paciente é de síndrome de fragilidade do idoso.","E":"A presença de corpúsculos de Pappenheimer é esperada na hematoscopia."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-158090","number":"158090","sourceNumber":"158090","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente de 22 anos de idade é levado pelo pai ao pronto-socorro com queixas de\ndores fortes na região lombar, com evolução\nde alguns anos e piora progressiva. O paciente refere\nque, há muito tempo, as respectivas fezes, frequentemente, diarreicas, eventualmente têm sangue.\nEle nunca investigou o quadro, pois mora no interior e não possui bom acesso aos serviços de\nsaúde. O pai está muito preocupado com o quadro do filho, que está \"emagrecendo e encolhendo\nde tão doente\". Considerando esse caso clínico e os conhecimentos médicos a ele relacionados,\nassinale a alternativa CORRETA.","options":{"A":"Trata-se de uma artrite reativa por infecção por Shigella.","B":"O comprometimento axial tem relação com a atividade da doença intestinal.","C":"Provavelmente haverá fator reumatoide positivo.","D":"O envolvimento articular no contexto das doenças inflamatórias intestinais é mais comum na\ndoença de Crohn.","E":"O padrão de envolvimento axial evolui de forma ascendente e contínua, mas não costuma ser\nsimétrico."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-159556","number":"159556","sourceNumber":"159556","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente de cinquenta e quatro anos de idade procurou atendimento médico\nqueixando-se de mudanças no hábito intestinal\ne de presença de sangue nas fezes. O paciente\napresentou história de polipose adenomatosa familiar, diagnosticada havia seis anos. O paciente\nrelatou ainda que, com relação ao referido diagnóstico, não havia feito acompanhamento médico. O\nexame físico não mostrou alterações, e o toque retal deixou mancha de sangue na luva do médico.\nPor fim, o profissional da saúde solicitou dosagem do nível sérico de antígeno carcinoembriônico\n(CEA). Com referência a esse caso clínico, julgue o item que se segue. Nesse caso, se forem\nconstatados níveis normais de CEA, deve-se descartar o diagnóstico de câncer colorretal, dada a\nelevada sensibilidade diagnóstica desse marcador.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-159557","number":"159557","sourceNumber":"159557","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente de cinquenta e quatro anos de idade procurou atendimento médico\nqueixando-se de mudanças no hábito intestinal\ne de presença de sangue nas fezes. O paciente\napresentou história de polipose adenomatosa familiar, diagnosticada havia seis anos. O paciente\nrelatou ainda que, com relação ao referido diagnóstico, não havia feito acompanhamento médico. O\nexame físico não mostrou alterações, e o toque retal deixou mancha de sangue na luva do médico.\nPor fim, o profissional da saúde solicitou dosagem do nível sérico de antígeno carcinoembriônico\n(CEA). Com referência a esse caso clínico, julgue o item que se segue. No caso em consideração,\na principal hipótese diagnóstica é câncer colorretal.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-157980","number":"157980","sourceNumber":"157980","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Determinada paciente de 65 anos de idade, sexo feminino, procura a emergência com\nquadro de febre iniciada há dois dias,\nassociada a dor de caráter progressivo em fossa ilíaca\nesquerda, sem fatores de alívio ou piora. Já havia passado por episódios semelhantes, mas, dessa\nvez, procura atendimento em razão da persistência da dor. A tomografia de tórax mostra\nespessamento do cólon descendente, associado a infiltração dos planos adiposos adjacentes\n(Hinchey I). Nesse caso clínico, a principal hipótese diagnóstica e a conduta são, respectivamente,\ndiverticulite:","options":{"A":"Complicada e laparotomia exploradora de urgência.","B":"Complicada e videolaparoscopia de urgência.","C":"Complicada e drenagem percutânea guiada por tomografia computadorizada.","D":"Não complicada e tratamento conservador com antibioticoterapia.","E":"Não complicada e laparotomia exploradora."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-168435","number":"168435","sourceNumber":"168435","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um homem com 18 anos de idade é encaminhado à consulta no ambulatório de\nmedicina interna por estar com diarreia há\nmais de 4 semanas acompanhada de dor abdominal,\nfebre intermitente, perda de peso e hematoquezia ocasional. Ao exame físico, o paciente mostra-se\nemagrecido e sente dor à palpação profunda de fossa ilíaca direita, onde uma massa abdominal é\npalpada. Apresenta resultado de hemograma realizado na unidade básica de saúde com\nhematócrito = 36% (valor de referência: 39 a 49%), sem leucocitose, sendo a velocidade de\nhemossedimentação = 30 mm na primeira hora. O resultado do exame parasitológico de fezes é\nnegativo. Nessa situação, qual deve ser o próximo exame a ser solicitado ao paciente?","options":{"A":"Colonoscopia.","B":"Enema baritado.","C":"Ultrassonografia de abdome.","D":"Pesquisa de anticorpos antiendomísio e antigliadina."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-359173","number":"359173","sourceNumber":"359173","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A evolução da dor abdominal, sua duração, caráter e intensidade ajudam a definir um\nperfil para cada situação clínica específica. Assinale a alternativa CORRETA que contém o perfil de\ndor e a sua possível causa.","options":{"A":"Dor lancinante, aguda, de início súbito e de forte intensidade sugere quadros inflamatórios ou\nobstrutivos.","B":"Dor que se inicia de forma mais leve e, ao longo do tempo, evolui com piora súbita sugere\nobstrução de intestino delgado.","C":"Dor periumbilical e/ou difusa, constante, pode sugerir isquemia intestinal.","D":"Dor em cólica e de forte intensidade sugere perfuração de víscera oca e aneurisma roto de\naorta."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-368199","number":"368199","sourceNumber":"368199","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um senhor de 72 anos de idade, portador de doença arterial coronariana, em uso de\nantiagregação plaquetária, foi admitido no hospital com relato de ter apresentado vários episódios\nde perda de sangue vivo retal nos últimos dois dias. Ao exame, apresentava-se alerta, descorado,\ncom enchimento capilar normal; FC = 105 bpm; PA = 120x70 mmHg e T = 36,5 °C. Nesse caso, o\nexame que deve ser solicitado para identificação do sítio de sangramento desse paciente é","options":{"A":"cintilografia com hemácias marcadas.","B":"enema com bário.","C":"arteriografia.","D":"colonoscopia."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-352198","number":"352198","sourceNumber":"352198","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"S.A.P., 57 anos, feminina, hipertensa controlada (com uso de atenolol, losartana e\nhidroclorotiazida), procura atendimento médico com queixa de dor abdominal em fossa ilíaca\nesquerda de início há 4 dias, associada, náuseas, febre e calafrios. Frequência cardíaca: 98bpm,\npressão arterial: 110/70mmHg, abdome doloroso difusamente à palpação, com defesa em\nquadrante inferior esquerdo, sem sinais de irritação peritoneal. Hemoglobina: 13,1mg/dL,\nLeucócitos: 17.200/mm³, Proteína C Reativa (PCR): 54mg/dL. Tomografia de abdome mostra\ndivertículos em sigmoide, associado a espessamento parietal deste segmento e densificação dos\nplanos adiposos pericólicos, abscesso pericólico de 3 cm, com focos gasosos adjacentes. Assinale\na alternativa com a conduta terapêutica imediata mais apropriada para o caso:","options":{"A":"Drenagem percutânea.","B":"Colonoscopia.","C":"Antibioticoterapia endovenosa.","D":"Cirurgia de Hartmann."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-351587","number":"351587","sourceNumber":"351587","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Sobre a maturação da ileostomia e da colostomia, assinale V para as afirmativas\nverdadeiras e F para as falsas. ( ) Uma\nileostomia rasa ou plana pode resultar em dermatite logo\nnos primeiros dias de pós-operatório. ( ) A colostomia deve ser maturada na pele com mucosa\nprocidente à maneira de Brooke. ( ) Na laparotomia, tracionar a borda da parede de volta à linha\nmédia com auxílio de pinças de Kocher evita a distorção dos planos durante a dissecção. ( ) A\nmaturação da ileostomia pode ser confeccionada junto à pele com discreta elevação. Assinale a\nalternativa que apresenta a sequência CORRETA.","options":{"A":"V-F-V-F.","B":"F-V-F-V.","C":"V-F-F-V.","D":"F-V-V-F."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-351589","number":"351589","sourceNumber":"351589","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Dentre as alternativas a seguir, assinale a patologia MAIS encontrada com a\nenteroscopia intraoperatória nos sangramentos do intestino delgado.","options":{"A":"Tumor.","B":"Pólipo.","C":"Ectasia vascular.","D":"Divertículo de jejuno."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-351594","number":"351594","sourceNumber":"351594","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Sobre os exames subsidiários de abdome agudo, considere as afirmativas a seguir: I- A\ntomografia computadorizada de abdome e pelve detecta com alta sensibilidade e especificidade\nlesões inflamatórias, coleções, obstruções intestinais, isquemia e necrose esplâncnica, obstruções\narteriais, tromboses venosas, hemorragias intracavitárias e neoplasias. II- Cada padrão de abdome\nagudo tem seus exames preferenciais, sendo que alguns exames são sempre solicitados,\nindependentemente do padrão clínico. São eles: hemograma, amilase/lipase e coagulograma. III-\nSão exames indispensáveis para o diagnóstico de abdome agudo: hemograma, eletrocardiograma,\nradiografia, tomografia computadorizada e ultrassonografia. IV- A ultrassonografia, por sua\nfacilidade de acesso, por não necessitar contraste e nem expor o paciente à radiação, é geralmente\no exame de primeira escolha. Estão CORRETAS apenas as afirmativas:","options":{"A":"I e II.","B":"II e III.","C":"I e IV.","D":"I, III e IV."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-354093","number":"354093","sourceNumber":"354093","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente de 70 anos, sexo masculino, admitido no PS com quadro de Hemorragia\nDigestiva Baixa (HDB). Relata dois episódios de\nsangramento, hoje não associados a evacuação.\nNo momento paciente estável, lúcido e orientado, acianótico e normocorado. Pressão arterial\n120x70mmHg e frequência cardíaca de 80 bpm. Frente ao caso em questão, assinale a alternativa\ncorreta:","options":{"A":"A maioria cessa espontaneamente e a colonoscopia é o exame padrão-ouro.","B":"A avaliação inicial compreende o exame proctológico e a pesquisa de sangue oculto fecal.","C":"A abordagem cirúrgica está indicada no 3° episódio de hemorragia digestiva baixa quando a\ndoença diverticular for a causa.","D":"A forma hipertônica da doença diverticular é causa de sangramento maciço e está indicada a\narteriografia.","E":"A neoplasia colorretal é a principal causa de HDB nessa faixa etária e está indicada\ncolonoscopia, tomografia e solicitação de marcadores tumorais."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-354094","number":"354094","sourceNumber":"354094","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente masculino de 65 anos, sem antecedentes prévios, chega ao pronto-socorro\ncom dor abdominal progressiva em quadrante\ninferior esquerdo 48 horas, associado a parada de\neliminação de gases e fezes com distensão abdominal. Submetido a tomografia de abdome total\nque diagnosticou diverticulite aguda Hinchey 2. Como pode ser descrita a tomografia desse\npaciente e qual o tratamento indicado?","options":{"A":"Borramento da gordura pericolônica, sem coleção, e antibioticoterapia.","B":"Abscesso pericolônico confinado, laparotomia e antibioticoterapia.","C":"Abscesso paracolônico, laparotomia e antibioticoterapia","D":"Abscesso pericolônico com extensão para pelve, drenagem percutânea e antibioticoterapia.","E":"Ruptura de abscesso pélvico, laparotomia e antibioticoterapia."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-354095","number":"354095","sourceNumber":"354095","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente de 30 anos é internado com distensão abdominal e parada de eliminação\nde gases e fezes há 7 dias. Nega episódios\nanteriores parecidos, febre e emagrecimento, mas\nrefere náuseas e vômitos. De histórico patológico pregresso, refere laparotomia devido acidente\nautomobilístico. Quais achados radiográficos e a conduta imediata frente ao caso em questão?","options":{"A":"Níveis hidroaéreos; laparotomia exploradora.","B":"Sinal do \"\"grão de café\"\"; passagem de sonda retal.","C":"Sinal \"\"de empilhamento de moedas\"\"; passagem de sonda nasogástrica e hidratação\nintravenosa.","D":"Sinal de \"\"maçã mordida\"\"; lavagem intestinal com clister.","E":"Sinal de Rigler; desobstrução Intestinal por videocolonoscopia"},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-373561","number":"373561","sourceNumber":"373561","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Mulher, 33 anos, branca, comerciante, está em tratamento de doença de Pott com\nacometimento de vértebras torácicas e lombares. Estava com a doença em remissão, quando\nqueixou-se de piora da dor local agora com irradiação para membros inferiores. Retornou a\napresentar febre e perdeu 6 quilos em 30 dias. Ao exame físico: emagrecida com abaulamento ao\nnível da transição toracolombar, dor a palpação e ausência de sinais flogísticos. Sem déficits\nneurológicos em membros inferiores. Presença de vários gânglios axilares, inguinais e cervicais,\npequenos, móveis, fibroelásticos e indolores. Abdome com dor à palpação difusa, mais localizada\nem planos profundos, à esquerda, e sem sinais de irritação peritoneal. Realizou a tomografia abaixo\npara elucidação diagnóstica. Assinale a principal hipótese diagnóstica.","options":{"A":"Pielonefrite xantogranulomatosa.","B":"Tuberculose renal.","C":"Abscesso de m. psoas.","D":"Infiltração entérica (tuberculose miliar)."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-2/373561.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-336253","number":"336253","sourceNumber":"336253","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Mulher, 67 anos procurou pronto socorro por constipação há 10 dias, náuseas e\nvômitos. História de atendimento prévio há 20\ndias devido dor em hipocôndrio direito, náuseas,\nvômitos, porém com resolução espontânea. Submetida a tomografia de abdome com imagem\nsugestiva de aerobilia intra-hepática. A hipótese diagnóstica mais provável para o quadro atual é:","options":{"A":"Colangiocarcinoma avançado","B":"Síndrome de Mirizzi","C":"Síndrome de dumping","D":"Íleo biliar"},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-321153","number":"321153","sourceNumber":"321153","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Com relação à hemobilia, assinale a alternativa CORRETA:","options":{"A":"A colelitíase é a causa mais importante de hemobilia.","B":"O hepatoblastoma é o tumor associado mais comum.","C":"A angioembolização é o tratamento inicial definitivo de escolha.","D":"A cintilografia com hemácias marcadas é a modalidade diagnóstica de escolha."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-337617","number":"337617","sourceNumber":"337617","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Homem, 65 anos, foi submetido a apendicectomia videolaparoscópica por apendicite\naguda com peritonite. Recebeu alta após 7\ndias. Retorna no ambulatório com resultado de exame\nanatomopatológico que mostra em adenocarcinoma invasivo mucinoso do apêndice, sem presença\nde linfonodo positivo. Nesse caso, assinale a alternativa que apresenta o tratamento ADEQUADO\ncomplementar para esse paciente.","options":{"A":"Quimioterapia seguida de observação clínica e dosagem de antígeno carcinoembrionário (CEA).","B":"Seguimento clínico, pois não teve linfonodos positivos na peça retirada na cirurgia.","C":"Hemicolectomia direita e peritoniectomia com quimioterapia citoredutora.","D":"Hemicolectomia direita."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-337621","number":"337621","sourceNumber":"337621","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Leia o trecho a seguir: Um paciente internado com quadro de obstrução intestinal,\napresenta no RX de abdome agudo imagem\ncujo tratamento deve ser a\nprincípio . Assinale a alternativa que preenche CORRETAMENTE as lacunas.","options":{"A":"em pilha de moeda, laparoscopia para lise de aderência.","B":"de níveis hidroaéreos, laparotomia exploradora.","C":"de \"\"U\"\" invertido, colonoscopia descompressiva.","D":"apagamento do psoas, laparoscopia para higiene da cavidade e descompressão."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-334724","number":"334724","sourceNumber":"334724","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente masculino, 74 anos, diabético, hipertenso e com by-pass coronariano prévio,\ndeu entrada no hospital com diagnóstico de pé\ndiabético, sem sinais de sepse, sendo internado\npara antibioticoterapia endovenosa. No segundo dia de internação, iniciou quadro de dor abdominal\ndifusa, intensa, encontrado gemente no quarto. Ao exame, paciente acordado, comunicativo,\ngemente, afebril, eupneico, taquicárdico (frequência cardíaca de 101 bpm), ritmo cardíaco irregular,\npulso amplo, abdome discretamente distendido, ruídos hidroaéreos diminuídos, timpânico,\ndepressível, levemente doloroso, sem sinais de irritação peritoneal. Apresentou hábito intestinal\nnormal até o início da dor. Diante do quadro, qual dos itens abaixo combina o tipo mais provável de\nabdome agudo e sua respectiva propedêutica de exame de imagem mais indicada?","options":{"A":"Abdome agudo inflamatório, ultrassonografia de abdome total.","B":"Abdome agudo obstrutivo, radiografia de abdome agudo (em pé, deitado e cúpulas\ndiafragmáticas).","C":"Abdome agudo hemorrágico, radiografia de abdome agudo (em pé, deitado e cúpulas\ndiafragmáticas).","D":"Abdome agudo vascular, angiotomografia de abdome com contraste endovenoso."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-334725","number":"334725","sourceNumber":"334725","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Sobre a apendicite aguda é CORRETO afirmar que:","options":{"A":"No escore diagnóstico de Alvarado estão incluídos exames laboratoriais, tais como proteína C\nreativa.","B":"Antibioticoterapia pós-operatória está indicada para pacientes com apendicite aguda não\ncomplicada.","C":"A apendicectomia videolaparoscópica está associada a maior incidência de abscesso\nintra-abdominal em casos de apendicites agudas com perfuração e necrose.","D":"O tratamento não operatório pode ser indicado com bons resultados para aqueles pacientes que\nse apresentam com apendicolito nos exames de\nimagem."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-335079","number":"335079","sourceNumber":"335079","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Considere as afirmativas a seguir sobre os tumores do intestino delgado (jejuno-ileal).\nI.\nOs carcinoides intestinais pequenos surgem a partir de células endócrinas intraepiteliais. II. Os\npequenos tumores carcinoides intestinais são mais frequentemente localizados no íleo a 60 cm da\nválvula ileocecal. III. Os carcinoides de intestino delgado sempre se apresentam sintomáticos.\n\nEstão corretas as afirmativas","options":{"A":"I e II, apenas.","B":"I e III, apenas.","C":"II e III, apenas.","D":"I, II e III."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-346862","number":"346862","sourceNumber":"346862","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo feminino, 54 anos relata dor em cólica em quadrante superior direito\ndo abdome, há trinta dias. Segundo a paciente,\nhá doze horas houve piora da dor localizada,\nassociada à febre e a calafrios. Refere ainda anorexia e que não evacua há quatro dias. Assinale a\nalternativa que apresenta o PROVÁVEL diagnóstico dessa paciente.","options":{"A":"Abdome agudo vascular.","B":"Abdome agudo obstrutivo.","C":"Abdome agudo inflamatório.","D":"Abdome agudo hemorrágico."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-321186","number":"321186","sourceNumber":"321186","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo masculino, 25 anos, em acompanhamento de uma leucemia\nrecentemente tratada, relata dor abdominal há\ncerca de 48 horas, inicialmente difusa que se\nlocalizou na Fossa Ilíaca Direita (FID) e posteriormente difusa novamente. Exames laboratoriais da\nadmissão mostram: leucócitos totais: 15.500; Hemoglobina: 13,5gr/dl; urina rotina normal. Ao\nexame clínico apresenta FC: 98bpm, FR: 17irpm, abdome levemente distendido, com\ndescompressão dolorosa na FID. A radiografia de tórax em ortostatismo não mostra\npneumoperitônio e radiografia de abdome mostra alça sentinela na FID. Em relação ao caso clínico\ndescrito, é CORRETO afirmar que:","options":{"A":"A antibioticoterapia para gram positivos deve ser iniciada apenas após a laparotomia\nexploradora comprovar o diagnóstico de apendicite aguda,\npara evitar resistência bacteriana.","B":"Pacientes com imunodeficiências, como esse devem sempre passar por tentativa de tratamento\nclínico da possível apendicite aguda,\ndevido os maiores riscos do procedimento cirúrgico nesses\npacientes.","C":"Diante dos sinais e sintomas típicos para o diagnóstico de apendicite aguda, o tratamento mais\nadequado será encaminhamento imediato ao bloco cirúrgico, para realização da cirurgia, além de\niniciar antibioticoterapia.","D":"Para esse caso clínico se torna obrigatória a realização de tomografia computadorizada de\nabdome, antes da abordagem cirúrgica."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-320455","number":"320455","sourceNumber":"320455","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente de 57 anos admitido em Pronto Socorro com quadro de dor abdominal de forte\nintensidade. Realizada rotina de abdome agudo com evidência de pneumoperitônio. Ao toque retal,\ndiagnosticada lesão de reto a 5 cm de margem anal, estenosante. Submetido a laparotomia de\nurgência, com identificação de válvula ileocecal competente e perfuração de ceco. Diante dos\nachados pré e intra-operatórios, qual a melhor conduta a ser tomada durante a cirurgia de\nurgência?","options":{"A":"Colectomia total com ressecção de lesão primária e ileostomia terminal.","B":"Colectomia direita com ileostomia à Mikulicz.","C":"Colectomia total com ressecção da lesão primária e íleo reto anastomose.","D":"Rafia de ceco com ileostomia em alça à montante da lesão.","E":"Rafia de ceco com amputação abdominoperineal do reto."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-314017","number":"314017","sourceNumber":"314017","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"O volvo é uma condição na qual o intestino sofre uma torção sobre o seu eixo\nmesentérico, uma situação que resulta em\nobstrução parcial ou completa do lúmen intestinal e de\num grau variável do seu suprimento sanguíneo. Com relação ao volvo intestinal, analisar os itens\nabaixo: I. O volvo é mais comum no cólon sigmoide, com ocorrências menos frequentes envolvendo\no cólon direito e o íleo terminal. II. Medicamentos psicotrópicos podem predispor ao volvo por\nafetarem a motilidade intestinal. III. Os pacientes com volvo de sigmoide podem apresentar uma\nobstrução intestinal aguda ou subaguda, com sinais e sintomas indistinguíveis daqueles causados\npor um câncer do cólon distal. IV. Um nível hidroaéreo pode ser visualizado anterior à alça do cólon\ndilatado, e quase sempre há ar no reto. Estão CORRETOS:","options":{"A":"Somente os itens I, II e III.","B":"Somente os itens I, II e IV.","C":"Somente os itens I, III e IV.","D":"Somente os itens II, III e IV.","E":"Todos os itens."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-314020","number":"314020","sourceNumber":"314020","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"O sangramento gastrointestinal (GI) alto refere-se a sangramentos que se originam do\ntrato GI proximal ao ligamento de Treitz, sendo responsável por quase 80% das hemorragias GI\nsignificativas. Com relação a esses sangramentos, assinalar a alternativa CORRETA:","options":{"A":"As causas de sangramento GI alto são melhor categorizadas em não varicosas ou\nsangramentos relacionados com hipertensão portal.","B":"As causas não varicosas, responsáveis por cerca de 80%, apresentam as lacerações de\nMallory-Weiss como a mais comum.","C":"Quando há confirmação de um sangramento de úlcera péptica, a utilização de IBPs (inibidores\nde bomba de prótons) é indicada, porém não tem\nmostrado a capacidade de reduzir o risco de\nressangramento e a necessidade de intervenção cirúrgica.","D":"A maioria das lacerações de Mallory-Weiss ocorre ao longo da curvatura maior e, menos\ncomumente, na curvatura menor.","E":"O esôfago é frequentemente um local de hemorragia significativa, como resultado de esofagite."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-314025","number":"314025","sourceNumber":"314025","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Sobre o diagnóstico de apendicite aguda em crianças, analisar os itens abaixo: I. Ao\nexame físico, o que mais chama a atenção, no\ninício, são fácies de sofrimento e postura do\npaciente - quieto, sem muita mobilidade, já que a movimentação desencadeia dor pela irritação\nperitoneal. II. Na fase inicial, o paciente apresenta tríade sintomática, caracterizada por dor\nperiumbilical, febre moderada e anorexia. III. As manobras palpatórias devem, idealmente, ser\niniciadas exatamente no ponto apendicular. Está(ão) CORRETOS(S):","options":{"A":"Somente os itens I e III.","B":"Somente o item III.","C":"Somente os itens I e II.","D":"Somente o item II.","E":"Somente o item I."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-304851","number":"304851","sourceNumber":"304851","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Assinale a assertiva INCORRETA com relação à Doença de Crohn.","options":{"A":"Considerando a avaliação macroscópica, as lesões podem afetar qualquer segmento do trato\ngastrointestinal, com inflamação transmural e propensão a fenótipos penetrantes.","B":"O intestino comprometido pela doença pode fistulizar para o intestino adjacente ou estruturas\nadjacentes normalmente não afetadas pela doença.","C":"Uma característica macroscópica observada nas abordagens cirúrgicas da doença é a serosite\ncom envolvimento e invasão da serosa pela gordura\nmesentérica.","D":"O clássico granuloma não caseoso é encontrado em menos de 15% das biópsias, sendo o\ndiagnóstico baseado na soma de achados clínicos, endoscópicos e de imagens."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-306706","number":"306706","sourceNumber":"306706","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"L.P.A, 38 anos, sem comorbidades prévias, foi trazida ao hospital após ter apresentado\nepisódio de hematêmese em domicílio. Nega\nalergias. Relata estar em uso de ibuprofeno por conta\nde lombalgia após esforço físico há 15 dias. Foi submetida a endoscopia digestiva alta que\ndemonstrou úlcera gástrica com sangramento ativo difuso. Com relação ao quadro apresentado,\nqual é a classificação de Forrest da úlcera apresentada pela paciente e o risco de ressangramento,\nrespectivamente?","options":{"A":"Forrest IA ? Alto risco de ressangramento","B":"Forrest IB ? Alto risco de ressangramento","C":"Forrest IB ? Baixo risco de ressangramento","D":"Forrest IA ? Baixo risco de ressangramento"},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-305003","number":"305003","sourceNumber":"305003","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A respeito do exame físico nos pacientes com hemorragia digestiva baixa (HDB),\nanalise as afirmativas a seguir. I. O exame\nfísico frequentemente é bastante elucidativo em relação\nà etiologia da HDB, além de ser útil na avaliação da extensão do sangramento. II. A presença de\nhipotensão ortostática e choque é menor na HDB do que na hemorragia digestiva alta, o que requer\nmenos transfusão de sangue. III. Pacientes com sangramento de cólon têm uma necessidade\nmenor de transfusão de sangue do que aqueles em que a causa da hemorragia encontra-se no\nintestino delgado. Está(ão) correta(s) a(s) afirmativa(s)","options":{"A":"I, apenas.","B":"I e II, apenas.","C":"III, apenas.","D":"II e III, apenas."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-313292","number":"313292","sourceNumber":"313292","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente de 42 anos, sexo masculino, assistente administrativo há 20 anos, casado,\ncaucasiano, diabético tipo II, sem alterações da pressão arterial e frequência respiratória,\ntaquicárdico (112bpm), provavelmente, por conta de dor abdominal intensa, Temperatura axilar\n38,8oC. Foi encaminhado pela Clínica Médica para Cirurgia Geral, chegando ao consultório, após\nexame físico, o Cirurgião considera Psoas Positivo. Qual manobra propedêutica realizada?","options":{"A":"Dor no quadrante inferior direito induzida pela palpação do quadrante inferior esquerdo.","B":"Dor provocada quando o examinador estende passivamente o quadril direito do paciente.","C":"Dor a descompressão, pesquisada na palpação profunda.","D":"Dor à descompressão brusca do ponto cístico.","E":"Aumento da sensibilidade quando os músculos da parede abdominal são contraídos."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-313293","number":"313293","sourceNumber":"313293","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Diante do caso, da questão anterior, o Cirurgião entende que Sinal de Psoas positivo é\num forte indicativo de:","options":{"A":"Colecistite aguda.","B":"Pancreatite aguda.","C":"Apendicite aguda.","D":"Pancreatite necro-hemorrágica.","E":"Ruptura esplênica."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-313294","number":"313294","sourceNumber":"313294","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Sobre os sinais semiológicos de abdome agudo inflamatório, o sinal de Dunphy é\ndescrito como:","options":{"A":"Diminuição global dos RHA.","B":"Dor abdominal ao tossir.","C":"Timpanismo em região hepática.","D":"Posição antálgica (flexão do joelho contra o quadril).","E":"Compressão retrógrada em flanco esquerdo com dor em FID."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-305010","number":"305010","sourceNumber":"305010","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Considere que um paciente de 69 anos de idade apresenta-se com quadro de dor\nabdominal inespecífica há duas semanas,\nacompanhado de febre quase diariamente. O hábito\nintestinal está normal. Ao exame físico, encontra-se hemodinamicamente estável, vígil e orientado.\nÉ realizada tomografia computadorizada que demonstra abscesso de, aproximadamente, 10 cm na\nfossa ilíaca direita, em topografia de íleo terminal, sendo sugestiva de abscesso apendicular. Nesse\ncaso, é correto afirmar:","options":{"A":"A drenagem percutânea e a antibioticoterapia são mais indicadas que a cirurgia.","B":"A técnica de apendicectomia aberta é indicada por ter menos complicações que a cirurgia\nlaparoscópica.","C":"A tomografia computadorizada não tem boa acurácia para esse diagnóstico.","D":"A apresentação clínica não é compatível com o diagnóstico de apendicite."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-291947","number":"291947","sourceNumber":"291947","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente admitido com hematêmese no Pronto Socorro onde você trabalha. No exame\nfísico paciente se encontra agitado, sudorético, taquipneico, afebril, descorado. Pulsos finos de\n120bpm, PA: 90X50mmHG, ascite e baço palpável. Considerando o caso descrito, é CORRETO\nafirmar que:","options":{"A":"O paciente está em choque hipovolêmico grau 2 necessita de acesso venoso periférico com\njelco calibroso e ressuscitação volêmica com solução hidroeletrolítica.","B":"A hemorragia significativa e pela epidemiologia da hemorragia digestiva alta, no Brasil, a causa\ndeve ser uma úlcera péptica.","C":"O paciente após ressuscitação volêmica adequada deve iniciar análogo da somatostatina e\nendoscopia realizada em até 12 horas.","D":"A escolha de tratamento inicial seria a opção cirúrgica se analisamos a gravidade do caso."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-291949","number":"291949","sourceNumber":"291949","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente J.M.S. mulher 27 anos admitida no Pronto Socorro com quadro de abdômen\nagudo. Início da dor há cerca de 8 horas em\nandar inferior do abdômen principalmente a direita.\nNega vômitos, mas está um pouco nauseada. Relata também leve corrimento claro vaginal, há uns\ndias. Na história pregressa, faz uso de anticoncepcional de forma irregular e está casada há dois\nanos. No exame físico está com sudorese leve, corada no limiar, eupneica e tax. de 37,4Cº, PA:\n100X50mmHg e FC: 108bpm, abdômen está um pouco distendido com dor em andar inferior e\nBlumberg positivo a direita. Sinal de Chandelier negativo. Foi ao banheiro para colher o exame de\nurina solicitado e apresentou uma síncope quando se levantou. Exame laboratorial mostrou\nleucocitose de 12.500 leucócitos ainda sem resultado do diferencial e HB de 11,2gr/dl com HT de\n\n31. PCR está aumentado. Ultrassom mostrou líquido na cavidade. Considerando o caso descrito é\nCORRETO afirmar que o diagnóstico mais provável e a conduta para essa paciente deve ser:","options":{"A":"Gravidez ectópica rota indicar cirurgia.","B":"Doença inflamatória pélvica iniciar antibioticoterapia.","C":"Apendicite aguda confirmar com tomografia.","D":"Infecção do trato urinário e solicitar exame de urina rotina e gram de gota."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-314086","number":"314086","sourceNumber":"314086","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Em relação à apendicite em pediatria, assinalar a alternativa CORRETA:","options":{"A":"É a causa mais comum de abdome agudo em crianças em idade pré-escolar e escolar.","B":"O sinal de Rovsing é caracterizado por dor à descompressão brusca do ponto de McBurney.","C":"O sinal de Blumberg é caracterizado por dor em fossa ilíaca direita por compressão em fossa\nilíaca esquerda.","D":"Sinal de Giordano e Jobert positivos confirmam apendicite aguda.","E":"Sinal de Cullen positivo confirma apendicite aguda."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-257340","number":"257340","sourceNumber":"257340","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Homem de 57 anos realiza exame periódico de saúde com seu clínico. É portador de\nHipertensão Arterial Sistêmica (HAS) há 22 anos e diabetes mellitus tipo 2 há 2 anos. Faz uso\nregular de anlodipino 10mg, 1 vez ao dia, e metformina 1000mg, 1 vez ao dia. Não possui queixas\nou outras comorbidades. O exame físico não apresenta anormalidades. Traz resultado de pesquisa\nde sangue oculto nas fezes, que resultou positivo em 1 de 3 amostras. Após a correta interpretação\ndo resultado da pesquisa de sangue oculto nas fezes apresentado por esse paciente, a conduta\nsequencial MAIS ADEQUADA é a de:","options":{"A":"Realizar colonoscopia.","B":"Realizar endoscopia digestiva alta.","C":"Repetir a pesquisa de sangue oculto nas fezes.","D":"Solicitar a cinética do ferro."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-283888","number":"283888","sourceNumber":"283888","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Em relação à hemorragia digestiva baixa, assinale a alternativa correta.","options":{"A":"Acima dos 50 anos, a causa mais frequente é a neoplasia intestinal.","B":"Abaixo dos 50 anos, a causa mais frequente é a angiodisplasia.","C":"O sangramento diverticular raramente cessa espontaneamente.","D":"95% dos casos originam-se do cólon.","E":"Angiodisplasia não é causa de sangramento digestivo baixo, somente de sangramento digestivo\nalto."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-266366","number":"266366","sourceNumber":"266366","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A doença celíaca (DC) é uma enteropatia imunomediada causada por sensibilidade\npermanente ao glúten em indivíduos geneticamente predispostos. Na DC é correto afirmar:","options":{"A":"A forma clássica da DC é caracterizada pela presença de constipação intestinal refratária ao\ntratamento, distensão abdominal, dor epigástrica e perda de peso.","B":"Os principais testes para o diagnóstico da doença celíaca são a calprotectina fecal e o anticorpo\nantiendomísio da classe IgG e IgM.","C":"Em pacientes com DC deve ser evitado trigo, milho, cevada e lentilha.","D":"Nas formas atípicas da DC pode ocorrer anemia por deficiência de ferro refratária à ferroterapia\noral, artralgias ou artrites e atraso puberal."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-287847","number":"287847","sourceNumber":"287847","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Em relação à Diverticulite Aguda, analisar os itens abaixo: I. O estágio II da\nClassificação de Hinchey corresponde a grande\nabcesso que se estende para pelve. II. Devido a\nsua localização típica, faz diagnóstico diferencial com a colite isquêmica: a colite\npseudomembranosa e a retocolite ulcerativa. III. No estágio IV da Classificação de Hinchey, a taxa\nde mortalidade chega a 95%. Está(ão) CORRETO(S):","options":{"A":"Somente o item I.","B":"Somente o item II.","C":"Somente os itens I e II.","D":"Somente os itens I e III.","E":"Todos os itens."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-287850","number":"287850","sourceNumber":"287850","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Em relação à Isquemia Mesentérica Aguda, analisar os itens abaixo: I. Geralmente,\napresenta-se como dor mesogástrica ou\nperiumbilical. II. Arritmias, insuficiência cardíaca,\naterosclerose, vasculites e infarto do miocárdio recente são os principais fatores de risco e tem,\ncomo principal prevalência, o início da idade adulta. III. A mortalidade é superior a 60%. Está(ão)\nCORRETO(S):","options":{"A":"Somente o item I.","B":"Somente o item II.","C":"Somente os itens I e III.","D":"Somente os itens II e III.","E":"Todos os itens."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-287851","number":"287851","sourceNumber":"287851","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Em relação à dor e sua caracterização, assinalar a alternativa CORRETA:","options":{"A":"Inflamação, distensão e isquemia do peritônio visceral ou do mesentério causam um tipo de dor\nprofunda, vaga e pouco localizada, conhecida como dor referida.","B":"A dor visceral é mediada pelo sistema nervoso autônomo.","C":"A dor visceral é aquela sentida em um local distante de onde se originou.","D":"A dor visceral é bem localizada, intensa e aguda, pois é transmitida por inervação somática.","E":"A dor parietal é profunda, vaga e pouco caracterizada."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-287852","number":"287852","sourceNumber":"287852","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Em relação à apendicite, assinalar a alternativa CORRETA:","options":{"A":"Os principais agentes encontrados nos quadros de apendicite são Escherichia coli e Bacteroides\nfragili.","B":"A dor abdominal oriunda da apendicite melhora com a eliminação de flatos ou com evacuação.","C":"Se associado à dor abdominal ocorrer anorexia, está afastado o quadro de apendicite.","D":"A dor abdominal oriunda da apendicite guarda relação com atividade física ou posição.","E":"A ocorrência de diarreia é muito comum na fase inicial do quadro."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-287853","number":"287853","sourceNumber":"287853","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Assinalar a alternativa cujas patologias mais se relacionam à dor em hipocôndrio\ndireito:","options":{"A":"Cólica biliar, colecistite, colangite e hepatite.","B":"Cólica biliar, apendicite, colangite e hepatite.","C":"Diverticulite, apendicite, colangite e hepatite.","D":"Diverticulite, apendicite, isquemia mesentérica e hepatite.","E":"Diverticulite, apendicite, colecistite e colangite."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-287858","number":"287858","sourceNumber":"287858","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A Doença de Crohn (DC) é um distúrbio de etiologia desconhecida, caracterizado por\ninflamação transmural do trato gastrointestinal. Em relação à DC, assinalar a alternativa CORRETA:","options":{"A":"A localização mais comum para a ulceração é a região anal.","B":"A maioria dos pacientes desenvolve DC no trato gastrointestinal superior.","C":"O aspecto de paralelepípedos à endoscopia é comum na colite ulcerativa, diagnóstico diferencial\nmais comum da DC.","D":"Distúrbios oculares, especialmente uveíte e episclerite, são as manifestações extraintestinais\nmais comuns.","E":"Aproximadamente 30% dos pacientes podem desenvolver fístulas."},"answer":"E","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-260696","number":"260696","sourceNumber":"260696","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Qual das seguintes afirmativas sobre o tratamento com glicocorticoides na retocolite\nulcerativa (RCUI) é VERDADEIRA?","options":{"A":"O glicocorticoide é indicado na indução e manutenção da remissão em pacientes com RCUI\nmoderada agrave.","B":"Doses acima do equivalente a 40?60mg/dia não são associadas a benefício clínico adicional.","C":"O hormônio adrenocorticotrófico é a alternativa mais segura ao tratamento convencional com\nglicocorticoides.","D":"A budesonida oral é uma alternativa igualmente eficaz e segura à terapia convencional com\nglicocorticoides.","E":"Os glicocorticoides tópicos (retal) são mais efetivos que a mesalazina tópica no tratamento da\ndoença distal."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-257377","number":"257377","sourceNumber":"257377","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Sobre as neoplasias colorretais, assinale a alternativa que apresenta a associação\nCORRETA:","options":{"A":"Os pólipos da síndrome de Peutz-Jeghers estão associados a neoplasia de canal anal\nespecificamente.","B":"A polipose adenomatosa familiar está associada a hipertrofia congênita do epitélio pigmentar\nretiniano.","C":"Os pólipos juvenis são pólipos inflamatórios e constituem os pólipos mais comuns em crianças,\ngeralmente com apresentação solitária, e não se associam a potencial maligno.","D":"A síndrome de Turcot está associada a neoplasia primária do sistema sanguíneo e polipose\ncolorretal."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-266399","number":"266399","sourceNumber":"266399","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente idoso, acamado, trazido a Unidade de Pronto Atendimento com quadro agudo\nde dor abdominal e distensão abdominal,\nmais evidente em andar inferior do abdome, associado\ncom parada de eliminação de fezes e flatos. Família relata histórico de fecaloma de repetição. No\nRaio X de abdome fica evidente imagem com sinal de \"bico de pássaro\" e grande dilatação em\ncólon sigmóide, sem dilatação a montante em alças de delgado. Dentre as hipóteses abaixo, qual o\nprovável diagnóstico?","options":{"A":"Úlcera Gástrica Perfurada.","B":"Pancreatite Aguda.","C":"Retocolite Ulcerativa.","D":"Volvo de Cólon Sigmóide."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-266404","number":"266404","sourceNumber":"266404","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente masculino, 55 anos, com história prévia de laparotomia mediana infraumbilical\nhá 20 anos devido à apendicite aguda. Deu\nentrada no pronto-socorro com quadro de parada de\neliminação de fezes há 4 dias, com eliminação de flatos presentes. Ao exame físico, foi observado\nabdome com hipertimpanismo discreto, sem sinais de irritação peritoneal ou herniações de parede\nabdominal. Radiografia de abdome mostra distensão leve de intestino delgado difusamente, sem\nníveis hidroaéreos ou pneumoperitônio. Foi optado por tomografia de abdome com contraste oral\nque evidenciou distensão discreta de alças de delgado, sem fatores obstrutivos ou perfurativos\nevidentes, sem sinais de sofrimento intestinal, com contraste chegando até o jejuno. Diante do\nquadro clínico, qual a principal hipótese diagnóstica?","options":{"A":"Suboclusão intestinal por aderências.","B":"Oclusão intestinal metabólica.","C":"Hérnia inguinal encarcerada.","D":"Apendicite aguda."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-227079","number":"227079","sourceNumber":"227079","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Homem de 32 anos se queixa de dor abdominal periumbilical em cólica, que alivia após\na evacuação. Há diarreia em grande volume com\nfezes líquidas, algumas vezes contendo sangue,\nem 4 episódios ao dia, há 35 dias. Apresentou alguns episódios febris e perdeu 2 kg no período.\n\nDesconhece doenças prévias e nega o uso de medicamentos ou drogas ilícitas. O exame do\nabdômen revela dor à palpação profunda difusa,\nsem sinais de irritação peritoneal. O toque retal\nnão revela alterações. Sem outras anormalidades no restante do exame físico. Exames de\nlaboratório: hemoglobina 11,2 g/dl, leucócitos 5.460/mm³, plaquetas 230.000/mm³, proteína\n\nC-reativa 12 mg/dl, calprotectina fecal positiva. Colonoscopia: áreas de hiperemia e úlceras\nlongitudinais na mucosa do íleo terminal,\nângulo esplênico do cólon e sigmoide. Demais regiões\ncom mucosas de características normais. Considerando o caso descrito, assinale a alternativa que\napresenta o diagnóstico MAIS ADEQUADO para esse paciente:","options":{"A":"Colite isquêmica.","B":"Doença de Crohn.","C":"Retocolite ulcerativa.","D":"Síndrome do cólon irritável."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-255628","number":"255628","sourceNumber":"255628","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Em relação à apendicite aguda, MARQUE A CORRETA:","options":{"A":"A tríade sintomática é caracterizada por dor periumbilical, febre moderada e anorexia aparecem\nem somente 50% dos casos.","B":"Os resultados normais de hemograma não auxiliam na exclusão do diagnóstico.","C":"É a segunda causa mais frequente de abdome agudo cirúrgico da criança.","D":"A adenite mesentérica, por ser infrequente, não é um diagnóstico diferencial possível."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-246731","number":"246731","sourceNumber":"246731","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"No rastreio dos tumores de colón e reto, na população geral, a conduta mais correta,\ndentre as abaixo, é:","options":{"A":"Hemograma completo e dosagem de CEA (antígeno carcinoembrionário) anualmente.","B":"Hemograma completo, dosagem de CEA (antígeno carcinoembrionário) e pesquisa de sangue\noculto nas fezes a cada 2 anos.","C":"Dosagem de CEA anualmente.","D":"Pesquisa de sangue oculto nas fezes a cada 5 anos.","E":"Colonoscopia a cada 10 anos entre 50 e 75 anos de idade."},"answer":"E","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-255630","number":"255630","sourceNumber":"255630","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Tadeu, 55 anos, apresenta-se no serviço de urgência com dor em quadrante inferior\nesquerdo do abdome. Sobre os achados que\naumentam a suspeição para diverticulite, MARQUE A\nCORRETA:","options":{"A":"Hipotermia","B":"Diarréia","C":"Sangramento retal","D":"Distensão abdominal"},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-246372","number":"246372","sourceNumber":"246372","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Homem de 60 anos, com dor abdominal de início no flanco esquerdo há 3 dias, chegou\nao pronto-socorro com quadro de dor abdominal\ndifusa. Ao exame físico: palidez, FC: 110 bpm, PA:\n100x70 mmHg, dor e defesa voluntária da musculatura abdominal na parte inferior esquerda do\nabdome. Exames laboratoriais: Hematócrito 35% / Hemoglobina 11,6 mg/dl / Leuco 19380\n(mielócitos 0%/ metamielócitos 0%/ bastões 14%/ segmentados 57%/ eosinófilos 0% / linfócitos\n22%/ monócitos 7%) PLQ 255.000 mm³ PCR 23,9. Tomografia computadorizada de abdome com\nespessamento parietal intestinal e identificação do divertículo inflamado em sigmoide com abscesso\npericolônico medindo 8 x 10 cm. Sobre o caso apresentado, a classificação conforme Hinchey e a\nmelhor conduta são, respectivamente:","options":{"A":"Hinchey 1; tratamento cirúrgico","B":"Hinchey 2; drenagem percutânea","C":"Hinchey 3; sigmoidectomia","D":"Hinchey 4; drenagem aberta"},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-246373","number":"246373","sourceNumber":"246373","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Homem de 76 anos, com dor abdominal em fossa ilíaca direita há 6 horas, deu entrada\nno pronto-socorro com vômitos e distensão\nabdominal. Exame físico com abaulamento, dor, calor e\nrubor em topografia inguinal. Exames laboratoriais: Hematócrito 40% / Hemoglobina 13,5mg/dl /\nLeuco 16200 (mielócitos 0%/ metamielócitos 0%/ bastões 8%/ segmentados 66%/ eosinófilos 1% /\nlinfócitos 22%/ monócitos 3%) Plaquetas: 280.000 mm³ / PCR 58. Radiografia simples de abdome\ncom níveis hidroaéreos. Diante da suspeita de hérnia estrangulada, qual a conduta mais resolutiva?","options":{"A":"Antibioticoterapia endovenosa","B":"Laparoscopia diagnóstica","C":"Abordagem pré-peritoneal aberta","D":"Laparotomia xifo-pubiana"},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-246374","number":"246374","sourceNumber":"246374","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Mulher de 54 anos, apresentando 3 episódios de hematoquezia há 2 horas, chegou ao\npronto-socorro com quadro de hipotensão, taquicardia e sudorese. No exame físico: PA= 90x60\nmmHg, FC=110 bpm e palidez cutânea. Realizada passagem de sonda nasogástrica com saída de\nbile. Visando uma abordagem bem definida e lógica para essa paciente com hemorragia\ngastrointestinal aguda, qual a próxima conduta?","options":{"A":"Endoscopia digestiva alta","B":"Colonoscopia","C":"Endoscopia por cápsula","D":"Colectomia subtotal"},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-234438","number":"234438","sourceNumber":"234438","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Sobre a apendicite aguda, assinale a alternativa CORRETA:","options":{"A":"A diminuição de ingestão de fibras é fator de risco para desenvolver apendicite aguda.","B":"O fecalito é causa da obstrução em mais de 80% dos casos.","C":"A dor inicial, mal localizada, se deve a distensão do orgão e dura cerca de 1 hora.","D":"O sinal do obturador, dor a rotação interna da coxa, ocorre em pacientes com apendicite\nretrocecal."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-234440","number":"234440","sourceNumber":"234440","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Sr. Carlos Alberto 65 anos é admitido no pronto-socorro com dor abdominal há cerca de\n36 horas e piora progressiva. Relata\nlocalização em fossa ilíaca esquerda onde apresenta sinal de\nBlumberg. Não tem febre e tem bom estado geral. Paciente hipertenso e utiliza diuréticos. Sobre o\ncaso descrito, assinale a alternativa CORRETA:","options":{"A":"O diagnóstico é de diverticulite aguda Hinchey 1.","B":"O paciente deve ser encaminhado para internação e cirurgia e no mesmo dia para colectomia\nesquerda.","C":"O clister glicerinado pode auxiliar na melhora da dor desse paciente.","D":"O tratamento clínico está indicado com antibioticoterapia para gram negativos e anaeróbios e\nobservação clínica."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-232149","number":"232149","sourceNumber":"232149","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Durante o plantão em pronto-soccorro, dá entrada um paciente, masculino, 72 anos,\nhistória de mal de Parkinson, constipação\ncrônica e início de quadro de dor abdominal difusa e mal\ndefinida, associada à distensão abdominal moderada, com parada de eliminação de fezes há\naproximadamente 5 dias. Durante o exame físico evidenciou-se a presença do sinal de Gersuny.\n\nDiante desse quadro apresentado, assinale a alternativa que melhor indica a principal hipótese\ndiagnóstica:","options":{"A":"Isquemia mesentérica.","B":"Constipação crônica refratária ao tratamento clínico.","C":"Diverticulite aguda complicada.","D":"Tumoração estenosante em cólon esquerdo.","E":"Obstrução intestinal por fecaloma."},"answer":"E","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-232150","number":"232150","sourceNumber":"232150","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"O Antígeno Cárcino-embrionário (CEA) é um marcador tumoral utilizado no câncer\ncolorretal. Sobre o mesmo, assinale a alternativa incorreta:","options":{"A":"Sua elevação no pós-operatório é patognomônica para a presença de mestástase hepática.","B":"A maioria dos carcinomas precoces está associada a níveis normais de CEA.","C":"Elevações do CEA têm sido encontradas em doenças não malignas do cólon.","D":"Tabagismo é causa de elevação na sua dosagem sanguínea.","E":"Seu aumento nesses pacientes deve impor a realização de PET-Scan."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-243036","number":"243036","sourceNumber":"243036","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Admitida na UTI geral de um hospital, paciente de 68 anos, sexo feminino, hipertensa\nhá mais de 20 anos, com quadro de queda do\nestado geral, sonolência, diarreia de início há 2 dias,\ncom grande volume e vários episódios de evacuação por dia. Pressão Arterial de 100/50 mmHgOs\nexames mostraram Na = 119; K=3,0; HTC = 38%; Hb = 13,0, Leucócitos = 12500 com 5% de\nBastões e plaquetas = 250.000 . Uréia = 75, Creatinina = 1,6 , glicose = 70 . Peso 60 Kg. Assinale a\nalternativa que melhor explica o distúrbio do sódio e a conduta para este paciente:","options":{"A":"trata-se de uma Hiponatremia Euvolêmica, sendo a melhor conduta para este paciente a\nreposição de sódio com solução salina hipertônica - NaCl a 3%.","B":"trata-se de uma Hiponatremia Euvolêmica, sendo a melhor conduta para este paciente, a\ncorreção do sódio com solução salina isotônica ? Soro Fisiológico 0,9%.","C":"trata-se de uma Hiponatremia Hipovolêmica, sendo a melhor conduta para este paciente, a\nreposição de sódio com solução salina hipertônica - NaCl a 3%.","D":"trata-se de uma Hiponatremia Hipovolêmica, sendo a melhor conduta para este paciente a\ncorreção do sódio inicialmente com solução salina isotônica ? Soro Fisiológico 0,9%.","E":"trata-se de uma Hiponatremia Hipervolêmica, sendo a melhor conduta para este paciente a\ncorreção do sódio inicialmente com solução salina isotônica ? Soro Fisiológico 0,9%."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-246780","number":"246780","sourceNumber":"246780","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"A suscetibilidade hereditária ao câncer pode ser claramente observada nas diversas\nsíndromes genéticas, nas quais os fatores genéticos desempenham um papel central. Sobre a\nsíndrome do Câncer colorretal hereditário não poliposo (HNPCC) ou síndrome de Lynch é\nCORRETO afirmar que:","options":{"A":"Por se tratar de câncer colorretal não relacionado a polipose, a colonoscopia de rastreio não é,\ncomo via de regra, recomendada de forma rotineira.","B":"Alguns pacientes com HNPCC podem apresentar associação com tumores do SNC, na\nchamada síndrome de Gardner.","C":"o tumor extracólico mais comum na Síndrome de Lynch é o câncer de ovário.","D":"trata-se de uma síndrome genética com herança autossômica recessiva, associada a mutações\nem, pelo menos, cinco genes de reparo de\nDNA: MSH2, MSH6, MLH1, PMS1 e PMS2","E":"Dentre os tumores colorretais com caráter hereditário, a Síndrome de Lynch é a mais comum,\nrespondendo por cerca de 3 a 5% do total das neoplasias colorretais."},"answer":"E","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-246785","number":"246785","sourceNumber":"246785","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"O intestino delgado representa cerca de 75% do comprimento e 90% da área de\nsuperfície do trato digestivo e, de forma contraditória, responde por apenas 1% das neoplasias\nmalignas do sistema digestivo. Sobre o câncer do intestino delgado, pode-se afirmar:","options":{"A":"O adenocarcinoma do instestino delgado ocorre mais frequentemente na porção terminal do íleo\ne geralmente está associado à doença de Crohn.","B":"O GIST (tumor estromal gastrointestinal) se localiza mais fr//equentemente no duodeno. Por sua\ndisseminação ser hematogênica a linfadenectomia é prescindível durante a ressecção cirúrgica.","C":"Os tumores carcinóides do delgado se localizam de forma mais frequente no íleo terminal e\nraramente apresenta metástases quando comparamos com outros sítios primários.","D":"As manifestações exuberantes da síndrome carcinóide são frequentes nos tumores localizados\nno intestino médio acometendo mais da metade dos\npacientes com tumores carcinoides desta\nlocalização.","E":"Devido ao caráter indolente/crescimento lento dos tumores carcinóides, a ressecção ampla do\ntumor primário é preconizada mesmo nos pacientes já com doença metastática."},"answer":"E","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-243056","number":"243056","sourceNumber":"243056","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Qual a conduta mais adequada diante de um paciente portador de adenocarcinoma de\nreto a 7 cm da borda anal cujos exames de estadiamento (tomografia de tórax e abdome e\nressonância magnética de pelve) mostraram tratar-se de uma lesão estádio clínico T3N0M0?","options":{"A":"Radioquimioterapia neoadjuvante seguido de retossigmoidectomia e anastomose colorretal.","B":"Retossigmoidectomia com anastomose colorretal seguido de radioquimioterapia adjuvante.","C":"Amputação abdominoperineal do reto (cirurgia de Miles) seguido de quimioterapia adjuvante.","D":"Quimioterapia neoadjuvante seguido de retossigmoidectomia com colostomia terminal (cirurgia\nde Hartmann).","E":"Radioterapia neoadjuvante seguido de amputação abdominoperineal do reto (cirurgia de Miles)."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-196809","number":"196809","sourceNumber":"196809","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Segundo o sistema de pontuação de Alvarado Modificado para a Apendicite Aguda, a\npresença de sensibilidade na fossa ilíaca direita e a leucocitose >10.000, corresponde a pontuação\ntipo:","options":{"A":"1","B":"2","C":"3","D":"4"},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-196732","number":"196732","sourceNumber":"196732","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Os pólipos colônicos mais comuns mostrando células com desnaturação são:","options":{"A":"Adenomatosos.","B":"Esquistossomóticos.","C":"Hiperplásicos.","D":"Vilosos."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-212937","number":"212937","sourceNumber":"212937","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"No tocante às hemorragias digestivas altas, assinale a INCORRETA:","options":{"A":"A doença ulcerosa péptica é a maior causa de hemorragia digestiva alta.","B":"O H. pylori é associado com recorrência de sangramento em pacientes com úlcera duodenal.","C":"A passagem de sonda nasogástrica é recomendada na maioria dos casos.","D":"A profilaxia de peritonite bacteriana espontânea é recomendada em todos os pacientes com\nhemorragias digestivas altas varicosas.","E":"A eficácia da ligadura é maior que a escleroterapia para pacientes com hemorragia varicosa\naguda."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-212974","number":"212974","sourceNumber":"212974","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente de 32 anos, feminina, submetida à gastroplastia redutora em Y de Roux\nvideolaparoscópica (by-pass) há 6 meses, apresenta dor em hipocôndrio esquerdo há cerca de 8\ndias, que piora após se alimentar, apresentando também náuseas mas relata que \"não consegue\nvomitar\". Nega disfagia. Relata piora da dor há 4 horas, sem febre ou icterícia, dando entrada no\nPS com PA 120/70 mmHg, corada, Hb 12,1 leucócitos totais 9700 sem desvio, satO2 de 98% em ar\nambiente. Foi realizada radiografia de abdome agudo evidenciando distensão de alças\nisoladamente em hipocôndrio esquerdo e aparente distensão do estômago excluso. Qual a principal\nhipótese diagnóstica?","options":{"A":"Litíase biliar.","B":"Hérnia de Petersen.","C":"Isquemia intestinal.","D":"Estenose da gastroenteroanastomose.","E":"Úlcera marginal na anastomose gastro-jejunal"},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-215111","number":"215111","sourceNumber":"215111","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Em relação a dor abdominal de tratamento cirúrgico em idosos, podemos dizer que são\nfrequentes as patologias abaixo, EXCETO:","options":{"A":"Torção de ovário.","B":"Isquemia Mesentérica.","C":"Ruptura de Aneurisma de Aorta.","D":"Vólvulo Intestinal.","E":"Colecistite Aguda."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-220325","number":"220325","sourceNumber":"220325","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Um paciente, sexo masculino, 50 anos, assintomático apresentou sangue oculto nas\nfezes como positivo. Sobre o caso descrito, assinale a alternativa CORRETA:","options":{"A":"Um paciente normal pode perder até 2,5 ml sangue por dia nas fezes.","B":"O exame deve ser repetido e, se positivo, deve-se investigar com endoscopia digestiva alta e\ncolonoscopia.","C":"A melena pode ser produzida por quantidade acima de 200 ml no estômago.","D":"São causas de hemorragia digestiva alta, as úlceras gastroduodenais, a síndrome de\nMallory-Weis e, de hemorragia digestiva baixa, a doença diverticular dos cólons e a hemobilia."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-212897","number":"212897","sourceNumber":"212897","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Mulher 74 anos, hipertensa, diabética, com história de constipação crônica, foi levada\nao PS por familiares devido distensão\nabdominal com parada de eliminação de flatos e fezes há 3\ndias. Durante a avaliação inicial, exames laboratoriais apresentando apenas discreta anemia (Hb 10\ng/dl) e leucocitose (13.000/mm³) com desvio (10% de bastões). TC de abdome evidencia distensão\ncolônica até o cólon descendente, diversos divertículos em todo o cólon esquerdo, borramento de\ngordura em torno de todo o sigmoide, com duas coleções justa parede do sigmoide, uma medindo\n1,1 x 0,7 cm e outra 1,8 x 2,1 cm. Qual a classificação tomográfica (Hinchey) e o tratamento\ninicial?","options":{"A":"Hinchey I. Antibioticoterapia.","B":"Hinchey II. Antibioticoterapia.","C":"Hinchey III. Laparotomia com retossigmoidectomia à Hartmann.","D":"Hinchey I. Laparotomia com retossigmoidectomia com reconstrução primária.","E":"Hinchey II. Laparotomia com retossigmoidectomia com reconstrução primária."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-220320","number":"220320","sourceNumber":"220320","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente de 55 anos é admitido no pronto-socorro onde você estava de plantão.\nApresentava dor abdominal em cólica, que teve\ninício há 24 horas. Associados à dor, apresenta\nvários episódios de vômitos e distensão abdominal. Na história pregressa, tem passado de cirurgia\npara uma esplenectomia devido à queda em escada ocorrida 10 anos atrás. Hipertenso, usa\ndiuréticos e captopril. Na radiografia de tórax, não se encontra nada de anormal e, na radiografia\nde\nabdome, apresenta distensão de alças e pilhas de moeda. Sobre o caso descrito, assinale a\nalternativa CORRETA:","options":{"A":"O quadro clínico sugere possível neoplasia de cólon direito.","B":"O tratamento inicial deve ser realizado com hidratação, sonda nasogástrica e prescrição de\nantibioticoterapia profilática.","C":"O toque retal deve ser dispensado para exame desse paciente.","D":"O mais provável diagnóstico seria uma possível brida."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-212905","number":"212905","sourceNumber":"212905","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente do sexo masculino, 55 anos de idade, foi encaminhado para colonoscopia por\nqueixas de constipação progressiva e sangramento retal há 3 meses. O exame revelou lesão\nvegetante e ulcerada, não obstrutiva, no cólon sigmoide. O restante do cólon foi avaliado e\napresentava-se normal. As biópsias confirmaram tratar-se de adenocarcinoma, e o paciente foi\nsubmetido a retossigmoidectomia. Como orientar o seguimento endoscópico desse paciente?","options":{"A":"Colonoscopia 6 meses após a cirurgia.","B":"Colonoscopia 1 ano após cirurgia.","C":"Colonoscopia 2 anos após cirurgia.","D":"Colonoscopia 3 anos após cirurgia.","E":"Colonoscopia 3 meses após cirurgia."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-212908","number":"212908","sourceNumber":"212908","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Com relação aos divertículos cólicos, assinale a alternativa correta:","options":{"A":"Os divertículos respondem por mais de 65% das hemorragias baixas volumosas.","B":"Entre os pacientes com divertículos, cerca de 50% irão experimentar um episódio de\nsangramento em suas vidas.","C":"Dos pacientes que sangram por divertículos, 2/3 apresentam sangramento volumoso.","D":"O Cólon direito é fonte do sangramento em 50% a 90% dos pacientes.","E":"O Cólon sigmoide é principal fonte de sangramento."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-199521","number":"199521","sourceNumber":"199521","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente de 16 anos relata dor constante na região inguinal direita, associada a\nnáuseas nas últimas 12 horas. Foi operado há\n5 anos de uma apendicite aguda complicada. Ao\nexame físico, apresenta tumoração inguinal irredutível e distensão abdominal discreta. Não há\nirritação peritoneal. Nessas circunstâncias, a conduta ADEQUADA consiste em:","options":{"A":"Cirurgia.","B":"Tomografia computadorizada de abdômen.","C":"Sedação inicial com morfina seguida de tentativa de redução da tumoração.","D":"Repouso absoluto, sonda nasogástrica e hidratação com correção hidroeletrolítica."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-212918","number":"212918","sourceNumber":"212918","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"O rastreamento de câncer cólon retal. por colonoscopia, é recomendado por várias\nsociedades internacionais como bom método para diminuir a incidência e a mortalidade do\nCarcinoma. Quais das alternativas a seguir está correta:","options":{"A":"Rastreamento está indicado em qualquer idade.","B":"Rastreamento de pessoas acima de 75 anos está contraindicado.","C":"Rastreamento em pessoas acima de 80 anos de idade é discutível.","D":"O rastreamento deve cessar a qualquer idade após 2 colonoscopia normais.","E":"Deve-se iniciar o rastreamento a partir de 40 anos."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-215101","number":"215101","sourceNumber":"215101","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Qual a conduta mais adequada em um paciente de 50 anos, hígido, portador de\nadenocarcinoma de reto baixo a 5 cm da borda anal com estadiamento clínico com ressonância\nmagnética e tomografia cT3cN1cMo?","options":{"A":"Amputação abdominoperineal do reto.","B":"Ressecção anterior do reto com anastomose colorretal baixa.","C":"Radioterapia e quimioterapia neoadjuvante com posterior ressecção anterior do reto com\nanastomose colorretal baixa.","D":"Ressecção anterior do reto com anastomose colorretal baixa seguido de radioterapia e\nquimioterapia adjuvante.","E":"Ressecção anterior do reto com colostomia terminal seguido de radioterapia e quimioterapia\nadjuvante."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-202757","number":"202757","sourceNumber":"202757","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Diverticulose colônica está presente em uma parcela significativa da população. Sobre\no sangramento digestivo decorrente dessa entidade\npatológica, podemos afirmar que:","options":{"A":"50% dos pacientes com diverticulose colônica apresentarão sangramento em algum momento\nde suas vidas.","B":"O melhor método de diagnóstico e tratamento é a arteriografia com embolização.","C":"50% é a taxa de mortalidade dos pacientes submetidos à colectomia subtotal de urgência.","D":"50% dos pacientes apresentarão ressangramento em um período de 10 anos.","E":"A localização do sítio de sangramento não é essencial."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-202760","number":"202760","sourceNumber":"202760","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"O achado de uma paciente com inúmeros pólipos colônicos e um meduloblastoma\ncerebelar sugere o diagnóstico de:","options":{"A":"Doença de Cowden.","B":"Sindrome de Turcot.","C":"Polipose Adenomatosa Familiar.","D":"Síndrome de Peutz Jeghers.","E":"Síndrome de Gardner."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-199577","number":"199577","sourceNumber":"199577","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente masculino, 20 anos, sem comorbidades, deu entrada no pronto-socorro com\ndor abdominal em andar inferior, na fossa\nilíaca direita, que vem piorando há dois dias, associado a\nhiporexia e parada de eliminação de flatos. Ao exame físico apresenta frequência cardíaca de 88\nbpm, frequência respiratória de 16 irpm, estável hemodinamicamente, com descompressão brusca\npositiva (blumberg positivo).O quadro se manteve apesar da analgesia e hidratação. Leucograma,\namilase, creatinina e íons normais. Radiografia de abdome normal. Qual a conduta mais adequada,\npensando no diagnóstico mais provável:","options":{"A":"Laparoscopia diagnóstica.","B":"Ressonância nuclear magnética de abdome.","C":"Internação, antibiótico e observação clínica.","D":"Alta com sintomáticos e retorno para reavaliação em 24 horas."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-199615","number":"199615","sourceNumber":"199615","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente gestante, no primeiro trimestre da gestação, após episódios de vômitos\npersistentes devido à hiperêmese gravídica, deu\nentrada no pronto-socorro apresentando\nhematêmese associada a sinais de choque grau I. Após estabilização do quadro hemodinâmico,\napresentou remissão dos sintomas. Feito a hipótese diagnóstica de síndrome de Mallory-Weiss.\nOptado pela realização de endoscopia. Qual o provável achado no exame endoscópico que\ncomprova o diagnóstico?","options":{"A":"Úlceras em corpo e antro gástrico.","B":"Laceração da mucosa em região de transição esofagogástrica.","C":"Lesão gástrica de provável etiologia neoplástica.","D":"Erosão de mucosa gástrica associado a malformação vascular em pequena curvatura."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-199588","number":"199588","sourceNumber":"199588","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Contribuem para o íleo pós-operatório, exceto:","options":{"A":"Manipulação cirúrgica de alças intestinais no intra-operatório.","B":"Restrição ao leito.","C":"Tempo cirúrgico prolongado.","D":"Uso de anestésicos não narcóticos."},"answer":"D","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-172744","number":"172744","sourceNumber":"172744","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Homem de 68 anos, hospitalizado para tratamento de pneumonia com ceftriaxone e\nclaritromicina, evoluiu com diarréia associada à antibioticoterapia, tendo sido associado\nmetronidazol ao esquema terapêutico com melhora do quadro. Três dias após a alta hospitalar o\npaciente retorna com diarréia, dor e distenção abdominal, desidratado, hipotenso, com leucocitose\ne neutrofilia ao hemograma. A tomografia computadorizada de abdome evidenciou espessamento\nda parede do reto e colon sigmóide e a retossigmoidoscopia mostrou eritema de mucosa. A\npesquisa de toxinas A e B do Clostridium difficile nas fezes foi negativa e a PCR para o mesmo\npatógeno foi positiva. Assinale o esquema de antibioticoterapia mais indicado para este caso.","options":{"A":"Piperacilina 4 g + tazobactam 0,5 g de 8 em 8 horas, por via endovenosa, durante 10 dias.","B":"Amoxicilina 500 mg + clavulanato 125 mg de 8 em 8 horas, por via oral, durante 10 dias.","C":"Vancomicina 250 mg de 6 em 6 horas, por via oral, durante 10 dias.","D":"Levofloxacino 500 mg por via oral a cada 24 horas, por 7 dias."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-188006","number":"188006","sourceNumber":"188006","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Mulher, 34 anos apresentando períodos de dor abdominal tipo cólica de leve a\nmoderada intensidade em hipogástrio associada a\ndiarreia intercalando períodos assintomáticos.\nEsse quadro surgiu há 4 meses e os sintomas estão mais frequentes e de maior intensidade. No\núltimo mês, apresentou perda ponderal, astenia e mal-estar. Hoje vem em consulta sem queixa\nálgica para nova avaliação e mostrar exames solicitados por outro médico. Exame físico abdominal\nnormal. Hemograma evidencia anemia sem leucocitose. Sorologia negativa para HIV, positiva para\nanticorpos anti-Saccharomyces cerevisiae (ASCA) e negativa para anticorpos perinuclear\n\nanti-citoplasma de neutrófilos (pANCA). Estudo radiológico com bário do intestino delgado revela\naparência de padrão de chão forrado com paralelepípedo em várias áreas de intestino delgado e\nsinais de úlceras lineares em íleo terminal. Tomografia computadorizada evidencia acentuado\nespessamento transmural de aspecto salteado em vários segmentos de intestino delgado. Qual é o\ndiagnóstico provável e a conduta indicada?","options":{"A":"Histoplasmose intestinal - Fluconazol oral.","B":"Infecção por Clostridium difficile - Vancomicina endovenoso ou metronidazol oral.","C":"Tuberculose intestinal - Ressecção intestinal e confecção de ileostomia.","D":"Síndrome de Peutz-Jeghers - Ressecção intestinal extensa.","E":"Doença inflamatória intestinal - Budesonida e metronidazol orais."},"answer":"E","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-172539","number":"172539","sourceNumber":"172539","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente sexo masculino, previamente hígido, 32 anos inicia quadro súbito de volumosa\nhematêmese, procurando atendimento em hospital de interior onde é inicialmente internado.\n\nRecebe além de cristalóides, omeprazol e sintomáticos, 2 concentrados de hemácias ainda no PS e\nsegue em observação até realizar\nendocospia (EDA) no final da tarde. Durante a observação não\napresenta novos episódios hematêmese. No final da tarde hemoglobina (Hb) 6g/dl e realiza EDA\nque não evidencia sangramento ativo. Permanece internado, apresentando melena volumosa e\nqueda seriada de Hb, recebendo um total de mais de 10 unidades de concentrados de hemácias,\nquando então é transferido ao HECI após cerca de 72 horas do início do quadro. Na admissão ao\nHECI palidez cutânea intensa, torporoso, pele fria, RCR 2t FC 145bpm, 90x60mmHg. Realizada\npassagem de sonda nasogástrica com drenagem de enorme quantidade de sangue vivo. Qual das\nabaixo é a melhor lista de opções iniciais?","options":{"A":"Punção de veia em antebraço com jelco 18, 1000ml de cristalóides, tipagem sanguínea,\nhemograma e coagulograma.","B":"Punção de jugular interna ou femural com cateter de 12fr (tipo hemodiálise), imediata transfusão\ncom O negativo, plasma, plaquetas e\ncristalóides, tipagem sangúinea e exames laboratoriais.","C":"Punção de jugular interna ou subclávia com cateter venoso central, imediata transfusão com O\nnegativo, plasma, plaquetas e cristalóides, tipagem sangúinea e exames laboratoriais.","D":"Punção de duas veias, uma em cada antebraço com jelco 18, 1000ml de cristalóides, tipagem\nsanguínea, hemograma e coagulograma e realização imediata de EDA,","E":"Punção de duas veias, uma em cada antebraço com jelco 18, 1000ml de cristalóides, tipagem\nsanguínea, hemograma e coagulograma."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-172554","number":"172554","sourceNumber":"172554","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente sexo masculino, previamente hígido, 32 anos inicia quadro súbito de volumosa\nhematêmese, procurando atendimento em hospital de interior onde é inicialmente internado.\n\nRecebe além de cristalóides, omeprazol e sintomáticos, 2 concentrados de hemácias ainda no PS e\nsegue em observação até realizar\nendocospia (EDA) no final da tarde. Durante a observação não\napresenta novos episódios hematêmese. No final da tarde hemoglobina (Hb) 6g/dl e realiza EDA\nque não evidencia sangramento ativo. Permanece internado, apresentando melena volumosa e\nqueda seriada de Hb, recebendo um total de mais de 10 unidades de concentrados de hemácias,\nquando então é transferido ao HECI após cerca de 72 horas do início do quadro. Na admissão ao\nHECI palidez cutânea intensa, torporoso, pele fria, RCR 2t FC 145bpm, 90x60mmHg. Realizada\npassagem de sonda nasogástrica com drenagem de enorme quantidade de sangue vivo. Esse\nmesmo paciente após a adoção das medidas que o emergencista julgou apropriada na questão\nanterior, ao ser realizada a EDA o endoscopista refere notar sangramento de aspecto arterial\nproveniente do duodeno distal, sem identificação exata do ponto do sangramento. Assim, além das\nmedidas de suporte apropriadas, qual dessas abaixo é a intervenção seqüencial mais adequada?","options":{"A":"Passagem imediata de balão de Sangstein-Blackmore.","B":"Esclerose com adrenalina nas proximidades do possível local do sangramento.","C":"Realizar colonoscopia imediatamente.","D":"Realizar cintilografia imediatamente para identificar local do sangramento.","E":"Realizar cirurgia de emergência para exploração do duodeno, identificação local sangrante e\ncontrole cirúrgico do sangramento."},"answer":"E","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-172774","number":"172774","sourceNumber":"172774","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente de 25 anos, sexo masculino, há 4 meses apresentando quadro de dor\nabdominal, geralmente em quadrante inferior\ndireito, quase diária, associada à diarreia, cerca de 10\nepisódios por dia, com fezes líquidas, sem elementos anormais, fadiga e emagrecimento de 10 kg\nnesse período. Refere ainda saída de secreção fluida/purulenta por pequeno orifício em região\nperianal. Relata que na última semana vem apresentando piora da dor abdominal, associada à\nfebre (39-39,5°C). Ao exame físico apresenta dor importante à palpação em quadrante inferior\ndireito, com descompressão dolorosa. Diante do quadro clínico exposto, qual a principal hipótese\ndiagnóstica?","options":{"A":"Síndrome da imunodeficiência adquirida associada à tuberculose intestinal.","B":"Retocolite ulcerativa complicada com megacólon tóxico.","C":"Doença de Crohn complicada com abscesso em íleo terminal.","D":"Doença diverticular complicada com diverticulite aguda."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-174376","number":"174376","sourceNumber":"174376","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Qual das seguintes afirmações com relação à polipose adenomatose familiar (FAP) é\nfalsa?","options":{"A":"O portador da mutação do gene APC tem 100% de probabilidade de desenvolver câncer\ncolorretal.","B":"Ela é uma doença autossômica dominante.","C":"É caracterizada pela presença de 100 ou mais pólipos adenomatosos no colon e reto.","D":"O desenvolvimento do câncer colorretal é inevitável na ausência de colectomia.","E":"Ela conta para, aproximadamente, 5% dos casos de câncer colorretal."},"answer":"E","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-174390","number":"174390","sourceNumber":"174390","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Homem 25 anos, apresenta diarréia com sangue há 2 meses. Colonoscopia evidencia\nmucosa de reto e sigmoide distal de aspecto enentematoso e friável ao toque do aparelho, com\npequenas ulcerações rasas; cujas biópsias\n\ndemonstraram retite crônica com depleção de células caliciformes e formação de microabscessos\nde cripta. Em relação ao diagnóstico mais\nprovável neste doente, são apresentadas as seguintes\nafirmações: I- Avaliação complementar do intestino delgado é desnecessária neste caso.; II- A\ndroga de primeira escolha para o início do tratamento é a prednisona.; III- É necessário usar\nantibiótico no início do tratamento pelo achado histopatológico de retite e microabscessos de\ncripta.\nAssinale a alternativa correta:","options":{"A":"Apenas I.","B":"Apenas II.","C":"Apenas III.","D":"Apenas I e III.","E":"Todas estão corretas."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-174354","number":"174354","sourceNumber":"174354","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Paciente com história de hemorragia digestiva alta de grande volume é submetido à\nendoscopia digestiva alta, em que se evidencia úlcera com sangramento ativo e não pulsátil. Qual a\nclassificação de Forrest?","options":{"A":"Grau Ia.","B":"Grau Ib.","C":"Grau IIa.","D":"Grau IIb.","E":"Grau III."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-187491","number":"187491","sourceNumber":"187491","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Sobre abdome agudo obstrutivo é CORRETO afirmar, exceto:","options":{"A":"A radiografia de abdome agudo (abdome em pé e deitado + cúpulas diafragmáticas) é\nconsiderado o exame de imagem inicial, podendo inclusive indicar o tratamento.","B":"Vômitos fecaloides indicam fatores obstrutivos proximais.","C":"Casos de obstrução de cólon em pacientes com a válvula ileocecal competente podem tornar-se\npotencialmente mais graves.","D":"Sinal de empilhamento de moedas e 02 ou mais níveis hidroaéreos são indicativos de obstrução.","E":"As etiologias mais comuns são: hérnias, aderências e neoplasias."},"answer":"B","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-172837","number":"172837","sourceNumber":"172837","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Lactente de um ano e meio chegou ao pronto socorro desidratado e com história de ter\niniciado há dois dias diarreia, vômito e febre alta. A diarreia ocorre várias vezes por dia, com\nfezes\nlíquidas, volumosas, amareladas, com caráter explosivo e com grande perda hidroeletrolítica. Qual\né o provável agente etiológico e/ou a conduta a ser prescrita?","options":{"A":"Provavelmente a diarreia é viral e pela clínica, os adenovírus entéricos são a causa mais\nprovável.","B":"Provavelmente a diarreia é causada por agentes parasitários e o mais frequentemente envolvido\né a Entamoeba histolytica.","C":"Provavelmente a diarreia é por rotavírus, que é o principal responsável por episódios de diarreia\naguda, tanto nos países desenvolvidos como naqueles em desenvolvimento, representando 40%\ndos casos graves com hospitalização.","D":"Provavelmente a diarreia é por Shigella. Hidratação venosa e ceftriaxona devem ser prescritas\nimediatamente."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-172763","number":"172763","sourceNumber":"172763","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Em relação ao câncer colorretal hereditário, é INCORRETO afirmar que:","options":{"A":"A síndrome de Peutz-Jeghers caracteriza-se pela presença de pólipos adenomatosos no trato\nintestinal e hiperpigmentação da mucosa bucal, lábios e dedos.","B":"A polipose adenomatosa familiar ocorre por uma mutação no gene APC.","C":"A síndrome de Turcot caracteriza-se pela presença de pólipos colorretais e tumores do sistema\nnervoso central.","D":"A síndrome de Lynch ocorre por uma disfunção no mecanismo de reparo do DNA (MMR)."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-172772","number":"172772","sourceNumber":"172772","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Sobre as hemorragias digestivas baixas, assinale a alternativa incorreta.","options":{"A":"Hemorragia digestiva baixa é definida como um sangramento originário distalmente à válvula\nileocecal.","B":"A taxa de ressangramento após o primeiro episódio de hemorragia por doença diverticular é de\naproximadamente 25%.","C":"Endoclipes podem ser utilizados no tratamento endoscópico do sangramento por divertículo do\ncólon sigmóide.","D":"Embolização superseletiva ocorre ao nível dos vasa recta ou da artéria marginal."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-172796","number":"172796","sourceNumber":"172796","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Em relação a imagem abaixo podemos afirmar:","options":{"A":"Trata-se de um volvo de sigmoide.","B":"A colonoscopia está contra-indicada nesses casos.","C":"Trata-se de um tumor de reto obstrutivo.","D":"A tomografia é o melhor exame para elucidação do diagnóstico."},"answer":"A","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-2/172796.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-2-162594","number":"162594","sourceNumber":"162594","collectionBlock":"medcurso:medcurso-gastrologia-gas-2","collectionLabel":"Medcurso · GAS 2","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 2","subtopic":"","stem":"Assinale a alternativa CORRETA em relação à doença celíaca:","options":{"A":"O HLA B27 é um importante fator de risco para a doença.","B":"A detecção dos anticorpos IgA antitransglutaminase é útil nos pacientes portadores de\ndeficiência seletiva\n\nde imunoglobulina A.","C":"Osteopenia é encontrada em mais da metade dos pacientes.","D":"Linfoma do manto intestinal é uma complicação comum de pacientes que não aderem à dieta\nsem glúten.","E":"A biópsia duodenal revela infiltração da lâmina própria por eosinófilos."},"answer":"C","source":"Gastrologia/GAS 2/GAS 2.txt","sourceLabel":"Medcurso · GAS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
